  "глина": "Значење: Врста земље која се користи за грнчарију и обликовање.\n\nГраматика: Именица; генитив; једнина.",
  "глине": "Значење: Врста земље која се користи за грнчарију и обликовање.\n\nГраматика: Именица; глина; женски род; номинатив; множина.",
  "глува": "Значење: Који не чује.\n\nГраматика: Придев; глув; женски род; генитив; једнина.",
