  "глуму": "Значење: Уметност представљања лика на сцени, филму или телевизији.\n\nГраматика: Именица; глума; женски род; датив.",
  "глупа": "Значење: Неразумна или бесмислена.\n\nГраматика: Придев; глуп; женски род; генитив; једнина.",
