  "глупи": "Значење: Неразуман или непромишљен.\n\nГраматика: Придев; глуп; мушки род; номинатив; множина.",
  "глупо": "Значење: На неразуман или бесмислен начин.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "глупу": "Значење: Неразуман или непромишљен.\n\nГраматика: Придев; глуп; женски род; датив.",
