  "гњидо": "Значење: Вокатив речи гњида; погрдно обраћање.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "говна": "Значење: Вулгаран назив за измет; користи се и као груба увреда.\n\nГраматика: Именица; генитив; једнина.",
