  "говор": "Значење: Способност или чин говорења; јавни наступ или језички израз.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "годиш": "Значење: Пријаш или одговараш.\n\nГраматика: Глагол; презент; 2. лице; једнина.",
  "гозба": "Значење: Свечани обед са много хране и пића.\n\nГраматика: Именица; генитив; једнина.",
  "гозбе": "Значење: Свечани обед са много хране и пића.\n\nГраматика: Именица; гозба; женски род; номинатив; множина.",
  "гозби": "Значење: Свечани обед са много хране и пића.\n\nГраматика: Именица; гозба; женски род; номинатив; множина.",
  "гозбу": "Значење: Гозба; свечани оброк са много јела и гостију.\n\nГраматика: Именица; акузатив.",
