  "голуб": "Значење: Птица кратког кљуна, често симбол мира и благости.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "голфа": "Значење: Голф; спорт са палицом и лоптицом.\n\nГраматика: Именица; голф; мушки род; генитив; једнина.",
  "голфу": "Значење: Голф; спорт у ком се лоптица палицом убацује у рупу.\n\nГраматика: Именица; голф; мушки род; датив.",
  "горак": "Значење: Који има непријатан, опор укус; може значити и тежак или болан.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "горде": "Значење: Поносне, охоле или уздигнутог држања.\n\nГраматика: Именица; номинатив; множина.",
  "горди": "Значење: Поносити, узвишени или охоли.\n\nГраматика: Именица; номинатив; множина.",
