  "горег": "Значење: Гори; лошији од нечега другог.\n\nГраматика: Именица; гори; мушки род; генитив.",
  "горем": "Значење: Гори; у лошијем стању или неповољнијој прилици.\n\nГраматика: Именица; гори; мушки род; инструментал.",
  "горео": "Значење: Био у пламену или јако сијао.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
  "горим": "Значење: Пламтим или осећам јаку унутрашњу напетост.\n\nГраматика: Глагол; презент; 1. лице; једнина.",
  "горих": "Значење: Лошијих или неповољнијих.\n\nГраматика: Придев; гори; мушки род; генитив; множина.",
