  "грана": "Значење: Део дрвета који израста из стабла; може значити и област рада.\n\nГраматика: Именица; генитив; једнина.",
  "гране": "Значење: Део дрвета који израста из стабла; може значити и област рада.\n\nГраматика: Именица; грана; женски род; номинатив; множина.",
  "грани": "Значење: Део дрвета који израста из стабла; може значити и област рада.\n\nГраматика: Именица; грана; женски род; номинатив; множина.",
  "грану": "Значење: Део дрвета који израста из стабла; може значити и област рада.\n\nГраматика: Именица; грана; женски род; датив.",
