  "дечје": "Значење: Средњи род или множина придева дечји.\n\nГраматика: Именица; номинатив; множина.",
  "дечји": "Значење: Који припада деци или је намењен деци.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "дечју": "Значење: Који припада деци или је намењен деци.\n\nГраматика: Именица; дечји; мушки род; акузатив.",
  "дечка": "Значење: Младић или нечији момак.\n\nГраматика: Именица; дечко; средњи род; генитив; једнина.",
  "дечке": "Значење: Младић или нечији момак.\n\nГраматика: Именица; дечко; средњи род; номинатив; множина.",
  "дечки": "Значење: Момци или младићи; разговорни облик за дечаке.\n\nГраматика: Именица; номинатив; множина.",
  "дечко": "Значење: Младић или нечији момак.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "дечку": "Значење: Младић или нечији момак.\n\nГраматика: Именица; дечко; средњи род; акузатив.",
  "диван": "Значење: Леп, пријатан или изузетан; може значити и лежај за седење.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "дивим": "Значење: Осећам велико поштовање или одушевљење.\n\nГраматика: Глагол; презент; 1. лице; једнина.",
  "дивио": "Значење: Осећао је поштовање или одушевљење.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
