  "дивља": "Значење: Неукроћена, природна или необуздана.\n\nГраматика: Придев; дивљи; женски род; генитив; једнина.",
  "дивље": "Значење: Средњи род или множина речи дивљи; неукроћено или природно.\n\nГраматика: Именица; номинатив; множина.",
  "дивљи": "Значење: Који није питом, уређен или обуздан.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
  "дивљу": "Значење: Који није питом, уређен или обуздан.\n\nГраматика: Именица; дивљи; мушки род; датив.",
