  "дивне": "Значење: Леп, пријатан или изузетан; може значити и лежај за седење.\n\nГраматика: Именица; диван; мушки род; номинатив; множина.",
  "дивни": "Значење: Леп, пријатан или изузетан; може значити и лежај за седење.\n\nГраматика: Именица; диван; мушки род; номинатив; множина.",
