  "дигао": "Значење: Подигао или померио навише.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
  "дигла": "Значење: Подигла или померила навише.\n\nГраматика: Глагол; прошло време; l-облик; женски род; једнина.",
  "дигли": "Значење: Подигли или померили навише.\n\nГраматика: Глагол; презент; 3. лице; једнина.",
  "дигне": "Значење: Подигне или помери навише.\n\nГраматика: Глагол; презент; 3. лице; множина.",
