  "дизао": "Значење: Подизао или померао навише.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
  "дизел": "Значење: Врста горива или мотор који користи такво гориво.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "дизна": "Значење: Мали отвор или наставак кроз који се усмерава млаз течности, гаса или горива.\n\nГраматика: Именица; генитив; једнина.",
  "дилдо": "Значење: Предмет намењен сексуалној употреби; реч за одрасле.\n\nГраматика: Именица; номинатив; једнина; средњи род.",
  "дилер": "Значење: Особа која продаје или посредује у продаји; у жаргону често препродавац.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
