  "длаке": "Значење: Танка нит која расте на кожи човека или животиње.\n\nГраматика: Именица; длака; женски род; номинатив; множина.",
  "длаку": "Значење: Танка нит која расте на кожи човека или животиње.\n\nГраматика: Именица; длака; женски род; акузатив.",
