  "добро": "Значење: Оно што је исправно, корисно или повољно; може значити и стање без проблема.\n\nГраматика: Прилог.",
  "добру": "Значење: Онај који има добре особине, квалитет или понашање.\n\nГраматика: Именица; добар; мушки род; датив.",
