  "додир": "Значење: Лаган контакт руком, предметом или површином.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "додох": "Значење: Стигао је; дошао.\n\nГраматика: Глагол; доћи; прошло време (аорист); 1. лице; једнина.",
