  "дојам": "Значење: Утисак који нешто оставља.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "дојка": "Значење: Жлездани део тела код човека и сисара; код жене служи за дојење.\n\nГраматика: Именица; генитив; једнина.",
