  "домар": "Значење: Особа која брине о згради, реду и одржавању.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "домет": "Значење: Највећа удаљеност или могућност до које нешто досеже.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "домом": "Значење: Дом; кућом или местом становања.\n\nГраматика: Именица; дом; мушки род; инструментал.",
