  "доном": "Значење: Дон; титула, име реке или облик властитог назива.\n\nГраматика: Именица; дон; мушки род; инструментал.",
  "донор": "Значење: Особа која даје крв, орган, новац или нешто друго за помоћ.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "доњег": "Значење: Оног који је ниже или испод.\n\nГраматика: Придев; доњи; мушки род; генитив.",
  "доњем": "Значење: Доњи; ниж или оном испод.\n\nГраматика: Именица; доњи; мушки род; инструментал.",
  "доњим": "Значење: Доњи; нижим или онима испод.\n\nГраматика: Именица; доњи; мушки род; инструментал.",
  "доњој": "Значење: Оној која је ниже или испод.\n\nГраматика: Придев; доњи; женски род; датив.",
  "допао": "Значење: Свидео се или запао у неко стање.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
  "допис": "Значење: Писано обавештење, службено писмо или кратак текст.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "допре": "Значење: Стигне до некога или нечега.\n\nГраматика: Глагол; презент; 3. лице; множина.",
