  "замак": "Значење: Тврђава или велика стара грађевина; може значити и механизам за закључавање.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "замах": "Значење: Покрет руком или телом пре удара; снажан почетни покрет.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "замка": "Значење: Клопка или лукаво припремљена опасност.\n\nГраматика: Именица; генитив; једнина.",
  "замке": "Значење: Клопка или лукаво припремљена опасност.\n\nГраматика: Именица; замка; женски род; номинатив; множина.",
  "замки": "Значење: Клопка или лукаво припремљена опасност.\n\nГраматика: Именица; замка; женски род; номинатив; множина.",
  "замку": "Значење: Клопка или лукаво припремљена опасност.\n\nГраматика: Именица; замка; женски род; акузатив.",
  "замци": "Значење: Клопка или лукаво припремљена опасност.\n\nГраматика: Именица; замка; женски род; номинатив; множина.",
  "занат": "Значење: Вештина или занимање које се учи радом.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "запад": "Значење: Страна света где сунце залази; западни правац или област.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "запао": "Значење: Доспео у неко стање или положај.\n\nГраматика: Глагол; прошло време; l-облик; мушки род; једнина.",
