  "зачас": "Значење: Врло брзо, за кратко време.\n\nГраматика: Именица; номинатив; једнина; мушки род.",
  "зачин": "Значење: Додатак храни који јој даје мирис и укус.\n\nГраматика: Придев; мушки род; номинатив; једнина.",
