  "збиља": "Значење: Истина, стварност; такође значи озбиљно.\n\nГраматика: Именица; генитив; једнина.",
  "збрка": "Значење: Неред, пометња или збуњујућа ситуација.\n\nГраматика: Именица; генитив; једнина.",
  "збрке": "Значење: Неред, пометња или збуњујућа ситуација.\n\nГраматика: Именица; збрка; женски род; номинатив; множина.",
  "збрку": "Значење: Неред, пометња или збуњујућа ситуација.\n\nГраматика: Именица; збрка; женски род; акузатив.",
