function emptyLectorStats() {
  return { total: 0, add: 0, remove: 0, updated_at: "" };
}

function loadLectorStats() {
  try {
    return { ...emptyLectorStats(), ...JSON.parse(localStorage.getItem(LECTOR_STATS_KEY) || "{}") };
  } catch {
    return emptyLectorStats();
  }
}

function saveLectorStats(stats) {
  localStorage.setItem(LECTOR_STATS_KEY, JSON.stringify(stats));
}

async function submitLectorStats(stats = loadLectorStats()) {
  if (!supabaseConfigured()) return false;
  const response = await fetch(supabaseUrl(`${lectorStatsTable()}?on_conflict=device_id`), {
    method: "POST",
    headers: supabaseJsonHeaders({ Prefer: "resolution=merge-duplicates,return=minimal" }),
    body: JSON.stringify({
      nickname: loadPlayerName() || "Играч",
      device_id: deviceId(),
      total: Number(stats.total) || 0,
      add_count: Number(stats.add) || 0,
      remove_count: Number(stats.remove) || 0,
      updated_at: stats.updated_at || new Date().toISOString()
    })
  });
  return response.ok;
}

function bumpLectorStats(action) {
  const stats = loadLectorStats();
  stats.total += 1;
  if (action === "add") stats.add += 1;
  if (action === "remove") stats.remove += 1;
  stats.updated_at = new Date().toISOString();
  saveLectorStats(stats);
  submitLectorStats(stats).catch(() => {});
}

async function submitWordReport(word, action, source) {
  if (!supabaseConfigured() || !word) return false;
  const response = await fetch(supabaseUrl(wordReportsTable()), {
    method: "POST",
    headers: supabaseJsonHeaders({ Prefer: "return=minimal" }),
    body: JSON.stringify({
      word,
      action,
      source,
      nickname: loadPlayerName() || "Играч",
      device_id: deviceId()
    })
  });
  if (response.ok) bumpLectorStats(action);
  return response.ok;
}

async function fetchWordReportsRows() {
  if (!supabaseConfigured()) return [];
  const query = [
    "select=created_at,word,action,nickname",
    "order=created_at.desc",
    "limit=1000"
  ].join("&");
  const response = await fetch(supabaseUrl(`${wordReportsTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return [];
  const rows = await response.json();
  return Array.isArray(rows) ? rows : [];
}

async function fetchLectorStatsRows() {
  if (!supabaseConfigured()) return [];
  const query = [
    "select=nickname,total,add_count,remove_count,updated_at",
    "order=updated_at.desc",
    "limit=1000"
  ].join("&");
  const response = await fetch(supabaseUrl(`${lectorStatsTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return [];
  const rows = await response.json();
  return Array.isArray(rows) ? rows : [];
}

function lectorStats(rows = []) {
  const byName = new Map();
  rows
    .filter((row) => row.action === "add" || row.action === "remove")
    .forEach((row) => {
      const nickname = (row.nickname || "Играч").trim() || "Играч";
      if (!byName.has(nickname)) {
        byName.set(nickname, { nickname, total: 0, add: 0, remove: 0, lastAt: "" });
      }
      const entry = byName.get(nickname);
      entry.total += 1;
      if (row.action === "add") entry.add += 1;
      if (row.action === "remove") entry.remove += 1;
      if (!entry.lastAt || Date.parse(row.created_at || "") > Date.parse(entry.lastAt || "")) {
        entry.lastAt = row.created_at || "";
      }
    });
  return [...byName.values()];
}

function lectorStatsPersistent(rows = []) {
  const byName = new Map();
  rows.forEach((row) => {
    const hasTotal = row.total !== undefined || row.add_count !== undefined || row.remove_count !== undefined;
    if (!hasTotal && row.action !== "add" && row.action !== "remove") return;
    const nickname = (row.nickname || "Играч").trim() || "Играч";
    if (!byName.has(nickname)) {
      byName.set(nickname, { nickname, total: 0, add: 0, remove: 0, lastAt: "" });
    }
    const entry = byName.get(nickname);
    if (hasTotal) {
      entry.total += Number(row.total) || 0;
      entry.add += Number(row.add_count) || 0;
      entry.remove += Number(row.remove_count) || 0;
    } else {
      entry.total += 1;
      if (row.action === "add") entry.add += 1;
      if (row.action === "remove") entry.remove += 1;
    }
    const lastAt = row.updated_at || row.created_at || "";
    if (!entry.lastAt || Date.parse(lastAt || "") > Date.parse(entry.lastAt || "")) {
      entry.lastAt = lastAt;
    }
  });
  return [...byName.values()];
}

function wordMeaningHasGrammar(text) {
  return /\n\nГраматика:\s*\S/u.test(String(text || ""));
}

function mergeWordMeaning(existing = "", incoming = "") {
  const left = String(existing || "").trim();
  const right = String(incoming || "").trim();
  if (!left) return right;
  if (!right) return left;
  const leftHasGrammar = wordMeaningHasGrammar(left);
  const rightHasGrammar = wordMeaningHasGrammar(right);
  if (leftHasGrammar && !rightHasGrammar) return left;
  if (rightHasGrammar && !leftHasGrammar) return right;
  return right.length > left.length ? right : left;
}

function embeddedWordMeaning(word) {
  return mergeWordMeaning(BOOTSTRAP_WORD_INFO[word], WORD_INFO[word]);
}

function markWordVerified(word, verified = true) {
  const clean = normalize(word);
  if (!clean) return;
  if (verified) WORD_VERIFIED.add(clean);
  else WORD_VERIFIED.delete(clean);
}

function isWordVerified(word) {
  return WORD_VERIFIED.has(normalize(word));
}

function markWordVerifiedFromRow(word, row) {
  if (!word || !row) return;
  markWordVerified(word, row.verified === true || row.verified === "true");
}

function setWordModalVerifiedMark(word = "", { editable = false } = {}) {
  const verified = Boolean(word && isWordVerified(word));
  if (wordModalWord) {
    wordModalWord.classList.toggle("is-verified", verified);
    wordModalWord.setAttribute("data-verified", verified ? "true" : "false");
  }
  if (!wordModalVerifyStar) return;
  const show = Boolean(word);
  const canToggle = Boolean(show && editable && wordEditorAllowed);
  wordModalVerifyStar.hidden = !show;
  wordModalVerifyStar.textContent = verified ? "★" : "☆";
  wordModalVerifyStar.classList.toggle("is-verified", verified);
  wordModalVerifyStar.classList.toggle("is-editable", canToggle);
  wordModalVerifyStar.disabled = !canToggle;
  wordModalVerifyStar.setAttribute("aria-pressed", verified ? "true" : "false");
  wordModalVerifyStar.title = !show
    ? ""
    : canToggle
      ? (verified ? "Верификовано — кликни да поништиш" : "Кликни звездицу ако је све исправно")
      : (verified ? "Објашњење је верификовано" : "Објашњење још није верификовано");
}

async function setWordVerifiedRemote(word, verified) {
  if (!supabaseConfigured() || !wordEditorAllowed) return { ok: false, error: "forbidden" };
  const response = await fetch(supabaseUrl("rpc/set_word_verified"), {
    method: "POST",
    headers: supabaseJsonHeaders(),
    body: JSON.stringify({
      p_word: word,
      p_verified: Boolean(verified),
      p_nickname: normalizePlayerName(loadPlayerName() || ""),
      p_device_id: deviceId()
    })
  });
  if (!response.ok) return { ok: false, error: "request_failed" };
  const payload = await response.json().catch(() => ({}));
  if (!payload?.ok) return payload || { ok: false, error: "forbidden" };
  return { ok: true, verified: Boolean(verified) };
}

async function handleWordModalVerifyToggle() {
  const word = wordModalCurrentWord;
  if (!word || !wordEditorAllowed || !wordModalMeaningEditable) return;
  const next = !isWordVerified(word);
  if (wordModalVerifyStar) wordModalVerifyStar.disabled = true;
  const result = await setWordVerifiedRemote(word, next).catch(() => ({ ok: false }));
  if (!result?.ok) {
    setWordModalVerifiedMark(word, { editable: true });
    messageEl.textContent = result?.error === "forbidden"
      ? "Немаш дозволу за верификацију."
      : "Верификација није успела.";
    return;
  }
  markWordVerified(word, next);
  if (next) {
    applyVerifiedWordReviewChrome(word);
    messageEl.textContent = "Реч је верификована.";
  } else {
    if (wordReviewText) {
      wordReviewText.textContent = "Да ли је ова реч сувишна, непримерена или неисправна и треба да се уклони?";
      wordReviewText.hidden = false;
    }
    setWordModalButtons(wordReviewRemoveButtons(word));
    setWordModalVerifiedMark(word, { editable: true });
    setWordModalEditLink(true, true);
    messageEl.textContent = "Верификација је поништена.";
  }
}

async function fetchWordMeaning(word) {
  if (!word) return "";
  let meaning = embeddedWordMeaning(word);
  if (!supabaseConfigured()) {
    if (meaning) WORD_INFO[word] = meaning;
    return meaning || "";
  }

  const query = `${wordsTable()}?select=meaning,verified,created_at,updated_at&word=eq.${encodeURIComponent(word)}&active=eq.true&limit=1`;
  const response = await fetch(supabaseUrl(query), {
    headers: supabaseHeaders()
  });
  if (!response.ok) {
    // Starija baza bez kolone verified — probaj bez nje.
    const fallback = await fetch(
      supabaseUrl(`${wordsTable()}?select=meaning,created_at,updated_at&word=eq.${encodeURIComponent(word)}&active=eq.true&limit=1`),
      { headers: supabaseHeaders() }
    ).catch(() => null);
    if (!fallback?.ok) {
      if (meaning) WORD_INFO[word] = meaning;
      return meaning || "";
    }
    const fallbackRows = await fallback.json();
    const remoteFallback = String(fallbackRows?.[0]?.meaning || "").trim();
    if (remoteFallback) meaning = remoteFallback;
    else meaning = mergeWordMeaning(meaning, remoteFallback);
    if (meaning) WORD_INFO[word] = meaning;
    markWordVerifiedFromRow(word, fallbackRows?.[0]);
    return meaning;
  }

  const rows = await response.json();
  const remote = String(rows?.[0]?.meaning || "").trim();
  // Baza je izvor istine posle uređivanja — ne zadržavaj ugrađeni tekst.
  if (remote) meaning = remote;
  if (meaning) WORD_INFO[word] = meaning;
  markWordVerifiedFromRow(word, rows?.[0]);
  return meaning;
}

function normalizeOnlineWordRows(rows = []) {
  const byWord = new Map();
  (Array.isArray(rows) ? rows : []).forEach((row) => {
    const word = normalize(row?.word || row);
    if (word.length !== WORD_LENGTH || byWord.has(word)) return;
    byWord.set(word, {
      word,
      meaning: String(row?.meaning || "").trim(),
      type: String(row?.type || "").trim()
    });
  });
  return [...byWord.values()].sort((left, right) => left.word.localeCompare(right.word, "sr"));
}

function isKnownWord(word = "") {
  const cleanWord = normalize(word);
  if (WORD_SET.has(cleanWord)) return true;
  return LOCAL_WORD_SET.has(cleanWord);
}

function applyOnlineWords(rows = [], cache = false) {
  const normalizedRows = normalizeOnlineWordRows(rows);
  if (normalizedRows.length < MIN_ONLINE_WORDS) {
    onlineWordsReady = false;
    WORDS = [...LOCAL_WORDS];
    WORD_SET = new Set(LOCAL_WORD_SET);
    if (cache) localStorage.removeItem(ONLINE_WORDS_KEY);
    return false;
  }
  const mergedWords = new Map(LOCAL_WORDS.map((word) => [word, word]));
  normalizedRows.forEach((row) => mergedWords.set(row.word, row.word));
  WORDS = [...mergedWords.values()].sort((left, right) => left.localeCompare(right, "sr"));
  WORD_SET = new Set(WORDS);
  onlineWordsReady = true;
  normalizedRows.forEach((row) => {
    if (!row.meaning) return;
    WORD_INFO[row.word] = mergeWordMeaning(BOOTSTRAP_WORD_INFO[row.word], row.meaning);
  });
  saveWordDeck(loadWordDeck());
  if (cache) {
    localStorage.setItem(ONLINE_WORDS_KEY, JSON.stringify({
      savedAt: new Date().toISOString(),
      rows: normalizedRows
    }));
  }
  return true;
}

function loadCachedOnlineWords() {
  try {
    const data = JSON.parse(localStorage.getItem(ONLINE_WORDS_KEY) || "null");
    return applyOnlineWords(data?.rows || [], false);
  } catch {
    return false;
  }
}

function loadOnlineWords() {
  // Rečnik je u igri (WORDS + WORD_INFO). Ne skidamo celu tabelu iz Supabase.
  loadCachedOnlineWords();
}

function challengeCode() {
  return Math.random().toString(36).replace(/[^a-z0-9]/gi, "").slice(2, 8).toUpperCase();
}

function challengeUrl(code) {
  const url = new URL(window.location.href);
  url.searchParams.set("challenge", code);
  return url.toString();
}

function challengeIsActive(row) {
  if (playedChallenge(row)) return false;
  const status = String(row?.status || "").toLowerCase();
  const witchHuntOpen = challengeIsWitchHuntRow(row)
    && isWeekendWitchActive()
    && challengeIsCurrentWitchHuntRow(row);
  const statusOk = status === "accepted" || (status === "played" && witchHuntOpen);
  if (!statusOk) return false;
  if (challengePausedForWitchHunt(row)) return false;
  const until = challengeActiveUntil(row);
  return !until || Date.now() < until;
}

function loadManualChallengeCredit() {
  try {
    return Math.max(0, Number(localStorage.getItem(CHALLENGE_MANUAL_CREDIT_KEY)) || 0);
  } catch {
    return 0;
  }
}

async function refreshManualChallengeCredit() {
  if (!supabaseConfigured() || !profileDeviceId()) return loadManualChallengeCredit();
  const query = [
    "select=challenge_bonus",
    `device_id=eq.${encodeURIComponent(profileDeviceId())}`,
    "limit=1"
  ].join("&");
  const response = await fetch(supabaseUrl(`${playersTable()}?${query}`), { headers: supabaseHeaders() });
  if (!response.ok) return loadManualChallengeCredit();
  const rows = await response.json();
  const credit = Math.max(0, Number(rows?.[0]?.challenge_bonus) || 0);
  localStorage.setItem(CHALLENGE_MANUAL_CREDIT_KEY, String(credit));
  updateChallengeQuota();
  return credit;
}

function challengeCardState(row) {
  if (playedChallenge(row)) return "played";
  if (challengeIsActive(row)) return "accepted";
  return "pending";
}

function weekendWitchWindowContaining(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  const day = date.getDay();
  if (day !== 0 && day !== 6) return null;
  const start = new Date(date);
  start.setHours(0, 0, 0, 0);
  if (day === 0) start.setDate(start.getDate() - 1);
  const end = new Date(start);
  end.setDate(end.getDate() + 2);
  return { start: start.getTime(), end: end.getTime() };
}

function challengeIsWitchHuntRow(row) {
  return Boolean(weekendWitchWindowContaining(row?.created_at || row?.day));
}

function challengeIsCurrentWitchHuntRow(row) {
  const window = weekendWitchWindowContaining(new Date());
  const createdAt = Date.parse(row?.created_at || row?.day || "");
  return Boolean(window && Number.isFinite(createdAt) && createdAt >= window.start && createdAt < window.end);
}

function challengePausedForWitchHunt(row, now = new Date()) {
  return isWeekendWitchActive(now) && !challengeIsWitchHuntRow(row);
}

function pausedWitchHuntTimeBetween(start, end) {
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) return 0;
  let paused = 0;
  const cursor = new Date(start);
  cursor.setHours(0, 0, 0, 0);
  cursor.setDate(cursor.getDate() - 1);
  while (cursor.getTime() < end) {
    const window = weekendWitchWindowContaining(cursor);
    if (window) {
      paused += Math.max(0, Math.min(end, window.end) - Math.max(start, window.start));
      cursor.setDate(cursor.getDate() + 2);
    } else {
      cursor.setDate(cursor.getDate() + 1);
    }
  }
  return paused;
}

function challengeDeadlineWithWeekendPause(base, duration, row) {
  if (!Number.isFinite(base)) return 0;
  if (challengeIsWitchHuntRow(row)) return base + duration;
  let deadline = base + duration;
  for (let attempt = 0; attempt < 8; attempt += 1) {
    const extended = base + duration + pausedWitchHuntTimeBetween(base, deadline);
    if (extended === deadline) break;
    deadline = extended;
  }
  return deadline;
}

function challengePendingDuration(row) {
  return challengeIsWitchHuntRow(row) ? CHALLENGE_WITCH_PENDING_MS : CHALLENGE_PENDING_MS;
}

function challengeActiveUntil(row) {
  const accepted = Date.parse(row?.accepted_at || "");
  const created = Date.parse(row?.created_at || "");
  const base = Number.isFinite(accepted) ? accepted : created;
  // Witch Hunt zelena kartica važi do kraja vikenda (sub–ned).
  if (challengeIsWitchHuntRow(row)) {
    const window = weekendWitchWindowContaining(row?.created_at || row?.day || new Date());
    if (window) return window.end;
  }
  return challengeDeadlineWithWeekendPause(base, CHALLENGE_ACTIVE_MS, row);
}

function challengePendingUntil(row) {
  const created = Date.parse(row?.created_at || "");
  if (!Number.isFinite(created)) return 0;
  const duration = challengePendingDuration(row);
  // Witch Hunt žute: 48h, bez pauze radnim danom (nastaju subotom/nedeljom).
  if (challengeIsWitchHuntRow(row)) return created + duration;
  return challengeDeadlineWithWeekendPause(created, duration, row);
}

function challengePlayedVisibleUntil(row) {
  const playedAt = challengePlayedSortTime(row);
  if (!Number.isFinite(playedAt)) return 0;
  return challengeDeadlineWithWeekendPause(playedAt, CHALLENGE_PLAYED_DISPLAY_MS, row);
}

function challengePendingExpired(row) {
  if (row?.status !== "pending" || row?.opponent_device || row?.accepted_at) return false;
  // Witch Hunt žute: važe 48h i ne brišu se tokom lova; posle vikenda više ne važe.
  if (challengeIsWitchHuntRow(row)) {
    if (isWeekendWitchActive() && challengeIsCurrentWitchHuntRow(row)) return false;
    const until = challengePendingUntil(row);
    return !until || Date.now() >= until;
  }
  if (challengePausedForWitchHunt(row)) return false;
  const until = challengePendingUntil(row);
  return Boolean(until && Date.now() >= until);
}

function challengeInvitePlayersClear(row) {
  if (!cleanChallengeName(row?.creator)) return false;
  if (isOpenChallengeOpponent(row?.opponent)) {
    // Samo stvarni otvoreni poziv na čekanju; posle isteka ili bez uređaja/imena ne prikazuj.
    return row?.status === "pending" && !row?.opponent_device && !row?.accepted_at;
  }
  return Boolean(cleanChallengeName(row?.opponent));
}

function challengeExpired(row) {
  // Zelene Witch Hunt kartice važe sve do kraja lova; ne smeju isteći
  // usred subote ili nedelje. U ponedeljak ih zatvara finalizeExpiredChallenges.
  if (isWeekendWitchActive() && challengeIsCurrentWitchHuntRow(row)) return false;
  if (challengePausedForWitchHunt(row)) return false;
  const until = challengeActiveUntil(row);
  return Boolean(until && Date.now() >= until);
}

function challengePlayedSortTime(row) {
  const times = [row?.creator_played_at, row?.opponent_played_at, row?.updated_at, row?.created_at, row?.accepted_at]
    .map((value) => Date.parse(value || ""))
    .filter(Number.isFinite);
  if (times.length) return Math.max(...times);
  if (String(row?.status || "").toLowerCase() === "played") return Date.now();
  return 0;
}

function challengeExpirySortTime(row) {
  const state = challengeCardState(row);
  if (state === "accepted") return challengeActiveUntil(row);
  if (state === "pending") return challengePendingUntil(row);
  if (playedChallenge(row) && !challengeIsWitchHuntRow(row)) return challengePlayedVisibleUntil(row);
  return challengePlayedSortTime(row);
}

function formatChallengeCountdown(remaining) {
  if (!remaining) return "истекло";
  const hours = Math.floor(remaining / 3600000);
  const minutes = Math.floor((remaining % 3600000) / 60000);
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

function challengeCountdownText(row) {
  return formatChallengeCountdown(Math.max(0, challengeActiveUntil(row) - Date.now()));
}

function challengePendingCountdownText(row) {
  return formatChallengeCountdown(Math.max(0, challengePendingUntil(row) - Date.now()));
}

function challengeRole(row) {
  const me = loadPlayerName();
  if (row?.creator_device && row.creator_device === profileDeviceId()) return "creator";
  if (row?.opponent_device && row.opponent_device === profileDeviceId()) return "opponent";
  if (challengeNameMatches(row?.opponent, me)) return "opponent";
  if (challengeNameMatches(row?.creator, me)) return "creator";
  return "";
}

function challengeAlreadyPlayed(row, role) {
  if (!role) return false;
  return challengePlayedAt(row, role) || localChallengePlayedAt(row, role);
}

function challengePlayedAt(row, role) {
  return Number.isFinite(Date.parse(row?.[`${role}_played_at`] || ""));
}

function loadChallengePlayedStore() {
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_PLAYED_KEY) || "null");
    if (data && typeof data === "object") return data;
  } catch {}
  return {};
}

function saveChallengePlayedStore(store) {
  const entries = Object.entries(store || {})
    .filter(([, value]) => Number.isFinite(Date.parse(value?.playedAt || "")))
    .sort((a, b) => Date.parse(b[1].playedAt) - Date.parse(a[1].playedAt))
    .slice(0, 200);
  localStorage.setItem(CHALLENGE_PLAYED_KEY, JSON.stringify(Object.fromEntries(entries)));
}

function challengePlayedKey(rowOrCode, role) {
  const code = normalizeChallengeCode(typeof rowOrCode === "string" ? rowOrCode : rowOrCode?.code);
  return code && role ? `${code}:${role}` : "";
}

function localChallengePlayedAt(rowOrCode, role) {
  const key = challengePlayedKey(rowOrCode, role);
  if (!key) return false;
  const playedAt = loadChallengePlayedStore()[key]?.playedAt || "";
  return Number.isFinite(Date.parse(playedAt));
}

function rememberChallengePlayed(rowOrCode, role) {
  const key = challengePlayedKey(rowOrCode, role);
  if (!key) return;
  const store = loadChallengePlayedStore();
  store[key] = { playedAt: new Date().toISOString() };
  saveChallengePlayedStore(store);
}

function loadPendingChallengeResults() {
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_RESULT_PENDING_KEY) || "null");
    return data && typeof data === "object" ? data : {};
  } catch {}
  return {};
}

function savePendingChallengeResults(store) {
  const entries = Object.entries(store || {})
    .filter(([, item]) => item?.code && item?.role && item?.patch)
    .slice(-40);
  localStorage.setItem(CHALLENGE_RESULT_PENDING_KEY, JSON.stringify(Object.fromEntries(entries)));
}

function rememberPendingChallengeResult(code, role, patch, meta = {}) {
  const cleanCode = normalizeChallengeCode(code);
  if (!cleanCode || !role || !patch) return;
  const store = loadPendingChallengeResults();
  store[cleanCode] = {
    code: cleanCode,
    role,
    patch,
    meta,
    updatedAt: new Date().toISOString()
  };
  savePendingChallengeResults(store);
}

function forgetPendingChallengeResult(code) {
  const cleanCode = normalizeChallengeCode(code);
  if (!cleanCode) return;
  const store = loadPendingChallengeResults();
  delete store[cleanCode];
  savePendingChallengeResults(store);
}

function challengePlayedToday(row) {
  if (!playedChallenge(row)) return false;
  const playedTimes = [row?.creator_played_at, row?.opponent_played_at]
    .map((value) => Date.parse(value || ""))
    .filter(Number.isFinite);
  const lastPlayed = playedTimes.length ? new Date(Math.max(...playedTimes)).toISOString() : row?.created_at || "";
  const playedDay = String(lastPlayed).slice(0, 10);
  return (playedDay || row?.day) === todayId();
}

function sameChallengePlayerPair(creator, opponent) {
  return Boolean(cleanChallengeName(creator) && cleanChallengeName(opponent) && sameChallengeName(creator, opponent));
}

function ownPendingChallenge(row) {
  if (!row || row.status !== "pending") return false;
  return row.creator_device === profileDeviceId() || sameChallengeName(row.creator, loadPlayerName());
}

function selfChallengeRow(row) {
  const creatorDevice = String(row?.creator_device || "").trim();
  const opponentDevice = String(row?.opponent_device || "").trim();
  // Dva razlicita uredjaja mogu imati isto ime nakon spajanja profila.
  // Tada to nije izazov samom sebi i kartica mora ostati vidljiva.
  if (creatorDevice && opponentDevice) return creatorDevice === opponentDevice;
  return sameChallengePlayerPair(row?.creator, row?.opponent);
}

function loadCancelledChallengeCodes() {
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_CANCELLED_KEY) || "null");
    const period = isWeekendWitchActive() ? weekendWitchId() : todayId();
    if ((data?.period || data?.day) !== period || !Array.isArray(data.codes)) return [];
    return data.codes.map((code) => String(code || "").trim().toUpperCase()).filter(Boolean);
  } catch {
    return [];
  }
}

function rememberCancelledChallenge(code) {
  const cleanCode = String(code || "").trim().toUpperCase();
  if (!cleanCode) return;
  const codes = loadCancelledChallengeCodes().filter((item) => item !== cleanCode);
  codes.unshift(cleanCode);
  const period = isWeekendWitchActive() ? weekendWitchId() : todayId();
  localStorage.setItem(CHALLENGE_CANCELLED_KEY, JSON.stringify({ period, codes: codes.slice(0, 80) }));
}

function locallyCancelledChallenge(rowOrCode) {
  const code = typeof rowOrCode === "string" ? rowOrCode : rowOrCode?.code;
  const cleanCode = String(code || "").trim().toUpperCase();
  return Boolean(cleanCode && loadCancelledChallengeCodes().includes(cleanCode));
}

function challengeCardVisible(row) {
  if (!row) return false;
  if (playedChallenge(row)) {
    // Witch Hunt plave: samo subota–nedelja; posle vikenda ostaje samo tabla dole (pon–pet).
    if (challengeIsWitchHuntRow(row)) {
      return isWeekendWitchActive() && challengeIsCurrentWitchHuntRow(row);
    }
    // Radni dan: plavi prikaz 24h, pauzira se preko vikenda i nastavlja u ponedeljak.
    if (isWeekendWitchActive()) return false;
    return Date.now() < challengePlayedVisibleUntil(row);
  }
  // Vikend pozivi se gase čim se lov završi.
  if (challengeIsWitchHuntRow(row) && (!isWeekendWitchActive() || !challengeIsCurrentWitchHuntRow(row))) return false;
  // Stari pozivi su sacuvani, ali se za vreme Witch Hunta ne prikazuju niti im istice vreme.
  // Zuti pending pozivi moraju ostati vidljivi da bi ih protivnik mogao prihvatiti.
  if (challengePausedForWitchHunt(row) && row?.status !== "pending") return false;
  if (row?.status === "cancelled") return false;
  if (locallyCancelledChallenge(row)) return false;
  if (challengePendingExpired(row)) return false;
  if (selfChallengeRow(row)) return false;
  // Ne prikazuj nedovršene kartice bez jasnih igrača (npr. prazan / „Чека се“ posle vikenda).
  if (!challengeInvitePlayersClear(row)) return false;
  if (row?.status === "pending") return true;
  const until = challengeActiveUntil(row);
  return !until || Date.now() < until;
}

function loadPendingChallengeCode() {
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_PENDING_KEY) || "null");
    return data && data.date === todayId() ? data.code : "";
  } catch {
    return "";
  }
}

function savePendingChallengeCode(code) {
  localStorage.setItem(CHALLENGE_PENDING_KEY, JSON.stringify({ date: todayId(), code }));
}

function clearPendingChallengeCode() {
  localStorage.removeItem(CHALLENGE_PENDING_KEY);
}

function loadActiveChallenge() {
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_ACTIVE_KEY) || "null");
    return data && data.code ? data : null;
  } catch {
    return null;
  }
}

function saveActiveChallenge(data) {
  if (!data?.code) return;
  localStorage.setItem(CHALLENGE_ACTIVE_KEY, JSON.stringify({
    code: data.code,
    role: data.role || "",
    creator: data.creator || "",
    opponent: data.opponent || "",
    savedAt: new Date().toISOString()
  }));
}

function clearActiveChallenge() {
  localStorage.removeItem(CHALLENGE_ACTIVE_KEY);
}

function loadSentChallengeRowsToday() {
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_SENT_KEY) || "null");
    if (Array.isArray(data?.entries)) {
      const active = data.entries.filter(challengeSentEntryActive);
      if (active.length !== data.entries.length) {
        localStorage.setItem(CHALLENGE_SENT_KEY, JSON.stringify({ entries: active }));
      }
      const weekendWindow = isWeekendWitchActive() ? weekendWitchWindowContaining(new Date()) : null;
      return active
        .filter((entry) => {
          const stamp = String(entry.day || entry.created_at || entry.sentAt || "").slice(0, 10);
          if (weekendWindow) return challengeIsCurrentWitchHuntRow(entry);
          return stamp === todayId();
        })
        .map((entry) => ({
          code: entry.code || "",
          day: entry.day || todayId(),
          creator: entry.creator || loadPlayerName() || "Играч",
          creator_device: entry.creator_device || profileDeviceId(),
          opponent: entry.opponent || "",
          opponent_device: entry.opponent_device || "",
          accepted_at: entry.accepted_at || "",
          status: entry.status || "pending",
          words: Array.isArray(entry.words) ? entry.words : [],
          created_at: entry.created_at || entry.sentAt || new Date().toISOString(),
          sentAt: entry.sentAt || entry.created_at || new Date().toISOString()
        }));
    }
    if (data?.date === todayId() && Array.isArray(data.opponents)) {
      return data.opponents.map((opponent) => ({
        day: todayId(),
        creator: loadPlayerName() || "Играч",
        creator_device: profileDeviceId(),
        opponent,
        status: "pending",
        created_at: new Date().toISOString(),
        sentAt: new Date().toISOString()
      }));
    }
  } catch {
    if (localStorage.getItem(CHALLENGE_SENT_KEY) === todayId()) {
      return [{
        day: todayId(),
        creator: loadPlayerName() || "Играч",
        creator_device: profileDeviceId(),
        opponent: "legacy",
        status: "pending",
        created_at: new Date().toISOString(),
        sentAt: new Date().toISOString()
      }];
    }
  }
  return [];
}

function loadSentChallengesToday() {
  return loadSentChallengeRowsToday().map((entry) => entry.opponent || "");
}

function markChallengeSentToday(opponent, row = null) {
  if (!challengeCountsForDailyLimit({ opponent })) return;
  let entries = [];
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_SENT_KEY) || "null");
    entries = Array.isArray(data?.entries)
      ? data.entries.filter(challengeSentEntryActive)
      : loadSentChallengesToday().map((name) => ({ opponent: name, sentAt: new Date().toISOString(), status: "pending" }));
  } catch {
    entries = [];
  }
  entries.push({
    code: row?.code || "",
    day: row?.day || todayId(),
    creator: row?.creator || loadPlayerName() || "Играч",
    creator_device: row?.creator_device || profileDeviceId(),
    opponent: opponent || "",
    opponent_device: row?.opponent_device || "",
    accepted_at: row?.accepted_at || "",
    status: row?.status || "pending",
    words: Array.isArray(row?.words) ? row.words : [],
    created_at: row?.created_at || new Date().toISOString(),
    sentAt: new Date().toISOString()
  });
  localStorage.setItem(CHALLENGE_SENT_KEY, JSON.stringify({ entries }));
}

function removeSentChallenge(code) {
  const cleanCode = normalizeChallengeCode(code);
  if (!cleanCode) return;
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_SENT_KEY) || "null");
    const entries = Array.isArray(data?.entries) ? data.entries : [];
    localStorage.setItem(CHALLENGE_SENT_KEY, JSON.stringify({
      entries: entries.filter((entry) => normalizeChallengeCode(entry?.code) !== cleanCode)
    }));
  } catch {
    localStorage.removeItem(CHALLENGE_SENT_KEY);
  }
}

function cleanChallengeName(value) {
  return String(value || "").trim().replace(/\s+/g, " ");
}

function sameChallengeName(left, right) {
  return cleanChallengeName(left).toLocaleLowerCase("sr") === cleanChallengeName(right).toLocaleLowerCase("sr");
}

function challengeNameMatches(storedName, profileName) {
  if (sameChallengeName(storedName, profileName)) return true;
  const stored = cleanChallengeName(storedName);
  const me = cleanChallengeName(profileName);
  if (!stored || !me) return false;
  const guestMatch = stored.match(/^Играч\s+(.+)$/i);
  return Boolean(guestMatch && sameChallengeName(guestMatch[1], me));
}

function postgrestEqValue(value) {
  const text = cleanChallengeName(value);
  if (!text) return "";
  if (/[",()]/.test(text) || /\s/.test(text)) {
    return `"${text.replace(/"/g, "\"\"")}"`;
  }
  return encodeURIComponent(text);
}

function isOpenChallengeOpponent(value) {
  const clean = cleanChallengeName(value);
  return !clean || sameChallengeName(clean, "Нови корисник") || sameChallengeName(clean, "Чека се");
}

function challengeCountsForDailyLimit(row) {
  if (row?.status === "cancelled") return false;
  if (locallyCancelledChallenge(row)) return false;
  return !isOpenChallengeOpponent(row?.opponent) && !selfChallengeRow(row) && !challengePendingExpired(row);
}

function challengeSentEntryActive(entry) {
  const created = Date.parse(entry?.created_at || entry?.sentAt || "");
  if (!Number.isFinite(created)) return false;
  if (isWeekendWitchActive() && challengeIsCurrentWitchHuntRow(entry)) return entry?.status !== "cancelled";
  const status = entry?.status || "pending";
  if (status === "cancelled") return false;
  if (status === "played") {
    if (challengeIsWitchHuntRow(entry)) {
      return isWeekendWitchActive() && challengeIsCurrentWitchHuntRow(entry);
    }
    return Date.now() < challengePlayedVisibleUntil(entry);
  }
  if (status === "accepted") return Date.now() < challengeActiveUntil(entry);
  const until = challengePendingUntil(entry);
  return Date.now() < until;
}

function dailyChallengeCount(rows = []) {
  return rows.filter(challengeCountsForDailyLimit).length;
}

function todayCompetitiveCompletedLevels() {
  const today = todayId();
  const fromRun = gameType === "competitive" ? Number(competitiveCompleted) || 0 : 0;
  const fromLock = loadTodayLock();
  const lockCompleted = fromLock?.date === today ? Number(fromLock.completed) || 0 : 0;
  const fromResult = loadResults().find((result) => result?.date === today);
  const resultCompleted = Number(fromResult?.completed) || 0;
  return Math.max(0, fromRun, lockCompleted, resultCompleted);
}

function challengeDailyLimit() {
  const completed = todayCompetitiveCompletedLevels();
  const levelBonus = COMPETITIVE_LEVELS
    .slice(0, Math.max(0, Math.min(completed, COMPETITIVE_LEVELS.length)))
    .reduce((sum, level) => sum + level, 0);
  const normalBonus = loadNormalChallengeBonus().bonus;
  const weekendBonus = weekendWitchChallengeBonus();
  const manualCredit = loadManualChallengeCredit();
  return Math.min(
    CHALLENGE_MAX_DAILY_LIMIT,
    CHALLENGE_BASE_DAILY_LIMIT + levelBonus + normalBonus + weekendBonus + manualCredit
  );
}

function completedCompetitiveLevelIndex() {
  return Math.max(0, Math.min(Number(competitiveCompleted) || 0, COMPETITIVE_LEVELS.length) - 1);
}

function canAdvanceCompetitiveLevel() {
  return gameType === "competitive" &&
    done &&
    competitiveCompleted > competitiveLevelIndex &&
    competitiveLevelIndex < COMPETITIVE_LEVELS.length - 1;
}

function updateCompetitiveNextButton() {
  if (gameType !== "competitive" || !nextLevelButton) return;
  nextLevelButton.textContent = "Даље";
  nextLevelButton.hidden = !canAdvanceCompetitiveLevel();
}

function sentChallengeRowsFromHistory(rows = []) {
  return rows.filter((row) =>
    row.creator_device === profileDeviceId() &&
    (isWeekendWitchActive()
      ? challengeIsCurrentWitchHuntRow(row)
      : String(row.day || "").slice(0, 10) === todayId()) &&
    challengeCountsForDailyLimit(row)
  );
}

function updateChallengeQuota(rows = null) {
  if (!challengeQuotaEl) return;
  const sentRows = Array.isArray(rows)
    ? rows
    : loadSentChallengeRowsToday().filter(challengeCountsForDailyLimit);
  const limit = challengeDailyLimit();
  const sent = Math.min(dailyChallengeCount(sentRows), limit);
  challengeQuotaEl.textContent = `Послато ${sent}/${limit}`;
  challengeQuotaEl.removeAttribute("title");
}

async function fetchSentChallengesToday() {
  const weekendWindow = isWeekendWitchActive() ? weekendWitchWindowContaining(new Date()) : null;
  const local = loadSentChallengeRowsToday()
    .filter((row) => !weekendWindow || challengeIsCurrentWitchHuntRow(row))
    .filter(challengeCountsForDailyLimit);
  if (!supabaseConfigured()) return local;
  const periodFilter = weekendWindow
    ? [
      `created_at=gte.${encodeURIComponent(new Date(weekendWindow.start).toISOString())}`,
      `created_at=lt.${encodeURIComponent(new Date(weekendWindow.end).toISOString())}`
    ]
    : [`day=eq.${encodeURIComponent(todayId())}`];
  const query = [
    "select=code,day,status,creator,creator_device,opponent,opponent_device,accepted_at,created_at",
    `creator_device=eq.${encodeURIComponent(profileDeviceId())}`,
    ...periodFilter,
    "limit=1000"
  ].join("&");
  const response = await fetch(supabaseUrl(`${challengeTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return local;
  const rows = await response.json();
  return Array.isArray(rows) ? rows.filter(challengeCountsForDailyLimit) : local;
}

function isWithinChallengeActiveWindow(value, now = Date.now()) {
  const at = Date.parse(value || "");
  return Number.isFinite(at) && now - at <= CHALLENGE_PLAYER_ACTIVE_MS;
}

function collectRecentlyActiveChallengeNames({
  normalRows = [],
  scoreRows = [],
  challengeRows = [],
  challengeStatsRows = []
} = {}, currentName = "", now = Date.now()) {
  const names = new Set();
  const add = (rawName, when) => {
    const name = cleanChallengeName(rawName);
    if (!name || name === "Чека се" || sameChallengeName(name, currentName)) return;
    if (!isWithinChallengeActiveWindow(when, now)) return;
    names.add(name);
  };

  (normalRows || []).forEach((row) => add(row?.nickname, row?.updated_at));
  (scoreRows || []).forEach((row) => add(row?.nickname, row?.created_at));
  (challengeRows || []).forEach((row) => {
    add(row?.creator, row?.creator_played_at || row?.created_at);
    add(row?.opponent, row?.opponent_played_at || row?.created_at);
  });
  (challengeStatsRows || []).forEach((row) => {
    add(row?.player_a, row?.last_played_at);
    add(row?.player_b, row?.last_played_at);
  });
  return names;
}

async function fetchChallengePlayers() {
  if (!supabaseConfigured()) return [];
  const currentName = loadPlayerName();

  // Samo igrači sa stvarnom igrom u poslednjih 7 dana — ne samo last_seen / registracija.
  const [playerRows, normalRows, scoreRows, challengeRows, challengeStatsRows] = await Promise.all([
    fetchPlayerRows().catch(() => null),
    fetchNormalStatsRows().catch(() => []),
    fetchOnlineLeaderboard().catch(() => []),
    fetchChallengeHistory().catch(() => []),
    fetchChallengeStatsRows().catch(() => [])
  ]);

  const recentNames = collectRecentlyActiveChallengeNames({
    normalRows,
    scoreRows,
    challengeRows,
    challengeStatsRows
  }, currentName);

  if (Array.isArray(playerRows) && playerRows.length) {
    const known = new Set(
      playerRows
        .map((row) => cleanChallengeName(row?.nickname))
        .filter((name) => name && !sameChallengeName(name, currentName))
    );
    return [...recentNames]
      .filter((name) => known.has(name))
      .sort((a, b) => a.localeCompare(b, "sr"));
  }

  return [...recentNames].sort((a, b) => a.localeCompare(b, "sr"));
}

function renderChallengePlayers(names = []) {
  if (!challengePlayerSelect) return;
  const current = challengePlayerSelect.value;
  const items = [
    ["", "Изазови Петка"],
    ...names.map((name) => [name, name]),
  ];
  const hasCurrent = items.some(([value]) => value === current);
  challengePlayerSelect.value = hasCurrent ? current : "";
  if (challengePlayerButton) {
    const selected = items.find(([value]) => value === challengePlayerSelect.value);
    challengePlayerButton.textContent = selected?.[1] || "Изазови Петка";
  }
  if (!challengePlayerMenu) return;
  challengePlayerMenu.innerHTML = "";
  const search = document.createElement("input");
  search.className = "challenge-player-search";
  search.type = "search";
  search.placeholder = "Претрага";
  search.autocomplete = "off";
  challengePlayerMenu.append(search);
  const optionButtons = [];
  search.addEventListener("input", () => {
    const term = cleanChallengeName(search.value).toLocaleLowerCase("sr");
    optionButtons.forEach((button) => {
      const label = cleanChallengeName(button.textContent).toLocaleLowerCase("sr");
      button.hidden = Boolean(term) && !label.includes(term);
    });
  });
  items.forEach(([value, label]) => {
    const item = document.createElement("button");
    item.type = "button";
    item.className = "challenge-player-option";
    item.textContent = label;
    item.dataset.value = value;
    item.setAttribute("aria-pressed", value === challengePlayerSelect.value ? "true" : "false");
    item.addEventListener("click", () => {
      challengePlayerSelect.value = value;
      if (value !== "__new__") {
        clearPendingChallengeCode();
        if (challengeCodeInput) challengeCodeInput.value = "";
      }
      if (challengePlayerButton) {
        challengePlayerButton.textContent = label;
        challengePlayerButton.setAttribute("aria-expanded", "false");
      }
      challengePlayerMenu.hidden = true;
      [...challengePlayerMenu.querySelectorAll(".challenge-player-option")].forEach((button) => {
        button.setAttribute("aria-pressed", button.dataset.value === value ? "true" : "false");
      });
      renderChallengePanel();
    });
    challengePlayerMenu.append(item);
    optionButtons.push(item);
  });
  if (!challengePlayerMenu.hidden && !challengePlayerMenu.children.length) {
    challengePlayerMenu.hidden = true;
  }
}

function challengePickerItems() {
  return challengePickerPlayers.map((name) => ({ value: name, label: name, kind: "player" }));
}

function challengeFavoriteId(name) {
  return cleanChallengeName(name || "").toLocaleLowerCase("sr");
}

function loadChallengeFavorites() {
  try {
    const parsed = JSON.parse(localStorage.getItem(CHALLENGE_FAVORITES_KEY) || "[]");
    return Array.isArray(parsed) ? parsed.filter(Boolean) : [];
  } catch {
    return [];
  }
}

function saveChallengeFavorites(ids) {
  const unique = [...new Set((ids || []).filter(Boolean))];
  localStorage.setItem(CHALLENGE_FAVORITES_KEY, JSON.stringify(unique.slice(0, 80)));
}

function isChallengeFavorite(name) {
  const id = challengeFavoriteId(name);
  return Boolean(id && loadChallengeFavorites().includes(id));
}

function toggleChallengeFavorite(name) {
  const id = challengeFavoriteId(name);
  if (!id) return;
  const favorites = loadChallengeFavorites();
  saveChallengeFavorites(favorites.includes(id)
    ? favorites.filter((item) => item !== id)
    : [id, ...favorites]);
}

function challengePairAggregate(first, second, rows = challengeStatsRows) {
  if (!first || !second || !Array.isArray(rows) || !rows.length) return null;
  const matches = rows.filter((item) => (
    (sameChallengeName(item.player_a, first) && sameChallengeName(item.player_b, second)) ||
    (sameChallengeName(item.player_a, second) && sameChallengeName(item.player_b, first))
  ));
  const row = matches.sort((a, b) => (Number(b.total_games) || 0) - (Number(a.total_games) || 0))[0];
  if (!row) return null;
  const firstIsA = sameChallengeName(row.player_a, first);
  const aWins = Number(row.player_a_wins) || 0;
  const bWins = Number(row.player_b_wins) || 0;
  const draws = Number(row.draws) || 0;
  const aSent = Number(row.player_a_sent) || 0;
  const bSent = Number(row.player_b_sent) || 0;
  return {
    pair: {
      creator: firstIsA ? aWins : bWins,
      opponent: firstIsA ? bWins : aWins,
      tie: draws
    },
    directed: {
      first: firstIsA ? aSent : bSent,
      second: firstIsA ? bSent : aSent
    }
  };
}

function challengeDirectedCounts(rows = [], first, second) {
  const aggregate = challengePairAggregate(first, second);
  if (aggregate) return aggregate.directed;
  return rows.reduce((counts, row) => {
    if (sameChallengeName(row.creator, first) && sameChallengeName(row.opponent, second)) counts.first += 1;
    if (sameChallengeName(row.creator, second) && sameChallengeName(row.opponent, first)) counts.second += 1;
    return counts;
  }, { first: 0, second: 0 });
}

function renderChallengePickerStats(value) {
  if (!challengePickerStats) return;
  const me = loadPlayerName() || "Играч";
  if (!value) {
    challengePickerStats.textContent = "Изабери играча за међусобни скор.";
    return;
  }
  if (value === "__new__") {
    challengePickerStats.textContent = "Нови корисник добија линк и код. Када прихвати, постаје противник у изазову.";
    return;
  }
  const pair = challengePairScore(challengePickerRows, me, value);
  const directed = challengeDirectedCounts(challengePickerRows, me, value);
  challengePickerStats.innerHTML = "";
  const table = document.createElement("div");
  table.className = "challenge-score-table";
  const title = document.createElement("div");
  title.className = "challenge-score-title";
  title.textContent = "Међусобни скор";
  const board = document.createElement("div");
  board.className = "challenge-score-board";
  const leftName = document.createElement("span");
  leftName.className = "challenge-score-name";
  leftName.textContent = me;
  const result = document.createElement("span");
  result.className = "challenge-score-result";
  result.textContent = `${pair.creator} : ${pair.opponent}`;
  const rightName = document.createElement("span");
  rightName.className = "challenge-score-name";
  rightName.textContent = value;
  board.append(leftName, result, rightName);
  const meta = document.createElement("div");
  meta.className = "challenge-score-meta";
  [`${me} → ${value}: ${directed.first}`, `Нерешено ${pair.tie || 0}`, `${value} → ${me}: ${directed.second}`].forEach((text) => {
    const item = document.createElement("span");
    item.textContent = text;
    meta.append(item);
  });
  table.append(title, board, meta);
  challengePickerStats.append(table);
}

function selectChallengePickerPlayer(value) {
  challengePickerSelected = value;
  if (challengePlayerSelect) challengePlayerSelect.value = value;
  if (challengePlayerButton) {
    const label = value === "__new__" ? "Нови корисник" : (value || "Изазови Петка");
    challengePlayerButton.textContent = label;
  }
  if (challengePickerSubmit) challengePickerSubmit.disabled = !value;
  renderChallengePickerStats(value);
  if (!challengePickerGrid) return;
  [...challengePickerGrid.querySelectorAll(".challenge-picker-player")].forEach((button) => {
    button.setAttribute("aria-pressed", button.dataset.value === value ? "true" : "false");
  });
}

function renderChallengePickerGrid() {
  if (!challengePickerGrid) return;
  const term = cleanChallengeName(challengePickerSearch?.value || "").toLocaleLowerCase("sr");
  const favorites = loadChallengeFavorites();
  const favoriteRank = (item) => {
    const id = challengeFavoriteId(item.value);
    const index = favorites.indexOf(id);
    return index === -1 ? 9999 : index;
  };
  challengePickerGrid.innerHTML = "";
  challengePickerItems()
    .filter((item) => !term || item.label.toLocaleLowerCase("sr").includes(term))
    .sort((first, second) => {
      if (first.kind === "new" && second.kind !== "new") return 1;
      if (second.kind === "new" && first.kind !== "new") return -1;
      const firstFavorite = favoriteRank(first);
      const secondFavorite = favoriteRank(second);
      if (firstFavorite !== secondFavorite) return firstFavorite - secondFavorite;
      return first.label.localeCompare(second.label, "sr");
    })
    .forEach((item) => {
      const favorite = item.kind !== "new" && isChallengeFavorite(item.value);
      const button = document.createElement("button");
      button.type = "button";
      button.className = "challenge-picker-player";
      button.classList.toggle("favorite", favorite);
      button.dataset.value = item.value;
      button.setAttribute("aria-pressed", item.value === challengePickerSelected ? "true" : "false");
      const avatar = document.createElement("span");
      avatar.className = "profile-avatar";
      renderAvatarForName(avatar, item.label, { current: item.kind === "new" });
      if (item.kind !== "new") {
        const heart = document.createElement("span");
        heart.className = "challenge-favorite-toggle";
        heart.setAttribute("role", "button");
        heart.setAttribute("tabindex", "0");
        heart.setAttribute("aria-label", favorite ? "Уклони из фаворита" : "Додај у фаворите");
        heart.textContent = favorite ? "♥" : "♡";
        const toggle = (event) => {
          event.preventDefault();
          event.stopPropagation();
          toggleChallengeFavorite(item.value);
          renderChallengePickerGrid();
        };
        heart.addEventListener("click", toggle);
        heart.addEventListener("keydown", (event) => {
          if (event.key === "Enter" || event.key === " ") toggle(event);
        });
        button.append(heart);
      }
      const label = document.createElement("span");
      label.className = "challenge-picker-player-name";
      label.textContent = item.label;
      button.append(avatar, label);
      button.addEventListener("click", () => selectChallengePickerPlayer(item.value));
      challengePickerGrid.append(button);
    });
}

function closeChallengePicker() {
  if (challengePickerModal) challengePickerModal.hidden = true;
  if (challengePlayerButton) challengePlayerButton.setAttribute("aria-expanded", "false");
  challengePickerBusy = false;
  if (challengePickerMessage) challengePickerMessage.textContent = "";
}

async function openChallengePicker() {
  if (!challengePickerModal) return;
  challengePickerModal.hidden = false;
  challengePickerBusy = false;
  challengePickerSelected = "";
  if (challengePlayerSelect) challengePlayerSelect.value = "";
  if (challengePlayerButton) challengePlayerButton.textContent = "Изазови Петка";
  if (challengePickerSubmit) challengePickerSubmit.disabled = true;
  if (challengePickerMessage) challengePickerMessage.textContent = "";
  if (challengePickerSearch) challengePickerSearch.value = "";
  renderChallengePickerStats(challengePickerSelected);
  try {
    const [players, rows, statsRows] = await Promise.all([
      fetchChallengePlayers().catch(() => []),
      fetchChallengeHistory().catch(() => []),
      fetchChallengeStatsRows().catch(() => [])
    ]);
    challengePickerPlayers = Array.isArray(players) ? players : [];
    challengePickerRows = Array.isArray(rows) ? rows : [];
    challengeStatsRows = Array.isArray(statsRows) ? statsRows : [];
    renderChallengePlayers(challengePickerPlayers);
  } catch {
    challengePickerPlayers = [];
    challengePickerRows = [];
    challengeStatsRows = [];
  }
  renderChallengePickerGrid();
}

function challengeRowMine(row) {
  const me = loadPlayerName();
  const mineByDevice = row?.creator_device === profileDeviceId() || row?.opponent_device === profileDeviceId();
  const mineByName = me && (challengeNameMatches(row?.opponent, me) || challengeNameMatches(row?.creator, me));
  return mineByDevice || mineByName;
}

function challengeNotificationRows(rows = []) {
  return rows.filter((row) => {
    if (playedChallenge(row)) return false;
    if (selfChallengeRow(row)) return false;
    if (!challengeCardVisible(row)) return false;
    return challengeRowMine(row);
  });
}

function challengeRowsForPlayer(rows = []) {
  const me = loadPlayerName();
  const typedCode = normalizeChallengeCode(
    challengeCodeInput?.value || loadPendingChallengeCode() || loadActiveChallenge()?.code || ""
  );
  return rows.filter((row) => {
    if (typedCode && normalizeChallengeCode(row.code) === typedCode) return challengeCardVisible(row);
    if (playedChallenge(row)) {
      return challengeCardVisible(row) && (
        row.creator_device === profileDeviceId() ||
        row.opponent_device === profileDeviceId() ||
        (cleanChallengeName(me) && (sameChallengeName(row.opponent, me) || sameChallengeName(row.creator, me)))
      );
    }
    return challengeNotificationRows([row]).length > 0;
  });
}

function updateChallengeBadge(rows = []) {
  const button = typeButtons.find((item) => item.dataset.type === "challenge");
  if (!button) return;
  const pendingRows = challengeNotificationRows(rows)
    .filter((row) => row.status === "pending" && !row.opponent_device && !row.accepted_at);
  const waitingForReply = pendingRows.filter((row) => challengeRole(row) === "creator").length;
  const waitingForMe = pendingRows.filter((row) => challengeRole(row) === "opponent").length;
  if (waitingForReply) button.dataset.sentCount = String(waitingForReply);
  else delete button.dataset.sentCount;
  if (waitingForMe) button.dataset.receivedCount = String(waitingForMe);
  else delete button.dataset.receivedCount;
  delete button.dataset.count;
  syncChallengeIdlePetkoState();
}

function challengeBadgeCount() {
  const button = typeButtons.find((item) => item.dataset.type === "challenge");
  if (!button) return 0;
  return (Number(button.dataset.sentCount) || 0) + (Number(button.dataset.receivedCount) || 0);
}

function challengeLobbyOpen() {
  return gameType === "challenge" && !challengeGameOpen();
}

function notificationSeenIds() {
  try {
    const ids = JSON.parse(localStorage.getItem(NOTIFICATION_SEEN_KEY) || "[]");
    return Array.isArray(ids) ? ids : [];
  } catch {
    return [];
  }
}

function rememberNotification(id) {
  const ids = notificationSeenIds().filter((item) => item !== id);
  ids.unshift(id);
  localStorage.setItem(NOTIFICATION_SEEN_KEY, JSON.stringify(ids.slice(0, 80)));
}

function notificationWasSeen(id) {
  return notificationSeenIds().includes(id);
}

function notificationsReady() {
  return "Notification" in window && Notification.permission === "granted";
}

async function requestNotificationPermission() {
  if (!("Notification" in window) || Notification.permission !== "default") return;
  try {
    await Notification.requestPermission();
  } catch {}
}

async function petkoNotify(id, title, body, tag = id) {
  if (!id || notificationWasSeen(id) || !notificationsReady()) return;
  rememberNotification(id);
  const options = {
    body,
    tag,
    renotify: false,
    icon: "app-icon.png",
    badge: "logo-icon.png",
    data: { url: window.location.href }
  };
  try {
    const registration = "serviceWorker" in navigator ? await navigator.serviceWorker.getRegistration() : null;
    if (registration?.showNotification) {
      await registration.showNotification(title, options);
      return;
    }
    new Notification(title, options);
  } catch {}
}

async function registerNativePushDevice(token) {
  if (!token || !supabaseConfigured()) return false;
  const capacitor = window.Capacitor;
  const platform = capacitor?.getPlatform?.() || "web";
  const response = await fetch(supabaseUrl("push_devices?on_conflict=token"), {
    method: "POST",
    headers: supabaseJsonHeaders({ Prefer: "resolution=merge-duplicates,return=minimal" }),
    body: JSON.stringify({
      token,
      platform,
      nickname: loadPlayerName() || null,
      device_id: deviceId(),
      updated_at: new Date().toISOString()
    })
  });
  return response.ok;
}

async function setupNativePushNotifications() {
  const capacitor = window.Capacitor;
  const push = capacitor?.Plugins?.PushNotifications;
  if (!capacitor?.isNativePlatform?.() || !push) return false;

  const current = await push.checkPermissions();
  const permission = current.receive === "prompt" ? await push.requestPermissions() : current;
  if (permission.receive !== "granted") return false;

  await push.removeAllListeners();
  await push.addListener("registration", ({ value }) => registerNativePushDevice(value).catch(() => false));
  await push.addListener("registrationError", () => {});
  await push.addListener("pushNotificationActionPerformed", ({ notification }) => {
    const url = notification?.data?.url;
    if (typeof url === "string" && url) window.location.assign(url);
  });
  await push.register();
  return true;
}

function notifyDailyEvents() {
  if (isPetkoFriday()) {
    petkoNotify(
      `friday-${todayId()}`,
      "Петак за Петка",
      "Данас су такмичарски поени дупли, а 5 обичних победа доноси бонус.",
      "petko-friday"
    );
  }
  if (!todayLock()) {
    petkoNotify(
      `competitive-ready-${todayId()}`,
      "Такмичарски је спреман",
      "Данашњи турнир те чека. Један покушај дневно.",
      "petko-competitive"
    );
  }
}

function notifyChallengeEvents(rows = []) {
  challengeNotificationRows(rows).forEach((row) => {
    if (!challengeCardVisible(row)) return;
    const role = challengeRole(row);
    const creator = row.creator || "Играч";
    const opponent = row.opponent || "Играч";
    const canAccept = row.status === "pending" && !row.opponent_device && !ownPendingChallenge(row);
    const canPlay = challengeIsActive(row) && role && !challengeAlreadyPlayed(row, role);

    if (canAccept && role !== "creator") {
      petkoNotify(
        `challenge-invite-${row.code}-${row.updated_at || row.created_at || ""}`,
        "Позив на изазов",
        `${creator} те је позвао на изазов. Прихвати код ${row.code}.`,
        `petko-challenge-${row.code}`
      );
    } else if (canPlay) {
      petkoNotify(
        `challenge-ready-${row.code}-${role}`,
        "Изазов је активан",
        `${creator} против ${opponent}. Можеш да играш или наставиш изазов.`,
        `petko-challenge-${row.code}`
      );
    }
  });
}

function challengeScoreValue(status) {
  const solvedCount = solvedAt.filter(Boolean).length;
  const unusedRows = status === "finished" ? unusedAttempts() : 0;
  return solvedCount * 5 + unusedRows * 10;
}

function clearChallengePanelWords() {
  if (!challengeStatusEl || !challengeStatusEl.classList.contains("challenge-words-copy")) return;
  challengeStatusEl.classList.remove("challenge-words-copy");
  challengeStatusEl.hidden = true;
  challengeStatusEl.innerHTML = "";
}

function renderChallengePanel(text) {
  if (!challengePanelEl) return;
  const showLobby = gameType === "challenge" && !challengeGameOpen();
  challengePanelEl.hidden = !showLobby;
  updateChallengePlayerName();
  updateChallengeQuota();
  const showCodeTools = false;
  const pendingCode = loadPendingChallengeCode();
  const active = loadActiveChallenge();
  if (active && sameChallengePlayerPair(active.creator, active.opponent)) {
    clearActiveChallenge();
  }
  const safeActive = active && !sameChallengePlayerPair(active.creator, active.opponent) ? active : null;
  if (challengeStatusEl) {
    challengeStatusEl.classList.remove("challenge-words-copy");
    challengeStatusEl.hidden = !text;
    challengeStatusEl.textContent = text || "";
  }
  if (challengeCodeTools) challengeCodeTools.hidden = !showCodeTools;
  if (checkChallengeButton) checkChallengeButton.hidden = !(showCodeTools && (pendingCode || active?.code));
  if (challengeCodeInput && showCodeTools && pendingCode && !safeActive && !challengeCodeInput.value) challengeCodeInput.value = pendingCode;
}

function renderChallengePanelWords(row, solvedFlags = null) {
  if (!challengeStatusEl) return;
  const words = normalizeChallengeWords(row?.words);
  challengeStatusEl.hidden = !words.length;
  challengeStatusEl.innerHTML = "";
  challengeStatusEl.classList.toggle("challenge-words-copy", Boolean(words.length));
  if (!words.length) return;
  const flags = Array.isArray(solvedFlags)
    ? solvedFlags
    : (sameChallengeWords(words, targets) && solvedAt.length === words.length
      ? solvedAt.map(Boolean)
      : null);
  challengeStatusEl.append(createChallengeWordList(words, { withInfo: true, solvedFlags: flags }));
}

async function fetchChallenge(code) {
  if (!supabaseConfigured() || !code) return null;
  const query = [
    "select=*",
    `code=eq.${encodeURIComponent(code.toUpperCase())}`,
    "limit=1"
  ].join("&");
  const response = await fetch(supabaseUrl(`${challengeTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) throw new Error(await supabaseErrorMessage(response, "Изазов није доступан."));
  const rows = await response.json();
  return Array.isArray(rows) && rows[0] ? hydrateChallengeRow(rows[0]) : null;
}

async function updateChallenge(code, patch, sourceRow = null) {
  const normalizedCode = normalizeChallengeCode(code);
  if (!normalizedCode) throw new Error("Нема кода изазова.");

  const readUpdatedRows = async (response) => {
    if (!response?.ok) return null;
    const rows = await response.json().catch(() => []);
    return Array.isArray(rows) && rows[0] ? hydrateChallengeRow(rows[0]) : null;
  };

  const row = sourceRow || await fetchChallenge(normalizedCode).catch(() => null);
  let lastError = "Изазов није уписан.";

  if (row?.creator && Array.isArray(row.words) && row.words.length) {
    const body = {
      code: normalizedCode,
      day: row.day,
      creator: row.creator,
      creator_device: row.creator_device,
      creator_faction: row.creator_faction,
      opponent: row.opponent,
      opponent_faction: row.opponent_faction,
      status: row.status,
      words: row.words,
      ...patch
    };
    try {
      const upsertResponse = await fetch(supabaseUrl(`${challengeTable()}?on_conflict=code`), {
        method: "POST",
        headers: supabaseJsonHeaders({ Prefer: "resolution=merge-duplicates,return=representation" }),
        body: JSON.stringify(body)
      });
      const updated = await readUpdatedRows(upsertResponse);
      if (updated) return updated;
      lastError = await supabaseErrorMessage(upsertResponse, lastError);
    } catch (error) {
      lastError = error?.message || lastError;
    }
  }

  try {
    const patchResponse = await fetch(supabaseUrl(`${challengeTable()}?code=eq.${encodeURIComponent(normalizedCode)}`), {
      method: "PATCH",
      headers: supabaseJsonHeaders({ Prefer: "return=representation" }),
      body: JSON.stringify(patch)
    });
    const updated = await readUpdatedRows(patchResponse);
    if (updated) return updated;
    lastError = await supabaseErrorMessage(patchResponse, lastError);
  } catch (error) {
    if (error?.message) lastError = error.message;
  }

  throw new Error(lastError);
}

async function retryPendingChallengeResults() {
  if (!supabaseConfigured()) return [];
  const items = Object.values(loadPendingChallengeResults());
  const refreshedRows = [];
  for (const item of items) {
    const code = normalizeChallengeCode(item?.code);
    const role = item?.role === "creator" ? "creator" : item?.role === "opponent" ? "opponent" : "";
    if (!code || !role || !item?.patch) continue;
    try {
      const current = await fetchChallenge(code).catch(() => null);
      if (current && challengePlayedAt(current, role)) {
        forgetPendingChallengeResult(code);
        clearChallengeProgress(code);
        rememberChallengePlayed(code, role);
        refreshedRows.push(current);
        continue;
      }
      await updateChallenge(code, item.patch);
      const updated = await fetchChallenge(code).catch(() => null);
      forgetPendingChallengeResult(code);
      clearChallengeProgress(code);
      rememberChallengePlayed(code, role);
      if (updated) refreshedRows.push(updated);
    } catch {}
  }
  return refreshedRows;
}

async function deleteChallenge(code) {
  const response = await fetch(supabaseUrl(`${challengeTable()}?code=eq.${encodeURIComponent(code)}`), {
    method: "DELETE",
    headers: supabaseJsonHeaders({ Prefer: "return=minimal" })
  });
  if (!response.ok) throw new Error(await supabaseErrorMessage(response, "Изазов није обрисан."));
}

async function cancelPendingChallenge(row) {
  if (!row?.code) return;
  if (row.status !== "pending" || row.opponent_device || row.accepted_at || challengeRole(row) !== "creator") return;
  rememberCancelledChallenge(row.code);
  removeSentChallenge(row.code);
  clearPendingChallengeCode();
  updateChallengeQuota();
  renderChallengePanel("Изазов је отказан.");
  try {
    await deleteChallenge(row.code);
  } catch {
    await updateChallenge(row.code, { status: "cancelled" });
  }
  renderChallengePanel("Изазов је отказан.");
  const sentRows = await fetchSentChallengesToday().catch(() => loadSentChallengeRowsToday());
  updateChallengeQuota(sentRows);
  await refreshChallengeLobby().catch(() => {});
}

function confirmCancelPendingChallenge(row) {
  return new Promise((resolve) => {
    showWordModal({
      modalVariant: "witch-confirm",
      title: "Otkaži izazov",
      word: "žuta karta",
      text: "Da li želiš da obrišeš ovaj izazov?",
      reviewText: isWeekendWitchActive() && challengeIsCurrentWitchHuntRow(row)
        ? "Vraća ti se 1 dozvoljeni izazov. Možeš odmah izazvati drugog igrača."
        : "Ovaj izazov će biti otkazan.",
      buttons: [
        {
          label: "Ne, zadrži",
          tone: "danger",
          onClick: () => {
            closeWordModal();
            resolve(false);
          }
        },
        {
          label: "Da, otkaži",
          tone: "success",
          onClick: () => {
            closeWordModal();
            resolve(true);
          }
        }
      ]
    });
  });
}

async function finalizeExpiredChallenges(rows = []) {
  const patchedRows = [];
  for (const row of rows) {
    const creatorPlayed = challengeSidePlayed(row, "creator");
    const opponentPlayed = challengeSidePlayed(row, "opponent");
    const witchWindow = weekendWitchWindowContaining(row?.created_at || row?.day);
    const witchHuntEnded = Boolean(witchWindow && Date.now() >= witchWindow.end);
    // Kada se Witch Hunt završi, odigrana strana automatski pobeđuje
    // svaku nedovršenu zelenu karticu; druga strana dobija nula poena.
    const shouldFinalize = !playedChallenge(row) && (challengeExpired(row) || witchHuntEnded) && creatorPlayed !== opponentPlayed;
    if (!shouldFinalize || !row.code) {
      patchedRows.push(row);
      continue;
    }
    const missingRole = creatorPlayed ? "opponent" : "creator";
    const patch = {
      status: "played",
      [`${missingRole}_score`]: 0,
      [`${missingRole}_attempts`]: 0,
      [`${missingRole}_solved`]: 0
    };
    try {
      await updateChallenge(row.code, patch);
      patchedRows.push({ ...row, ...patch });
    } catch {
      patchedRows.push(row);
    }
  }
  return patchedRows;
}

const CHALLENGE_HISTORY_COLUMNS = [
  "code",
  "day",
  "status",
  "creator",
  "creator_device",
  "opponent",
  "opponent_device",
  "accepted_at",
  "created_at",
  "words",
  "creator_score",
  "creator_attempts",
  "creator_solved",
  "creator_played_at",
  "opponent_score",
  "opponent_attempts",
  "opponent_solved",
  "opponent_played_at",
  "creator_faction",
  "opponent_faction"
].join(",");

function mergeChallengeHistoryRows(rows = []) {
  const byCode = new Map();
  rows.flat().forEach((row) => {
    const code = normalizeChallengeCode(row?.code);
    if (code) byCode.set(code, row);
  });
  return [...byCode.values()].sort(
    (a, b) => (Date.parse(b.created_at || "") || 0) - (Date.parse(a.created_at || "") || 0)
  );
}

function challengeHistoryOrFilter() {
  const parts = [];
  const device = profileDeviceId();
  if (device) {
    parts.push(`creator_device.eq.${encodeURIComponent(device)}`);
    parts.push(`opponent_device.eq.${encodeURIComponent(device)}`);
  }
  const me = loadPlayerName();
  if (me) {
    parts.push(`creator.eq.${postgrestEqValue(me)}`);
    parts.push(`opponent.eq.${postgrestEqValue(me)}`);
  }
  return parts.length ? `or=(${parts.join(",")})` : "";
}

async function fetchChallengeHistoryRequests() {
  const since = new Date(Date.now() - 10 * 24 * 60 * 60 * 1000).toISOString();
  const sinceFilter = `created_at=gte.${encodeURIComponent(since)}`;
  const base = [
    `select=${CHALLENGE_HISTORY_COLUMNS}`,
    sinceFilter,
    "order=created_at.desc",
    "limit=200"
  ];
  const openBase = [
    `select=${CHALLENGE_HISTORY_COLUMNS}`,
    "order=created_at.desc",
    "limit=100"
  ];
  const queries = [];
  const orFilter = challengeHistoryOrFilter();
  if (orFilter) queries.push([...base.slice(0, 1), orFilter, ...base.slice(1)].join("&"));
  // Svi otvoreni pozivi (žute) i prihvaćeni (zelene) — bez datuma, da ništa ne ispada iz prikaza.
  queries.push([
    ...openBase.slice(0, 1),
    "status=eq.pending",
    "opponent_device=is.null",
    ...openBase.slice(1)
  ].join("&"));
  queries.push([
    ...openBase.slice(0, 1),
    "status=eq.accepted",
    ...openBase.slice(1)
  ].join("&"));
  queries.push([...base.slice(0, 1), "status=eq.played", ...base.slice(1)].join("&"));
  const typedCode = normalizeChallengeCode(
    challengeCodeInput?.value || loadPendingChallengeCode() || loadActiveChallenge()?.code || ""
  );
  if (typedCode) {
    queries.push([
      `select=${CHALLENGE_HISTORY_COLUMNS}`,
      `code=eq.${encodeURIComponent(typedCode)}`,
      "limit=1"
    ].join("&"));
  }
  return Promise.all(queries.map((query) => fetch(supabaseUrl(`${challengeTable()}?${query}`), {
    headers: supabaseHeaders()
  })));
}

async function fetchChallengeHistory() {
  if (!supabaseConfigured()) return [];
  const responses = await fetchChallengeHistoryRequests().catch(() => []);
  const payloads = await Promise.all(responses.map(async (response) => {
    if (!response?.ok) {
      const details = await response.text().catch(() => "");
      console.warn("Petko: challenge history request failed.", response?.status, details);
      return [];
    }
    const rows = await response.json();
    return Array.isArray(rows) ? rows : [];
  }));
  return mergeChallengeHistoryRows(payloads);
}

function mergeChallengeStatsRows(rows = []) {
  const merged = new Map();
  rows.flat().forEach((row) => {
    if (!row || typeof row !== "object") return;
    const aRaw = normalizePlayerName(row.player_a || "");
    const bRaw = normalizePlayerName(row.player_b || "");
    const a = aRaw.toLocaleLowerCase("sr");
    const b = bRaw.toLocaleLowerCase("sr");
    if (!a || !b || a === b) return;
    const key = a <= b ? `${a}::${b}` : `${b}::${a}`;
    const firstIsA = a <= b;
    const normalized = firstIsA
      ? {
          player_a: aRaw,
          player_b: bRaw,
          player_a_wins: Number(row.player_a_wins) || 0,
          player_b_wins: Number(row.player_b_wins) || 0,
          draws: Number(row.draws) || 0,
          player_a_sent: Number(row.player_a_sent) || 0,
          player_b_sent: Number(row.player_b_sent) || 0,
          total_games: Number(row.total_games) || 0,
          last_played_at: row.last_played_at || ""
        }
      : {
          player_a: bRaw,
          player_b: aRaw,
          player_a_wins: Number(row.player_b_wins) || 0,
          player_b_wins: Number(row.player_a_wins) || 0,
          draws: Number(row.draws) || 0,
          player_a_sent: Number(row.player_b_sent) || 0,
          player_b_sent: Number(row.player_a_sent) || 0,
          total_games: Number(row.total_games) || 0,
          last_played_at: row.last_played_at || ""
        };
    const current = merged.get(key);
    if (!current) {
      merged.set(key, normalized);
      return;
    }
    const keep = normalized.total_games > current.total_games
      || (normalized.total_games === current.total_games && String(normalized.last_played_at) > String(current.last_played_at))
      ? normalized
      : current;
    merged.set(key, {
      player_a: keep.player_a || current.player_a,
      player_b: keep.player_b || current.player_b,
      player_a_wins: keep.player_a_wins,
      player_b_wins: keep.player_b_wins,
      draws: keep.draws,
      player_a_sent: keep.player_a_sent,
      player_b_sent: keep.player_b_sent,
      total_games: keep.total_games,
      last_played_at: keep.last_played_at || current.last_played_at || ""
    });
  });
  return [...merged.values()];
}

async function fetchChallengeStatsRows(options = {}) {
  if (!supabaseConfigured()) return [];
  const baseQuery = [
    "select=player_a,player_b,player_a_wins,player_b_wins,draws,player_a_sent,player_b_sent,total_games,last_played_at",
    "order=last_played_at.desc.nullslast",
    "limit=1000"
  ].join("&");
  const requests = [baseQuery];
  const focusName = normalizePlayerName(options.focusName ?? loadPlayerName() ?? "");
  if (focusName) {
    const pattern = encodeURIComponent(`*${focusName}*`);
    requests.push([
      "select=player_a,player_b,player_a_wins,player_b_wins,draws,player_a_sent,player_b_sent,total_games,last_played_at",
      `or=(player_a.ilike.${pattern},player_b.ilike.${pattern})`,
      "order=last_played_at.desc.nullslast",
      "limit=1000"
    ].join("&"));
  }
  const responses = await Promise.all(requests.map((query) => fetch(supabaseUrl(`${challengeStatsTable()}?${query}`), {
    headers: supabaseHeaders()
  })));
  const payloads = await Promise.all(responses.map(async (response) => {
    if (!response.ok) return [];
    const rows = await response.json();
    return Array.isArray(rows) ? rows : [];
  }));
  return mergeChallengeStatsRows(payloads);
}

async function fetchChallengeScoreStatsRows() {
  if (!supabaseConfigured()) return [];
  const query = [
    "select=nickname,best_score,best_score_count,last_at",
    "order=best_score.desc,best_score_count.desc,last_at.desc.nullslast",
    "limit=1000"
  ].join("&");
  const response = await fetch(supabaseUrl(`${challengeScoreStatsTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return [];
  const rows = await response.json();
  return Array.isArray(rows) ? rows : [];
}

function challengeSidePlayed(row, role) {
  return Boolean(challengePlayedAt(row, role));
}

function challengeRoleSurrendered(row, role) {
  if (!challengePlayedAt(row, role)) return false;
  return (Number(row?.[`${role}_attempts`]) || 0) === 0;
}

function challengeRoleStatusLabel(row, role) {
  if (!challengePlayedAt(row, role)) {
    return playedChallenge(row) ? "истекло време" : "није одиграо";
  }
  if (challengeRoleSurrendered(row, role)) return "предао партију";
  const rawScore = row?.[`${role}_score`];
  const rawSolved = row?.[`${role}_solved`];
  const rawAttempts = row?.[`${role}_attempts`];
  const score = Number(rawScore);
  const solved = Number(rawSolved);
  const attempts = Number(rawAttempts);
  const parts = [];
  parts.push(Number.isFinite(score) ? `${formatScore(score)} поена` : "-");
  if (Number.isFinite(solved)) parts.push(`${formatScore(solved)}/6 табли`);
  if (Number.isFinite(attempts)) parts.push(`${formatScore(attempts)}/11 редова`);
  return parts.join(" · ");
}

function challengeScoreboardResult(row) {
  return playedChallenge(row);
}

function playedChallenge(row) {
  const creatorFinished = challengeSidePlayed(row, "creator");
  const opponentFinished = challengeSidePlayed(row, "opponent");
  if (creatorFinished && opponentFinished) return true;
  if (String(row?.status || "").toLowerCase() !== "played") return false;
  // Pogrešno označen „played“ u bazi — tokom Witch Hunta oba moraju odigrati.
  if (challengeIsWitchHuntRow(row) && isWeekendWitchActive() && challengeIsCurrentWitchHuntRow(row)) {
    return false;
  }
  return creatorFinished || opponentFinished;
}

function challengeWinner(row) {
  if (!playedChallenge(row)) return null;
  const creatorScore = Number(row.creator_score) || 0;
  const opponentScore = Number(row.opponent_score) || 0;
  if (creatorScore === opponentScore) return "tie";
  return creatorScore > opponentScore ? "creator" : "opponent";
}

function challengePairScore(rows, creator, opponent) {
  const aggregate = challengePairAggregate(creator, opponent);
  if (aggregate) return aggregate.pair;
  const score = { creator: 0, opponent: 0, tie: 0 };
  rows.forEach((row) => {
    const sameOrder = row.creator === creator && row.opponent === opponent;
    const reverseOrder = row.creator === opponent && row.opponent === creator;
    if (!playedChallenge(row) || (!sameOrder && !reverseOrder)) return;
    const winner = challengeWinner(row);
    if (winner === "tie") {
      score.tie += 1;
    } else if ((sameOrder && winner === "creator") || (reverseOrder && winner === "opponent")) {
      score.creator += 1;
    } else {
      score.opponent += 1;
    }
  });
  return score;
}

function challengePairText(pair, creator, opponent) {
  const tieText = pair.tie ? ` · нерешено ${pair.tie}` : "";
  return `${creator} ${pair.creator} : ${pair.opponent} ${opponent}${tieText}`;
}

function challengeGameOpen() {
  return gameType === "challenge" && !done && targets.length === CHALLENGE_WORDS;
}

function normalizeChallengeWords(words) {
  let source = words;
  if (typeof source === "string") {
    try {
      source = JSON.parse(source);
    } catch {
      return [];
    }
  }
  if (!Array.isArray(source)) return [];
  return source.map((word) => normalize(word)).filter((word) => word.length === WORD_LENGTH);
}

function sameChallengeWords(first = [], second = []) {
  const left = normalizeChallengeWords(first);
  const right = normalizeChallengeWords(second);
  return left.length === right.length && left.every((word, index) => word === right[index]);
}

function hydrateChallengeRow(row) {
  if (!row || typeof row !== "object") return null;
  if (row.words === undefined) return row;
  return { ...row, words: normalizeChallengeWords(row.words) };
}

function challengeRowLabel(row, role) {
  return challengeRoleStatusLabel(row, role);
}

function challengeDifference(row) {
  if (!playedChallenge(row)) return 0;
  return Math.abs((Number(row.creator_score) || 0) - (Number(row.opponent_score) || 0));
}

function challengeWinnerName(row) {
  const winner = challengeWinner(row);
  if (winner === "creator") return row.creator || "Играч 1";
  if (winner === "opponent") return row.opponent || "Играч 2";
  if (winner === "tie") return "Нерешено";
  return "Чека се";
}

function challengeAvatarCode(avatar = {}) {
  const explicitCode = String(avatar?.code || "").trim();
  if (explicitCode) return explicitCode.toUpperCase();

  const id = String(avatar?.id || "").trim().toLowerCase();
  const idMatch = id.match(/^(male|female)-(\d+)$/);
  if (idMatch) return `${idMatch[1] === "female" ? "Z" : "M"}${idMatch[2]}`;

  const source = String(avatar?.fullSrc || avatar?.src || "");
  const sourceMatch = source.match(/(?:^|\/)([MZ]\d{2,3})(?:-[ab])?\.png$/i);
  return sourceMatch ? sourceMatch[1].toUpperCase() : "";
}

function challengeAvatarIsMale(avatar = {}) {
  const code = challengeAvatarCode(avatar);
  const id = String(avatar?.id || "").toLowerCase();
  return avatar?.group === "male" || id.startsWith("male-") || /^M\d+$/i.test(code);
}

function challengeFactionFromAvatar(avatar = {}) {
  return challengeAvatarIsMale(avatar) ? "hunter" : "witch";
}

function challengeRowFaction(row = {}, role = "creator") {
  const saved = String(row?.[`${role}_faction`] || "").toLowerCase();
  if (saved === "hunter" || saved === "witch") return saved;
  const name = role === "creator" ? row.creator : row.opponent;
  return challengeFactionFromAvatar(challengeProfileAvatar(name));
}

function challengeAvatarIsWeekendWitch(avatar = {}) {
  return /^Z4[1-5]$/i.test(challengeAvatarCode(avatar));
}

function challengeWeekendHunterAvatar() {
  return profileAvatarByCode("M50") || profileAvatarById("male-50") || {
    id: "male-50",
    code: "M50",
    group: "male",
    label: "Ловац",
    src: "avatar/M50.png",
    fullSrc: "avatar/M50-a.png"
  };
}

function challengeWeekendWitchAvatar(seed = "") {
  const weekendSeed = `${weekendWitchId()}|${cleanChallengeName(seed)}`;
  let hash = 0;
  for (let index = 0; index < weekendSeed.length; index += 1) {
    hash = ((hash * 31) + weekendSeed.charCodeAt(index)) >>> 0;
  }
  const code = `Z${41 + (hash % 5)}`;
  return profileAvatarByCode(code) || profileAvatarById(`female-${code.slice(1)}`);
}

function challengeDisplayAvatar(avatar = {}, seed = "") {
  if (!isWeekendWitchActive()) return avatar;
  if (challengeAvatarIsWeekendWitch(avatar)) return avatar;
  if (challengeAvatarIsMale(avatar)) return challengeWeekendHunterAvatar();
  return challengeWeekendWitchAvatar(seed || challengeAvatarCode(avatar) || avatar?.id) || avatar;
}

function challengeProfileAvatar(name = "") {
  let avatar;
  if (isOpenChallengeOpponent(name)) avatar = profileAvatarByCode("Z40") || profileAvatarById("female-40");
  else if (sameChallengeName(name, loadPlayerName())) avatar = currentProfileAvatar();
  else avatar = cachedProfileAvatar(name) || deterministicProfileAvatar(name);
  return challengeDisplayAvatar(avatar, name);
}

function confirmWitchSisterChallenge(opponent = "") {
  return new Promise((resolve) => {
    showWordModal({
      modalVariant: "witch-confirm",
      title: "Викенд вештичарења",
      word: "сестра вештица",
      text: `Изазиваш сестру вештицу ${opponent}. Овај изазов је дозвољен.`,
      reviewText: "Потврди да желиш да пошаљеш изазов.",
      buttons: [
        {
          label: "Да",
          tone: "success",
          onClick: () => {
            closeWordModal();
            resolve(true);
          }
        },
        {
          label: "Не",
          tone: "danger",
          onClick: () => {
            closeWordModal();
            resolve(false);
          }
        }
      ]
    });
  });
}

function showHunterChallengeBlocked(opponent = "") {
  return new Promise((resolve) => {
    showWordModal({
      modalVariant: "hunter-blocked",
      title: "Кодекс Ловаца",
      word: "ловци не нападају ловце",
      text: `Не можеш послати изазов играчу ${opponent} јер сте обојица Ловци.`,
      reviewText: "Током Witch Hunta Ловац може изазвати само Вештицу.",
      buttons: [{
        label: "Разумем",
        tone: "success",
        onClick: () => {
          closeWordModal();
          resolve();
        }
      }]
    });
  });
}

function challengeWinnerVerb(name = "") {
  return challengeProfileAvatar(name)?.group === "female" ? "Победила" : "Победио";
}

function challengeWinnerScoreVerb(name = "") {
  return challengeProfileAvatar(name)?.group === "female" ? "Освојила" : "Освојио";
}

function challengeSentVerb(name = "") {
  return challengeProfileAvatar(name)?.group === "female" ? "послала" : "послао";
}

function challengeResultAvatarSrc(avatar = {}, variant = "a") {
  const displayAvatar = challengeDisplayAvatar(avatar);
  const suffix = variant === "b" ? "b" : "a";
  const code = challengeAvatarCode(displayAvatar);
  if (code) {
    if (code === "M50" && suffix === "b") return "avatar/M50-a.png";
    return `avatar/${code}-${suffix}.png`;
  }
  const source = String(displayAvatar?.fullSrc || displayAvatar?.src || "");
  const match = source.match(/^(.*\/)?([^/.]+?)(?:-[ab])?\.png$/i);
  if (!match) return "";
  return `${match[1] || ""}${match[2]}-${suffix}.png`;
}

function challengeResultVisual(winnerName = "", loserName = "") {
  const loserAvatar = challengeProfileAvatar(loserName);
  if (isWeekendWitchActive() && challengeAvatarIsWeekendWitch(loserAvatar)) {
    return {
      name: loserName,
      avatar: loserAvatar,
      src: challengeResultAvatarSrc(loserAvatar, "b")
    };
  }

  const winnerAvatar = challengeProfileAvatar(winnerName);
  return {
    name: winnerName,
    avatar: winnerAvatar,
    src: challengeResultAvatarSrc(winnerAvatar, "a")
  };
}

function renderChallengeVsAvatar(target, name = "") {
  if (!target) return;
  const avatar = challengeProfileAvatar(name);
  const vsSrc = challengeResultAvatarSrc(avatar);
  target.innerHTML = "";
  target.classList.toggle("has-image", Boolean(vsSrc || avatar?.src));
  if (!vsSrc) {
    renderAvatarForName(target, name, { avatar });
    return;
  }
  const image = document.createElement("img");
  image.src = vsSrc;
  image.alt = name || avatar?.label || "Аватар";
  image.loading = "eager";
  image.addEventListener("error", () => {
    renderAvatarForName(target, name, { avatar });
  }, { once: true });
  target.append(image);
}

function challengeResultLine(row, role, name) {
  const line = document.createElement("div");
  line.className = "challenge-result-line";
  const player = document.createElement("strong");
  player.textContent = `${name}:`;
  const details = document.createElement("span");
  details.textContent = challengePlayedAt(row, role)
    ? challengeRoleStatusLabel(row, role)
    : (playedChallenge(row) ? "истекло време" : "није одиграо");
  line.append(player, details);
  return line;
}

function challengeAvatarElement(name) {
  const avatar = document.createElement("span");
  avatar.className = "profile-avatar challenge-player-avatar";
  renderAvatarForName(avatar, name, {
    avatar: challengeProfileAvatar(name)
  });
  return avatar;
}

function createChallengeWordList(words = [], options = {}) {
  const list = document.createElement("div");
  list.className = `challenge-result-word-list${options.withInfo ? " with-info" : ""}`;
  const solvedFlags = Array.isArray(options.solvedFlags) ? options.solvedFlags : null;
  normalizeChallengeWords(words).forEach((target, index) => {
    const solved = solvedFlags ? Boolean(solvedFlags[index]) : true;
    const chip = document.createElement("div");
    chip.className = `solution-chip ${solved ? "solved" : "unsolved"} challenge-result-word-chip`;
    const word = document.createElement("div");
    word.className = "mini-word";
    [...displayWord(target)].forEach((letter) => {
      const tile = document.createElement("span");
      tile.className = "mini-word-tile";
      tile.textContent = letter;
      word.append(tile);
    });
    chip.append(word);
    if (options.withInfo) {
      const info = document.createElement("button");
      info.className = "mini-word-info";
      info.type = "button";
      info.textContent = "?";
      info.setAttribute("aria-label", `Објашњење речи ${displayWord(target)}`);
      info.addEventListener("click", (event) => {
        event.stopPropagation();
        showExistingWordReview(target);
      });
      chip.append(info);
    }
    list.append(chip);
  });
  if (!list.childElementCount) {
    const empty = document.createElement("div");
    empty.className = "challenge-result-word-empty";
    empty.textContent = "Речи нису сачуване.";
    list.append(empty);
  }
  return list;
}

let heldChallengeResultKey = "";
let challengeVisibleCardCount = 0;
let challengeSectionState = loadChallengeSectionState();

function loadChallengeSectionState() {
  return {};
}

function resetChallengeSectionState() {
  challengeSectionState = {};
}

function saveChallengeSectionState() {}

function challengeSectionOpen(key, defaultOpen = false) {
  if (typeof challengeSectionState[key] === "boolean") return challengeSectionState[key];
  return defaultOpen;
}

function setChallengeSectionOpen(key, open) {
  challengeSectionState[key] = Boolean(open);
  saveChallengeSectionState();
}

function latestFinishedWitchHuntWindow(rows = []) {
  const now = Date.now();
  return (rows || []).reduce((latest, row) => {
    const window = weekendWitchWindowContaining(row?.created_at || row?.day);
    return window && window.end <= now && (!latest || window.end > latest.end) ? window : latest;
  }, null);
}

let weekendWitchResults = [];

async function refreshWeekendWitchResults() {
  if (!supabaseConfigured()) return [];
  const response = await fetch(supabaseUrl(`${weekendResultsTable()}?select=*&order=weekend_start.desc&limit=24`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return weekendWitchResults;
  const rows = await response.json();
  weekendWitchResults = Array.isArray(rows) ? rows : [];
  return weekendWitchResults;
}

function weekendResultWindow(result) {
  if (!result || typeof result !== "object") return null;
  const start = Date.parse(`${String(result.weekend_start || "").slice(0, 10)}T00:00:00`);
  if (!Number.isFinite(start)) return null;
  return { start, end: start + (2 * 24 * 60 * 60 * 1000) };
}

function savedWitchHuntResultForWindow(window) {
  if (!window) return null;
  return weekendWitchResults.find((result) => {
    if (!result) return false;
    const savedWindow = weekendResultWindow(result);
    return savedWindow && savedWindow.start === window.start;
  }) || null;
}

function latestSavedWitchHuntResult() {
  const now = Date.now();
  const lastStart = latestWitchHuntWeekendStart();
  return weekendWitchResults.find((result) => {
    if (!result) return false;
    const window = weekendResultWindow(result);
    const startDate = String(result.weekend_start || "").slice(0, 10);
    return startDate === lastStart && window && window.end <= now;
  }) || null;
}

function tallyWeekendWitchPlayedRows(playedRows = []) {
  let hunters = 0;
  let witches = 0;
  let draws = 0;
  playedRows.forEach((row) => {
    if (!playedChallenge(row)) return;
    const creatorIsHunter = challengeRowFaction(row, "creator") === "hunter";
    const opponentIsHunter = challengeRowFaction(row, "opponent") === "hunter";
    // Veštica koja napadne drugu Vešticu računa se kao poražena Veštica:
    // bez obzira na pojedinačni skor, poen ide Lovcima.
    if (!creatorIsHunter && !opponentIsHunter) {
      hunters += 1;
      return;
    }
    const winner = challengeWinner(row);
    if (!winner) return;
    if (winner === "tie") {
      draws += 1;
      return;
    }
    const winnerRole = winner === "creator" ? "creator" : "opponent";
    if (challengeRowFaction(row, winnerRole) === "hunter") hunters += 1;
    else witches += 1;
  });
  return { hunters, witches, draws };
}

function showFinishedWitchHuntUntilFriday() {
  if (isWeekendWitchActive()) return false;
  const day = new Date().getDay();
  return day >= 1 && day <= 5;
}

function witchHuntWinnerImage(winner, window) {
  const images = winner === "hunter"
    ? ["avatar/Z41-b.png", "avatar/Z45-b.png"]
    : winner === "witch"
      ? ["avatar/Z41-a.png", "avatar/Z45-a.png", "avatar/challenge-tie-witch.png"]
      : ["avatar/challenge-tie-witch.png"];
  const started = Number(window?.end) || Date.now();
  const slot = Math.max(0, Math.floor((Date.now() - started) / (3 * 60 * 60 * 1000)));
  return images[slot % images.length];
}

function calendarWitchHuntWindow(date = new Date()) {
  const startStamp = latestWitchHuntWeekendStart(date);
  const start = Date.parse(`${startStamp}T00:00:00`);
  if (!Number.isFinite(start)) return null;
  return { start, end: start + (2 * 24 * 60 * 60 * 1000) };
}

function renderWeekendWitchScoreboard(rows = []) {
  if (!weekendWitchScoreboardEl) return;
  const currentWitchWindow = weekendWitchWindowContaining(new Date());
  const finishedWindow = latestFinishedWitchHuntWindow(rows);
  const savedFinishedResult = latestSavedWitchHuntResult();
  const savedFinishedWindow = weekendResultWindow(savedFinishedResult);
  // Kartice te nedelje imaju prednost. Ako nema redova/arhive, i dalje pokaži
  // kalendarski prošli vikend od ponedeljka do petka.
  const displayWindow = currentWitchWindow
    || (showFinishedWitchHuntUntilFriday()
      ? (finishedWindow || savedFinishedWindow || calendarWitchHuntWindow())
      : null);
  const weekendStart = dateStampFromMs(displayWindow?.start) || latestWitchHuntWeekendStart();
  let savedResult = savedWitchHuntResultForWindow(displayWindow) || savedFinishedResult;
  if (!witchHuntResultHasScore(savedResult)) {
    savedResult = cachedWeekendWitchResult(weekendStart);
  }
  const showFinalWinner = !currentWitchWindow && Boolean(displayWindow) && showFinishedWitchHuntUntilFriday();
  const playedRows = Array.isArray(rows) && displayWindow
    ? rows.filter((row) => {
      const sentAt = Date.parse(row?.created_at || row?.day || "");
      return challengeScoreboardResult(row) && Number.isFinite(sentAt) && sentAt >= displayWindow.start && sentAt < displayWindow.end;
    })
    : [];
  if ((!isWeekendWitchActive() && !showFinalWinner) || !displayWindow) {
    weekendWitchScoreboardEl.hidden = true;
    weekendWitchScoreboardEl.innerHTML = "";
    if (weekendWitchWinnerEl) weekendWitchWinnerEl.hidden = true;
    if (idleWitchWeekendPosterEl) {
      idleWitchWeekendPosterEl.src = "witch-weekend-poster.png";
      idleWitchWeekendPosterEl.alt = "";
    }
    return;
  }

  const liveTally = tallyWeekendWitchPlayedRows(playedRows);
  const useLiveTally = playedRows.length > 0;
  const hunters = useLiveTally ? liveTally.hunters : (Number(savedResult?.hunters) || 0);
  const witches = useLiveTally ? liveTally.witches : (Number(savedResult?.witches) || 0);
  const draws = useLiveTally ? liveTally.draws : (Number(savedResult?.draws) || 0);
  const unplayed = useLiveTally ? 0 : (Number(savedResult?.unplayed) || 0);
  const winningFaction = useLiveTally
    ? (hunters > witches ? "hunter" : witches > hunters ? "witch" : "tie")
    : (savedResult?.winner || (hunters > witches ? "hunter" : witches > hunters ? "witch" : "tie"));
  cacheWeekendWitchResult(weekendStart, {
    hunters,
    witches,
    draws,
    unplayed,
    winner: winningFaction
  });
  if (idleWitchWeekendPosterEl) {
    idleWitchWeekendPosterEl.src = showFinalWinner
      ? witchHuntWinnerImage(winningFaction, displayWindow)
      : "witch-weekend-poster.png";
    idleWitchWeekendPosterEl.alt = showFinalWinner ? "Pobednici Witch Hunta" : "";
  }
  if (weekendWitchWinnerEl) {
    if (showFinalWinner) {
      const winner = winningFaction === "hunter" ? "Lovci" : winningFaction === "witch" ? "Veštice" : "Nerešeno";
      weekendWitchWinnerEl.textContent = winner === "Nerešeno"
        ? "Witch Hunt je završen nerešeno"
        : `Pobednici ove nedelje su ${winner}`;
      weekendWitchWinnerEl.hidden = false;
    } else {
      weekendWitchWinnerEl.hidden = true;
    }
  }

  weekendWitchScoreboardEl.hidden = false;
  weekendWitchScoreboardEl.innerHTML = "";
  const createTally = (count, faction, label) => {
    const side = document.createElement("div");
    side.className = `weekend-witch-faction ${faction}`;
    const name = document.createElement("div");
    name.className = "weekend-witch-faction-name";
    name.textContent = label;
    const tally = document.createElement("div");
    tally.className = "weekend-witch-tally";
    tally.setAttribute("aria-label", `${label}: ${count}`);
    if (!count) {
      tally.textContent = "—";
    } else {
      const completeGroups = Math.floor(count / 5);
      const remainder = count % 5;
      const addGroup = (marks, crossed = false) => {
        const group = document.createElement("span");
        group.className = "weekend-witch-tally-group";
        for (let index = 0; index < marks; index += 1) {
          group.append(document.createElement("i"));
        }
        if (crossed) group.append(document.createElement("b"));
        tally.append(group);
      };
      for (let index = 0; index < completeGroups; index += 1) addGroup(4, true);
      if (remainder) addGroup(remainder);
    }
    side.append(name, tally);
    return side;
  };
  weekendWitchScoreboardEl.append(
    createTally(hunters, "hunters", "Lovci"),
    createTally(witches, "witches", "Veštice")
  );
  if (draws) {
    const drawsText = document.createElement("div");
    drawsText.className = "weekend-witch-scoreboard-draws";
    drawsText.textContent = `Nerešeno: ${draws}`;
    weekendWitchScoreboardEl.append(drawsText);
  }
  if (unplayed) {
    const unplayedText = document.createElement("div");
    unplayedText.className = "weekend-witch-scoreboard-draws";
    unplayedText.textContent = `Neodigrano: ${unplayed}`;
    weekendWitchScoreboardEl.append(unplayedText);
  }
}

function syncChallengeIdlePetkoState() {
  if (!challengeHistoryEl) return;
  const sections = Array.from(challengeHistoryEl.querySelectorAll(".challenge-section-body"));
  const hasCards = challengeVisibleCardCount > 0 ||
    sections.some((section) => section.children.length) ||
    challengeBadgeCount() > 0;
  const loading = document.body.dataset.challengeLoading === "true";
  document.body.dataset.challengeCards = hasCards ? "true" : "false";
  document.body.dataset.challengeWeekendPoster =
    !loading && (isWeekendWitchActive() || showFinishedWitchHuntUntilFriday()) ? "true" : "false";
}

function releaseChallengeResultFlip() {
  heldChallengeResultKey = "";
  document.querySelectorAll(".challenge-card.result.played.show-words").forEach((card) => {
    card.classList.remove("show-words");
  });
}

document.addEventListener("pointerup", releaseChallengeResultFlip);
document.addEventListener("pointercancel", releaseChallengeResultFlip);

function challengeResultKey(row = {}) {
  return String(row.id || row.code || row.created_at || "");
}

function bindChallengeResultFlip(card, key) {
  let holdTimer = 0;
  let startX = 0;
  let startY = 0;
  const clearHold = () => {
    window.clearTimeout(holdTimer);
    holdTimer = 0;
  };
  card.addEventListener("pointerdown", (event) => {
    if (event.pointerType === "mouse" && event.button !== 0) return;
    clearHold();
    startX = event.clientX;
    startY = event.clientY;
    heldChallengeResultKey = key;
    holdTimer = window.setTimeout(() => {
      if (heldChallengeResultKey === key) card.classList.add("show-words");
    }, 420);
  });
  card.addEventListener("pointermove", (event) => {
    if (!holdTimer) return;
    if (Math.abs(event.clientX - startX) > 8 || Math.abs(event.clientY - startY) > 8) clearHold();
  });
  card.addEventListener("pointerup", clearHold);
  card.addEventListener("pointercancel", clearHold);
  card.addEventListener("contextmenu", (event) => {
    if (heldChallengeResultKey === key || card.classList.contains("show-words")) event.preventDefault();
  });
}

function challengeHistorySection(key, title, rows, allRows, defaultOpen = false) {
  const group = document.createElement("div");
  const open = challengeSectionOpen(key, defaultOpen);
  group.className = `challenge-section-group challenge-section-group-${key} ${open ? "open" : "collapsed"}`;

  const menu = document.createElement("section");
  menu.className = `challenge-section challenge-section-${key}`;

  const toggle = document.createElement("button");
  toggle.type = "button";
  toggle.className = "challenge-section-toggle";
  toggle.setAttribute("aria-expanded", String(open));

  const label = document.createElement("span");
  label.textContent = title;
  const count = document.createElement("span");
  count.className = "challenge-section-count";
  count.textContent = String(rows.length);
  const arrow = document.createElement("span");
  arrow.className = "challenge-section-arrow";
  arrow.textContent = "⌄";
  toggle.append(label, count, arrow);

  const body = document.createElement("div");
  body.className = "challenge-section-body";
  body.hidden = !open;
  rows.forEach((row) => body.append(challengeCard(row, allRows)));

  toggle.addEventListener("click", () => {
    const nextOpen = group.classList.contains("collapsed");
    group.classList.toggle("collapsed", !nextOpen);
    group.classList.toggle("open", nextOpen);
    body.hidden = !nextOpen;
    toggle.setAttribute("aria-expanded", String(nextOpen));
    setChallengeSectionOpen(key, nextOpen);
    syncChallengeIdlePetkoState();
  });

  menu.append(toggle);
  group.append(menu, body);
  return group;
}

function challengeNameWithAvatar(name) {
  const item = document.createElement("span");
  item.className = "challenge-name-with-avatar";
  item.append(challengeAvatarElement(name));
  const label = document.createElement("span");
  label.textContent = name;
  item.append(label);
  return item;
}

function challengeCard(row, rows = []) {
  const card = document.createElement("article");
  card.className = `challenge-card ${playedChallenge(row) ? "result" : "invite"} ${challengeCardState(row)}`;
  card.addEventListener("click", () => clearChallengePanelWords());
  const creator = row.creator || "Играч 1";
  const opponent = row.opponent || "Чека се";
  const openInvite = isOpenChallengeOpponent(opponent);
  const role = challengeRole(row);
  const canCancel = role === "creator" && row.status === "pending" && !row.opponent_device && !row.accepted_at;
  if (canCancel) {
    const cancel = document.createElement("button");
    cancel.type = "button";
    cancel.className = "challenge-cancel-button";
    cancel.setAttribute("aria-label", "\u041e\u0434\u0443\u0441\u0442\u0430\u043d\u0438 \u043e\u0434 \u0438\u0437\u0430\u0437\u043e\u0432\u0430");
    cancel.textContent = "\u00d7";
    cancel.addEventListener("click", async () => {
      if (!await confirmCancelPendingChallenge(row)) return;
      cancelPendingChallenge(row).catch(() => renderChallengePanel("\u041e\u0434\u0443\u0441\u0442\u0430\u0458\u0430\u045a\u0435 \u043e\u0434 \u0438\u0437\u0430\u0437\u043e\u0432\u0430 \u043d\u0438\u0458\u0435 \u0443\u0441\u043f\u0435\u043b\u043e."));
    });
    card.append(cancel);
  }
  const otherPlayer = role === "creator" ? (openInvite ? "нови корисник" : opponent) : creator;
  const pair = openInvite || opponent === "Чека се" ? null : challengePairScore(rows, creator, opponent);
  if (playedChallenge(row)) {
    const resultKey = challengeResultKey(row);
    if (heldChallengeResultKey === resultKey) card.classList.add("show-words");
    const winnerRole = challengeWinner(row);
    const winnerName = challengeWinnerName(row);
    const main = document.createElement("div");
    main.className = "challenge-result-main";
    const body = document.createElement("div");
    body.className = "challenge-result-body";
    const versus = document.createElement("div");
    versus.className = "challenge-result-versus";
    versus.append(challengeNameWithAvatar(creator), document.createTextNode(" → "), challengeNameWithAvatar(opponent));
    const outcome = document.createElement("div");
    outcome.className = `challenge-result-outcome ${winnerRole === "tie" ? "tie" : "win"}`;
    if (winnerRole === "tie") {
      outcome.textContent = "Нерешено";
    } else {
      const winnerLine = document.createElement("div");
      winnerLine.textContent = `${challengeWinnerVerb(winnerName)} ${winnerName}`;
      const scoreLine = document.createElement("div");
      scoreLine.textContent = `${challengeWinnerScoreVerb(winnerName)} ${formatScore(challengeDifference(row))} бодова`;
      outcome.append(winnerLine, scoreLine);
    }
    const lines = document.createElement("div");
    lines.className = "challenge-result-lines";
    lines.append(
      challengeResultLine(row, "creator", creator),
      challengeResultLine(row, "opponent", opponent)
    );
    body.append(versus, outcome, lines);
    const media = document.createElement("div");
    media.className = `challenge-result-media ${winnerRole === "tie" ? "tie" : ""}`;
    if (winnerRole === "tie") {
      media.setAttribute("aria-label", "Нерешено");
      const tieImage = document.createElement("img");
      tieImage.src = isWeekendWitchActive() ? "avatar/challenge-tie-witch.png" : "avatar/challenge-tie.png";
      tieImage.alt = "Нерешено";
      tieImage.loading = "lazy";
      media.append(tieImage);
    } else {
      const loserName = winnerRole === "creator" ? opponent : winnerRole === "opponent" ? creator : "";
      const resultVisual = challengeResultVisual(winnerName, loserName);
      const resultSrc = resultVisual.src;
      if (resultSrc) {
        media.classList.add("action-avatar");
        const resultImage = document.createElement("img");
        resultImage.src = resultSrc;
        resultImage.alt = resultVisual.name;
        resultImage.loading = "lazy";
        resultImage.addEventListener("error", () => {
          media.innerHTML = "";
          media.classList.remove("action-avatar");
          renderAvatarForName(media, resultVisual.name, { avatar: resultVisual.avatar });
        }, { once: true });
        media.append(resultImage);
      } else {
        renderAvatarForName(media, resultVisual.name, { avatar: resultVisual.avatar });
      }
    }
    main.append(body, media);
    const flip = document.createElement("div");
    flip.className = "challenge-result-flip";
    const front = document.createElement("div");
    front.className = "challenge-result-face challenge-result-front";
    front.append(main);
    const back = document.createElement("div");
    back.className = "challenge-result-face challenge-result-back";
    back.append(createChallengeWordList(row.words));
    flip.append(front, back);
    card.append(flip);
    bindChallengeResultFlip(card, resultKey);
    return card;
  }
  if (pair) {
    const pairEl = document.createElement("div");
    pairEl.className = "challenge-card-pair";
    pairEl.append(
      document.createTextNode("Међусобно: "),
      challengeNameWithAvatar(creator),
      document.createTextNode(` ${pair.creator} : ${pair.opponent} `),
      challengeNameWithAvatar(opponent)
    );
    card.append(pairEl);
  }
  const title = document.createElement("div");
  title.className = "challenge-card-title";
  if (playedChallenge(row)) {
    title.append(challengeNameWithAvatar(creator), document.createTextNode(" → "), challengeNameWithAvatar(opponent));
  } else if (challengeIsActive(row)) {
    title.append(document.createTextNode("Изазов је прихваћен: "), challengeNameWithAvatar(creator), document.createTextNode(" → "), challengeNameWithAvatar(opponent));
  } else if (role === "creator") {
    if (openInvite) {
      title.append(document.createTextNode("Позван "), challengeNameWithAvatar("Нови корисник"));
    } else {
      title.append(document.createTextNode("Упутили сте изазов: "), challengeNameWithAvatar(opponent));
    }
  } else {
    title.append(challengeNameWithAvatar(creator), document.createTextNode(` вам је ${challengeSentVerb(creator)} изазов`));
  }
  const winner = document.createElement("div");
  winner.className = "challenge-card-winner";
  const pendingCountdown = challengePendingCountdownText(row);
  winner.textContent = playedChallenge(row)
    ? `Победник: ${challengeWinnerName(row)} · добија ${formatScore(challengeDifference(row))}`
    : challengeIsActive(row)
      ? `Зелена карта важи још ${challengeCountdownText(row)}`
      : isWeekendWitchActive() && challengeIsWitchHuntRow(row)
        ? "Жута карта важи до краја викенда"
      : role === "creator"
        ? `Чека се да ${otherPlayer} прихвати · истиче за ${pendingCountdown}`
        : `Прихватите изазов да се отвори игра · истиче за ${pendingCountdown}`;
  const scores = document.createElement("div");
  scores.className = "challenge-card-scores";
  scores.textContent = playedChallenge(row)
    ? `${creator}: ${challengeRowLabel(row, "creator")} | ${opponent}: ${challengeRowLabel(row, "opponent")}`
    : openInvite && role === "creator"
      ? `Чека се одговор новог корисника · 6 табли · 11 покушаја`
      : openInvite
        ? `Унеси име или надимак за игру · 6 табли · 11 покушаја`
        : `Код: ${row.code || "-"} · 6 табли · 11 покушаја`;
  card.append(title, winner);
  card.append(scores);
  if (!playedChallenge(row)) {
    const actions = document.createElement("div");
    actions.className = "challenge-card-actions";
    const canAccept = row.status === "pending" && !row.opponent_device && !ownPendingChallenge(row);
    const canPlay = challengeIsActive(row) && role && !challengeAlreadyPlayed(row, role);
    if (canAccept) {
      let nameInput = null;
      if (openInvite) {
        nameInput = document.createElement("input");
        nameInput.className = "challenge-card-name";
        nameInput.type = "text";
        nameInput.placeholder = "Име или надимак";
        nameInput.value = loadPlayerName();
        actions.append(nameInput);
      }
      const accept = document.createElement("button");
      accept.type = "button";
      accept.textContent = "Прихвати изазов";
      accept.addEventListener("click", () => acceptChallenge(row.code, { play: false, name: nameInput?.value || "" }).catch((error) => renderChallengePanel(error?.message || "Прихватање изазова није успело.")));
      actions.append(accept);
    }
    if (canPlay) {
      const play = document.createElement("button");
      play.type = "button";
      play.textContent = "Настави изазов";
      play.addEventListener("click", () => acceptChallenge(row.code, { play: true }).catch((error) => renderChallengePanel(error?.message || "Покретање изазова није успело.")));
      actions.append(play);
      const surrender = document.createElement("button");
      surrender.type = "button";
      surrender.className = "challenge-surrender-button";
      surrender.textContent = "Предај изазов";
      surrender.addEventListener("click", () => confirmSurrenderChallenge(row));
      actions.append(surrender);
    } else if (challengeIsActive(row) && role && challengeAlreadyPlayed(row, role)) {
      const waiting = document.createElement("div");
      waiting.className = "challenge-card-waiting";
      waiting.textContent = "Одиграли сте. Чека се противник.";
      actions.append(waiting);
    }
    if (actions.children.length) card.append(actions);
  }
  return card;
}

function renderChallengeHistoryCards(rows = []) {
  if (!challengeHistoryEl) return;
  challengeHistoryEl.innerHTML = "";
  renderWeekendWitchScoreboard(rows);
  updateChallengeBadge(rows);
  notifyChallengeEvents(rows);
  updateChallengeQuota(sentChallengeRowsFromHistory(rows));
  const notificationRows = challengeNotificationRows(rows);
  const inviteRows = notificationRows
    .sort((a, b) => {
      const stateOrder = { accepted: 0, pending: 1, played: 2 };
      const stateDiff = stateOrder[challengeCardState(a)] - stateOrder[challengeCardState(b)];
      if (stateDiff) return stateDiff;
      const expiryDiff = challengeExpirySortTime(a) - challengeExpirySortTime(b);
      if (expiryDiff) return expiryDiff;
      return (Date.parse(b.created_at || "") || 0) - (Date.parse(a.created_at || "") || 0);
    });
  const resultRows = rows
    .filter((row) => playedChallenge(row) && challengeCardVisible(row))
    .sort((a, b) => challengePlayedSortTime(b) - challengePlayedSortTime(a));
  const activeRows = inviteRows.filter((row) => challengeCardState(row) === "accepted");
  const pendingRows = inviteRows.filter((row) => challengeCardState(row) !== "accepted");
  challengeVisibleCardCount = inviteRows.length + resultRows.length;
  const sections = [
    ["active", "Активни изазови", activeRows],
    ["pending", "Изазови на чекању", pendingRows],
    ["played", "Одиграни изазови", resultRows]
  ].filter(([, , sectionRows]) => sectionRows.length);
  sections.forEach(([key, title, sectionRows]) => {
    challengeHistoryEl.append(challengeHistorySection(key, title, sectionRows, rows, false));
  });
  if (!challengeHistoryEl.childElementCount && (inviteRows.length || resultRows.length)) {
    const flat = document.createElement("div");
    flat.className = "challenge-section-body";
    [...inviteRows, ...resultRows].forEach((row) => flat.append(challengeCard(row, rows)));
    challengeHistoryEl.append(flat);
    challengeVisibleCardCount = inviteRows.length + resultRows.length;
  }
  syncChallengeIdlePetkoState();
}

async function refreshChallengeHistoryCards() {
  if (!challengeHistoryEl || !supabaseConfigured()) return;
  await persistLatestWitchHuntResult().catch(() => false);
  await refreshWeekendWitchResults().catch(() => []);
  const [rows, statsRows] = await Promise.all([
    fetchChallengeHistory(),
    fetchChallengeStatsRows().catch(() => [])
  ]);
  if (Array.isArray(statsRows)) challengeStatsRows = statsRows;
  renderChallengeHistoryCards(rows);
}

function challengeSyncRowSnapshot(row = {}) {
  return [
    row.code,
    row.status,
    row.accepted_at,
    row.creator,
    row.creator_device,
    row.opponent,
    row.opponent_device,
    row.creator_score,
    row.opponent_score,
    row.creator_solved,
    row.opponent_solved,
    row.creator_attempts,
    row.opponent_attempts,
    row.creator_played_at,
    row.opponent_played_at,
    row.created_at
  ].map((value) => value ?? "").join("|");
}

function challengeSyncSnapshotFor(rows = []) {
  return rows
    .map(challengeSyncRowSnapshot)
    .sort()
    .join("\n");
}

function mergeLocalChallengeRows(rows = []) {
  const byCode = new Map();
  rows.forEach((row) => {
    const code = normalizeChallengeCode(row?.code);
    if (code) byCode.set(code, row);
  });
  loadSentChallengeRowsToday()
    .filter((row) => row.code && challengeCardVisible(row))
    .forEach((row) => {
      const code = normalizeChallengeCode(row.code);
      if (!byCode.has(code)) byCode.set(code, row);
    });
  return [...byCode.values()];
}

function shouldPollChallengeSync() {
  if (!supabaseConfigured()) return false;
  if (document.visibilityState === "hidden") return false;
  if (gameType === "challenge") return true;
  if (loadActiveChallenge()?.code) return true;
  if (loadPendingChallengeCode()) return true;
  if (loadSentChallengeRowsToday().some(challengeSentEntryActive)) return true;
  return hasRegisteredPlayerProfile();
}

function mergeActiveChallengeRow(row) {
  if (!row?.code) return;
  const active = loadActiveChallenge();
  if (!active || normalizeChallengeCode(active.code) !== normalizeChallengeCode(row.code)) return;
  const role = active.role || challengeRole(row);
  const next = {
    ...active,
    role,
    creator: row.creator || active.creator,
    opponent: row.opponent || active.opponent
  };
  activeChallenge = next;
  saveActiveChallenge(next);
}

async function syncActiveChallengeResult(rows = []) {
  const active = activeChallenge || loadActiveChallenge();
  const code = normalizeChallengeCode(active?.code);
  if (!code) return;
  const row = rows.find((item) => normalizeChallengeCode(item.code) === code) || await fetchChallenge(code).catch(() => null);
  if (!row) return;
  mergeActiveChallengeRow(row);
  const role = active?.role || challengeRole(row);
  const localPlayed = role ? challengeAlreadyPlayed(row, role) : false;
  const localFinished = done && targets.length > 0 && solvedAt.filter(Boolean).length === targets.length;
  const localScore = done ? challengeScoreValue(localFinished ? "finished" : "failed") : 0;
  if (playedChallenge(row) || (gameType === "challenge" && done && localPlayed)) {
    await renderChallengeResult(row, localScore);
  }
}

async function cachedChallengePlayers(force = false) {
  if (!force && challengePlayersCache.rows && Date.now() - challengePlayersCache.at < CHALLENGE_AUX_TTL_MS) {
    return challengePlayersCache.rows;
  }
  const rows = await fetchChallengePlayers().catch(() => challengePlayersCache.rows || []);
  if (Array.isArray(rows)) challengePlayersCache = { at: Date.now(), rows };
  return rows;
}

async function cachedChallengeStatsRows(force = false) {
  if (!force && challengeStatsCache.rows && Date.now() - challengeStatsCache.at < CHALLENGE_AUX_TTL_MS) {
    return challengeStatsCache.rows;
  }
  const rows = await fetchChallengeStatsRows().catch(() => challengeStatsCache.rows || []);
  if (Array.isArray(rows)) challengeStatsCache = { at: Date.now(), rows };
  return rows;
}

async function syncChallengeState({ force = false } = {}) {
  if (!shouldPollChallengeSync() && !force) return;
  if (challengeSyncBusy) {
    if (force) challengeSyncQueuedForce = true;
    return;
  }
  challengeSyncBusy = true;
  try {
    await retryPendingChallengeResults().catch(() => []);
    const [players, rows, statsRows] = await Promise.all([
      gameType === "challenge" && !challengeGameOpen()
        ? cachedChallengePlayers(force).catch(() => [])
        : Promise.resolve(null),
      fetchChallengeHistory().catch(() => []),
      cachedChallengeStatsRows(force).catch(() => [])
    ]);
    if (Array.isArray(statsRows)) challengeStatsRows = statsRows;
    const finalRows = mergeLocalChallengeRows(await finalizeExpiredChallenges(rows));
    challengeRowsCache = finalRows;
    const snapshot = challengeSyncSnapshotFor(finalRows);
    const changed = force || snapshot !== challengeSyncSnapshot;
    const shouldRenderCards = changed || challengeLobbyOpen();
    if (changed) challengeSyncSnapshot = snapshot;
    if (shouldRenderCards) {
      if (Array.isArray(players)) renderChallengePlayers(players);
      renderChallengeHistoryCards(finalRows);
    } else {
      updateChallengeBadge(finalRows);
      updateChallengeQuota(sentChallengeRowsFromHistory(finalRows));
    }
    await syncActiveChallengeResult(finalRows);
  } finally {
    challengeSyncBusy = false;
    if (challengeSyncQueuedForce) {
      challengeSyncQueuedForce = false;
      syncChallengeState({ force: true }).catch(() => {});
    } else if (challengeLobbyOpen()) {
      syncChallengeIdlePetkoState();
    }
  }
}

function refreshChallengePanel() {
  syncChallengeState({ force: true }).catch(() => {});
}

async function refreshChallengeLobby() {
  await syncChallengeState({ force: true });
}

async function renderChallengeResult(row, localScore, options = {}) {
  if (!row) {
    renderChallengePanel("");
    return;
  }
  const creator = row.creator || "Играч 1";
  const opponent = row.opponent || "Играч 2";
  const [history, statsRows] = await Promise.all([
    fetchChallengeHistory(),
    fetchChallengeStatsRows().catch(() => [])
  ]);
  if (Array.isArray(statsRows)) challengeStatsRows = statsRows;
  if (!playedChallenge(row)) {
    saveActiveChallenge({
      code: row.code,
      role: activeChallenge?.role || loadActiveChallenge()?.role || "",
      creator,
      opponent
    });
    if (options.showPanelWords) {
      renderChallengePanel("");
      renderChallengePanelWords(row, options.solvedFlags);
    } else if (!challengeStatusEl?.classList.contains("challenge-words-copy")) {
      renderChallengePanel("");
    }
    renderChallengeHistoryCards([row, ...history.filter((item) => item.code !== row.code)]);
    return;
  }

  clearActiveChallenge();
  if (options.showPanelWords) {
    renderChallengePanel("");
    renderChallengePanelWords(row, options.solvedFlags);
  } else if (!challengeStatusEl?.classList.contains("challenge-words-copy")) {
    renderChallengePanel("");
  }
  renderChallengeHistoryCards([row, ...history.filter((item) => item.code !== row.code)]);
}

async function showChallengeScoreboard(code) {
  const row = await fetchChallenge(code);
  if (!row) {
    renderChallengePanel("Изазов није пронађен.");
    return;
  }
  await renderChallengeResult(row, 0);
}

async function shareChallenge(code) {
  const text = `Петко изазов: ${code}\n${challengeUrl(code)}`;
  if (navigator.share) {
    await navigator.share({ text, url: challengeUrl(code) });
    return;
  }
  await navigator.clipboard.writeText(text);
}

async function createChallenge(selectedOpponent = null) {
  renderChallengePanel("Шаљем изазов...");
  if (!supabaseConfigured()) {
    renderChallengePanel("За изазове мора бити активан Supabase.");
    return false;
  }
  const profileName = loadPlayerName() || (playerNameInput ? playerNameInput.value : "");
  if (!profileName) {
    renderChallengePanel("Уреди профил и упиши име пре слања изазова.");
    openProfileModal();
    return false;
  }
  const nickname = await savePlayerNameUnique(profileName);
  if (!nickname) return false;
  const selectedChallengeOpponent = selectedOpponent ?? challengePickerSelected;
  let opponent = cleanChallengeName(selectedChallengeOpponent || challengePlayerSelect?.value || "");
  const shareAfterCreate = false;
  if (opponent === "__new__") {
    renderChallengePanel("Позив за новог корисника више није доступан. Нови играч се прво региструје именом и аватаром.");
    return false;
  }
  if (!opponent && !shareAfterCreate) {
    renderChallengePanel("Изабери регистрованог играча.");
    return false;
  }
  if (sameChallengeName(nickname, opponent)) {
    renderChallengePanel("Не можеш изазвати самог себе.");
    return false;
  }
  if (isWeekendWitchActive() && !shareAfterCreate) {
    // Resolve Supabase weekend avatars before deciding which modal to show.
    await refreshChallengePlayerAvatars().catch(() => []);
    const creatorAvatar = challengeProfileAvatar(nickname);
    const opponentAvatar = challengeProfileAvatar(opponent);
    const creatorIsHunter = challengeAvatarIsMale(creatorAvatar);
    const opponentIsHunter = challengeAvatarIsMale(opponentAvatar);

    if (creatorIsHunter && opponentIsHunter) {
      await showHunterChallengeBlocked(opponent);
      renderChallengePanel("Ловац не може изазвати Ловца tokom Witch Hunta.");
      return false;
    }
    if (!creatorIsHunter && !opponentIsHunter) {
      const confirmed = await confirmWitchSisterChallenge(opponent);
      if (!confirmed) {
        renderChallengePanel("Изазов сестри вештици није послат.");
        return false;
      }
    }
  }
  const sentToday = await fetchSentChallengesToday().catch(() => loadSentChallengeRowsToday());
  updateChallengeQuota(sentToday);
  const sentCount = dailyChallengeCount(sentToday);
  const dailyLimit = challengeDailyLimit();
  if (!shareAfterCreate && sentCount >= dailyLimit) {
    renderChallengePanel(`Данас сте већ послали ${dailyLimit} изазова.`);
    return false;
  }
  const code = challengeCode();
  const words = chooseTargets(CHALLENGE_WORDS);
  const creatorFaction = challengeFactionFromAvatar(challengeProfileAvatar(nickname));
  const opponentFaction = shareAfterCreate ? null : challengeFactionFromAvatar(challengeProfileAvatar(opponent));
  let response;
  try {
    response = await fetch(supabaseUrl(challengeTable()), {
      method: "POST",
      headers: supabaseJsonHeaders({ Prefer: "return=minimal" }),
      body: JSON.stringify({
        code,
        day: todayId(),
        creator: nickname,
        creator_device: profileDeviceId(),
        creator_faction: creatorFaction,
        opponent_faction: opponentFaction,
        opponent: shareAfterCreate ? "Чека се" : opponent,
        status: "pending",
        words
      })
    });
  } catch {
    updateChallengeQuota(sentToday);
    renderChallengePanel("Слање изазова није успело. Покушај поново.");
    return false;
  }
  if (!response.ok) {
    updateChallengeQuota(sentToday);
    renderChallengePanel(await supabaseErrorMessage(response, "Изазов није направљен."));
    return false;
  }
  const createdAt = new Date().toISOString();
  const localChallengeRow = {
    code,
    day: todayId(),
    status: "pending",
    creator: nickname,
    creator_device: profileDeviceId(),
    opponent: shareAfterCreate ? "" : opponent,
    words,
    created_at: createdAt
  };
  markChallengeSentToday(opponent, localChallengeRow);
  updateChallengeQuota(shareAfterCreate ? sentToday : [...sentToday, localChallengeRow]);
  savePendingChallengeCode(code);
  if (challengeCodeInput) challengeCodeInput.value = code;
  renderChallengePanel(shareAfterCreate
    ? `Позивница ${code} је спремна. Пошаљи линк новом кориснику.`
    : `Изазов ${code} за ${opponent} је послат. Картица је жута док не прихвати.`);
  renderChallengeHistoryCards([localChallengeRow]);
  refreshChallengeLobby().catch(() => {});
  fetchChallengePlayers().then(renderChallengePlayers).catch(() => {});
  if (shareAfterCreate) {
    shareChallenge(code).catch(() => renderChallengePanel(`Позивница ${code} је направљена. Отвори жуту картицу и пошаљи линк.`));
  }
  return true;
}

async function supabaseErrorMessage(response, fallback) {
  try {
    const data = await response.json();
    const message = String(data?.message || "");
    if (data?.code === "PGRST205" || /Could not find the table/i.test(data?.message || "")) {
      return "У Supabase-у није направљена табела challenges. Покрени SQL из supabase-schema.sql.";
    }
    if (/same opponent already challenged today/i.test(message)) {
      return "Supabase SQL још има старо ограничење за истог противника. Покрени нови supabase-schema.sql.";
    }
    if (/daily challenge limit reached/i.test(message)) {
      return "Supabase још броји старе изазове за дневни лимит. Покрени најновији supabase-schema.sql да база броји исто као апликација.";
    }
    return message || fallback;
  } catch {
    return fallback;
  }
}

function showChallengeIntro() {
  exitChallengeToLobby();
}

function exitChallengeToLobby() {
  saveChallengeProgress();
  resetChallengeSectionState();
  gameType = "challenge";
  activeChallenge = loadActiveChallenge();
  competitiveIntro = false;
  competitiveRunActive = false;
  done = true;
  mode = CHALLENGE_WORDS;
  targets = [];
  solvedAt = [];
  guesses = [];
  current = "";
  keyStates = new Map();
  document.body.dataset.gameType = gameType;
  document.body.dataset.competitiveLocked = "false";
  document.body.dataset.competitiveIntro = "false";
  document.body.dataset.challengePlaying = "false";
  document.body.dataset.challengeFinished = "false";
  boardsEl.innerHTML = "";
  keyboardEl.innerHTML = "";
  hideWordReveal();
  boardsEl.classList.remove("multi", "mega", "level-1", "level-2", "level-4", "level-8");
  typeButtons.forEach((button) => button.classList.toggle("active", button.dataset.type === gameType));
  updateModeButtons();
  renderSolutionsPanel(false);
  nextLevelButton.hidden = true;
  modeLabelEl.textContent = "Изазов";
  messageEl.textContent = "";
  tryCountEl.textContent = "0";
  tryButton.textContent = `0/${CHALLENGE_ATTEMPTS}`;
  updateScoreDisplay();
  renderChallengePanel();
  document.body.dataset.challengeLoading = "true";
  syncChallengeIdlePetkoState();
  if (challengeCodeInput && activeChallenge) challengeCodeInput.value = "";
  if (challengeRowsCache.length) renderChallengeHistoryCards(challengeRowsCache);
  refreshChallengeLobby()
    .catch(() => {})
    .finally(() => {
      document.body.dataset.challengeLoading = "false";
      syncChallengeIdlePetkoState();
    });
}

function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function playChallengeVs(row) {
  if (!challengeVsOverlay || !row) return;
  const creator = row.creator || "Играч 1";
  const opponent = row.opponent || loadPlayerName() || "Играч 2";
  if (challengeVsLeftName) challengeVsLeftName.textContent = creator;
  if (challengeVsRightName) challengeVsRightName.textContent = opponent;
  renderChallengeVsAvatar(challengeVsLeftAvatar, creator);
  renderChallengeVsAvatar(challengeVsRightAvatar, opponent);
  challengeVsOverlay.hidden = false;
  challengeVsOverlay.classList.remove("active");
  void challengeVsOverlay.offsetWidth;
  challengeVsOverlay.classList.add("active");
  await wait(CHALLENGE_VS_MS);
  challengeVsOverlay.hidden = true;
  challengeVsOverlay.classList.remove("active");
}

async function startChallengeGame(row, role) {
  await hydrateGameSessionsFromCloud({ force: true }).catch(() => false);
  const serverRow = hydrateChallengeRow(row);
  if (!serverRow || !Array.isArray(serverRow.words) || serverRow.words.length !== CHALLENGE_WORDS) {
    renderChallengePanel("\u0418\u0437\u0430\u0437\u043e\u0432 \u043d\u0438\u0458\u0435 \u0438\u0441\u043f\u0440\u0430\u0432\u0430\u043d.");
    return;
  }
  const creator = serverRow.creator || "\u0418\u0433\u0440\u0430\u0447 1";
  const opponent = serverRow.opponent || loadPlayerName() || "\u0418\u0433\u0440\u0430\u0447 2";
  if (challengeAlreadyPlayed(serverRow, role)) {
    clearChallengeProgress(serverRow.code);
    activeChallenge = { code: serverRow.code, role, creator, opponent };
    saveActiveChallenge(activeChallenge);
    await renderChallengeResult(serverRow, Number(serverRow?.[`${role}_score`] || 0));
    return;
  }
  const savedProgress = loadChallengeProgress(serverRow.code);
  if (savedProgress && sameChallengeWords(savedProgress.targets, serverRow.words)) {
    await playChallengeVs(serverRow);
    restoreChallengeProgress({
      ...savedProgress,
      active: { ...(savedProgress.active || {}), code: serverRow.code, role, creator, opponent },
      targets: serverRow.words
    });
    return;
  }
  if (savedProgress) clearChallengeProgress(serverRow.code);
  await playChallengeVs(serverRow);
  gameType = "challenge";
  activeChallenge = { code: serverRow.code, role, creator, opponent };
  saveActiveChallenge(activeChallenge);
  clearPendingChallengeCode();
  if (challengeCodeInput) challengeCodeInput.value = "";
  competitiveIntro = false;
  competitiveRunActive = false;
  mode = CHALLENGE_WORDS;
  score = 0;
  targets = serverRow.words;
  solvedAt = Array(targets.length).fill(null);
  guesses = [];
  current = "";
  done = false;
  keyStates = new Map();
  bonusFlashRows = new Set();
  document.body.dataset.gameType = gameType;
  document.body.dataset.competitiveLocked = "false";
  document.body.dataset.competitiveIntro = "false";
  document.body.dataset.challengePlaying = "true";
  document.body.dataset.challengeFinished = "false";
  boardsEl.classList.remove("multi", "mega", "level-1", "level-2", "level-4", "level-8");
  boardsEl.classList.add("multi", "mega", "level-8");
  typeButtons.forEach((button) => button.classList.toggle("active", button.dataset.type === gameType));
  updateModeButtons();
  nextLevelButton.hidden = true;
  modeLabelEl.textContent = "\u0418\u0437\u0430\u0437\u043e\u0432";
  messageEl.textContent = "\u0418\u0437\u0430\u0437\u043e\u0432 \u043f\u0440\u0438\u0445\u0432\u0430\u045b\u0435\u043d: 6 \u0442\u0430\u0431\u043b\u0438, 11 \u043f\u043e\u043a\u0443\u0448\u0430\u0458\u0430.";
  renderChallengePanel(`\u0418\u0433\u0440\u0430\u0448: ${creator} \u043f\u0440\u043e\u0442\u0438\u0432 ${opponent}.`);
  Promise.all([
    fetchChallengeHistory(),
    fetchChallengeStatsRows().catch(() => [])
  ])
    .then(([rows, statsRows]) => {
      if (Array.isArray(statsRows)) challengeStatsRows = statsRows;
      const pair = challengePairScore(rows, creator, opponent);
      messageEl.textContent = `\u0418\u0433\u0440\u0430\u0448: ${creator} \u043f\u0440\u043e\u0442\u0438\u0432 ${opponent}. \u041c\u0435\u0452\u0443\u0441\u043e\u0431\u043d\u043e: ${challengePairText(pair, creator, opponent)}.`;
      renderChallengePanel(`\u0418\u0433\u0440\u0430\u0448: ${creator} \u043f\u0440\u043e\u0442\u0438\u0432 ${opponent}. \u041c\u0435\u0452\u0443\u0441\u043e\u0431\u043d\u043e: ${challengePairText(pair, creator, opponent)}.`);
    })
    .catch(() => {});
  renderSolutionsPanel(false);
  render();
  saveChallengeProgress();
}
async function acceptChallenge(codeInput = "", options = {}) {
  const playNow = options.play !== false;
  const code = String(codeInput || challengeCodeInput?.value || "").trim().toUpperCase();
  if (!code) {
    renderChallengePanel("Унеси код изазова.");
    return;
  }
  const row = await fetchChallenge(code);
  if (!row) {
    renderChallengePanel("Изазов није пронађен.");
    return;
  }
  if (row.creator_device === profileDeviceId()) {
    if (row.status !== "accepted" && row.status !== "played") {
      renderChallengePanel("Изазов је послат. Чека се прихватање противника.");
      return;
    }
    clearPendingChallengeCode();
    if (!playNow) {
      await renderChallengeResult(row, 0);
      return;
    }
    await startChallengeGame(row, "creator");
    return;
  }
  if (row.status === "pending" && sameChallengeName(row.creator, loadPlayerName())) {
    renderChallengePanel("Ово је твоја позивница. Чека се да је прихвати други корисник.");
    return;
  }
  if (row.status === "pending") {
    const invitedOpponent = isOpenChallengeOpponent(row.opponent) ? "" : cleanChallengeName(row.opponent);
    const requestedName = cleanChallengeName(
      invitedOpponent || options.name || loadPlayerName() || (playerNameInput ? playerNameInput.value : "") || ""
    );
    if (!requestedName) {
      renderChallengePanel("Уреди профил и упиши име пре прихватања изазова.");
      openProfileModal();
      return;
    }
    const acceptedName = await claimChallengePlayerName(requestedName, invitedOpponent);
    if (!acceptedName) {
      renderChallengePanel(`Надимак "${requestedName}" већ постоји. Пробај други назив.`);
      if (playerNameInput) playerNameInput.value = loadPlayerName();
      return;
    }
    let acceptedRow;
    try {
      acceptedRow = await updateChallenge(code, {
        status: "accepted",
        opponent: isOpenChallengeOpponent(row.opponent) ? acceptedName : row.opponent,
        opponent_device: profileDeviceId(),
        opponent_faction: challengeFactionFromAvatar(currentProfileAvatar()),
        accepted_at: new Date().toISOString()
      }, row);
    } catch (error) {
      renderChallengePanel(error?.message || "Прихватање изазова није успело.");
      return;
    }
    if (acceptedRow?.status === "accepted") {
      if (!playNow) {
        renderChallengePanel("Изазов је прихваћен. Картица је зелена и активна 24h.");
        renderChallengeHistoryCards([acceptedRow]);
        await refreshChallengeLobby().catch(() => {});
        return;
      }
      await startChallengeGame(acceptedRow, "opponent");
      return;
    }
  }
  const accepted = await fetchChallenge(code);
  if (!playNow) {
    renderChallengePanel("Изазов је прихваћен. Картица је зелена и активна 24h.");
    if (accepted) renderChallengeHistoryCards([accepted]);
    await refreshChallengeLobby().catch(() => {});
    return;
  }
  await startChallengeGame(accepted || row, "opponent");
}

async function finishChallenge(status) {
  done = true;
  document.body.dataset.challengePlaying = "true";
  document.body.dataset.challengeFinished = "true";
  renderSolutionsPanel(true);
  const resultScore = challengeScoreValue(status);
  const solvedCount = solvedAt.filter(Boolean).length;
  messageEl.textContent = status === "finished"
    ? `Изазов решен: ${solvedCount}/6. Скор ${resultScore}.`
    : `Изазов завршен: ${solvedCount}/6. Решења: ${displayWords(targets)}. Скор ${resultScore}.`;
  if (!activeChallenge?.code || !supabaseConfigured()) return;
  const prefix = activeChallenge.role === "creator" ? "creator" : "opponent";
  const otherRole = prefix === "creator" ? "opponent" : "creator";
  const currentRow = await fetchChallenge(activeChallenge.code).catch(() => null);
  const patch = {
    [`${prefix}_score`]: resultScore,
    [`${prefix}_attempts`]: guesses.length,
    [`${prefix}_solved`]: solvedCount,
    [`${prefix}_played_at`]: new Date().toISOString()
  };
  patch.status = currentRow && challengeSidePlayed(currentRow, otherRole) ? "played" : "accepted";
  rememberPendingChallengeResult(activeChallenge.code, prefix, patch, {
    score: resultScore,
    solvedFlags: solvedAt.map(Boolean)
  });
  try {
    await updateChallenge(activeChallenge.code, patch);
    forgetPendingChallengeResult(activeChallenge.code);
    clearChallengeProgress(activeChallenge.code);
    rememberChallengePlayed(activeChallenge.code, prefix);
    const row = await fetchChallenge(activeChallenge.code);
    await renderChallengeResult(row, resultScore, { showPanelWords: true, solvedFlags: solvedAt.map(Boolean) });
    refreshChallengePanel();
    refreshAvatarAchievements({ popup: true }).catch(() => {});
  } catch {
    renderChallengePanel("Резултат је сачуван локално; покушаћу поново online.");
  }
  render();
}

async function surrenderChallenge(row) {
  if (!row?.code || !supabaseConfigured()) return;
  const role = challengeRole(row);
  if (!role || challengeAlreadyPlayed(row, role)) return;
  const otherRole = role === "creator" ? "opponent" : "creator";
  const patch = {
    [`${role}_score`]: 0,
    [`${role}_attempts`]: 0,
    [`${role}_solved`]: 0,
    [`${role}_played_at`]: new Date().toISOString()
  };
  patch.status = challengeSidePlayed(row, otherRole) ? "played" : "accepted";
  await updateChallenge(row.code, patch);
  if (activeChallenge?.code === row.code) {
    clearChallengeProgress(row.code);
    clearActiveChallenge();
    activeChallenge = null;
  }
  renderChallengePanel("Изазов је предат.");
  refreshChallengePanel();
}

function confirmSurrenderChallenge(row) {
  showWordModal({
    title: "Предаја изазова",
    word: "изазов",
    text: "Да ли сигурно желиш да предаш овај изазов?",
    reviewText: "Када потврдиш, овај изазов се уписује као одигран са твоје стране.",
    buttons: [
      {
        label: "Да, предај",
        tone: "danger",
        onClick: () => {
          closeWordModal();
          surrenderChallenge(row).catch(() => renderChallengePanel("Предаја изазова није успела."));
        }
      },
      {
        label: "Не",
        tone: "success",
        onClick: closeWordModal
      }
    ]
  });
}

function loadPlayerName() {
  return (localStorage.getItem(PLAYER_NAME_KEY) || "").trim();
}

function hasRegisteredPlayerProfile() {
  const name = loadPlayerName();
  const avatarId = String(localStorage.getItem(PROFILE_AVATAR_KEY) || "").trim();
  if (!name || !avatarId) return false;
  return Boolean(profileAvatarById(avatarId) || (isWeekendWitchActive() && isWeekendEventAvatarId(avatarId)));
}

function normalizePlayerName(value) {
  return (String(value || "").trim().replace(/\s+/g, " ").slice(0, 18) || "Играч");
}

function savePlayerName(value) {
  const clean = normalizePlayerName(value);
  localStorage.setItem(PLAYER_NAME_KEY, clean);
  if (playerNameInput) playerNameInput.value = clean;
  updateChallengePlayerName();
  updateStatusProfile();
  return clean;
}

function loadRenameCount() {
  const count = Number(localStorage.getItem(PLAYER_RENAME_COUNT_KEY) || "0");
  return Number.isFinite(count) ? Math.max(0, count) : 0;
}

function saveRenameCount(count) {
  localStorage.setItem(PLAYER_RENAME_COUNT_KEY, String(Math.max(0, count)));
}

function updateChallengePlayerName() {
  if (!challengePlayerNameEl) return;
  const name = loadPlayerName() || "Играч";
  const left = Math.max(0, 3 - loadRenameCount());
  challengePlayerNameEl.textContent = `${name} · измена ${left}/3`;
}

function playerInitial(name) {
  const clean = normalizePlayerName(name);
  return clean.slice(0, 1).toUpperCase();
}

function emptyAvatarAchievementStats() {
  return {
    normalStarted: Number(loadNormalStats().started) || 0,
    tournaments: loadResults().filter(isFinalResult).length,
    challengeWins: 0,
    bestStreak: Math.max(0, ...loadResults().map((row) => Number(row.streak) || 0))
  };
}

function profileAvatarUnlockInfo(avatar = {}) {
  return avatar.unlockGroup ? PROFILE_UNLOCK_GROUPS[avatar.unlockGroup] || null : null;
}

function adminProfileAvatarFromNumber(group = "male", number = 0) {
  const cleanNumber = Number(number) || 0;
  if (cleanNumber < 100) return null;
  const isFemale = group === "female";
  return {
    id: `${isFemale ? "female" : "male"}-${cleanNumber}`,
    group: isFemale ? "female" : "male",
    label: `${isFemale ? "Ж" : "М"}${cleanNumber}`,
    src: `avatar/${isFemale ? "Z" : "M"}${cleanNumber}.png`,
    adminOnly: true
  };
}

function adminProfileAvatarFromCode(code = "") {
  const raw = String(code || "").trim();
  const upper = raw.toUpperCase();
  if (!upper) return null;
  let match = upper.match(/^MALE-(\d+)$/);
  if (match) return adminProfileAvatarFromNumber("male", match[1]);
  match = upper.match(/^FEMALE-(\d+)$/);
  if (match) return adminProfileAvatarFromNumber("female", match[1]);
  match = upper.match(/^[MМ](\d+)$/);
  if (match) return adminProfileAvatarFromNumber("male", match[1]);
  match = upper.match(/^[ZЗЖ](\d+)$/);
  if (match) return adminProfileAvatarFromNumber("female", match[1]);
  match = upper.match(/\/([MМZЗЖ])(\d+)\.PNG$/);
  if (match) {
    return adminProfileAvatarFromNumber(/[ZЗЖ]/.test(match[1]) ? "female" : "male", match[2]);
  }
  return null;
}

function isProfileAvatarUnlocked(avatar = {}, stats = avatarAchievementStats || emptyAvatarAchievementStats()) {
  if (avatar.adminOnly) return false;
  // Lovac i Veštice su isključivo sezonski avatari — zaključani su van Witch Hunta.
  if (isWeekendEventAvatarId(avatar.id)) return isWeekendWitchActive();
  const info = profileAvatarUnlockInfo(avatar);
  return !info || info.unlocked(stats);
}

function unlockedProfileAvatars(stats = avatarAchievementStats || emptyAvatarAchievementStats()) {
  const activeStats = stats || avatarAchievementStats || emptyAvatarAchievementStats();
  return SELECTABLE_PROFILE_AVATARS.filter((avatar) => isProfileAvatarUnlocked(avatar, activeStats));
}

function saveApprovedProfileAvatarId(id = "") {
  const avatar = profileAvatarById(id);
  if (avatar) {
    localStorage.setItem(PROFILE_AVATAR_APPROVED_KEY, avatar.id);
    return avatar.id;
  }
  localStorage.removeItem(PROFILE_AVATAR_APPROVED_KEY);
  return "";
}

function isProfileAvatarApproved(id = "") {
  return Boolean(id && !isWeekendEventAvatarId(id) && localStorage.getItem(PROFILE_AVATAR_APPROVED_KEY) === id);
}

function loadWeekendWitchState() {
  try {
    return { weekend: weekendWitchId(), ...JSON.parse(localStorage.getItem(WEEKEND_WITCH_KEY) || "{}") };
  } catch {
    return { weekend: weekendWitchId() };
  }
}

function saveWeekendWitchState(data = {}) {
  localStorage.setItem(WEEKEND_WITCH_KEY, JSON.stringify({ ...data, weekend: weekendWitchId() }));
}

function syncWeekendWitchAvatarState() {
  const active = isWeekendWitchActive();
  const current = localStorage.getItem(PROFILE_AVATAR_KEY) || "";
  if (active) {
    const state = loadWeekendWitchState();
    if (state.weekend !== weekendWitchId()) saveWeekendWitchState({});
    if (isWeekendEventAvatarId(current)) return;
    const avatar = profileAvatarById(current) || PROFILE_AVATARS[0];
    if (current && !localStorage.getItem(WEEKEND_WITCH_PREVIOUS_AVATAR_KEY)) {
      localStorage.setItem(WEEKEND_WITCH_PREVIOUS_AVATAR_KEY, avatar.id);
    }
    if (challengeAvatarIsMale(avatar)) {
      const hunter = challengeWeekendHunterAvatar();
      localStorage.setItem(PROFILE_AVATAR_KEY, hunter.id);
      saveWeekendWitchState({ selected: hunter.id });
      const player = loadPlayerName();
      if (player) PLAYER_AVATAR_CACHE.set(playerAvatarCacheKey(player), hunter.id);
      syncProfileAvatarToSupabase(hunter.id).catch(() => false);
    } else {
      const witch = challengeWeekendWitchAvatar(loadPlayerName());
      if (!witch) return;
      localStorage.setItem(PROFILE_AVATAR_KEY, witch.id);
      saveWeekendWitchState({ selected: witch.id });
      const player = loadPlayerName();
      if (player) PLAYER_AVATAR_CACHE.set(playerAvatarCacheKey(player), witch.id);
      syncProfileAvatarToSupabase(witch.id).catch(() => false);
    }
    return;
  }
  if (!isWeekendEventAvatarId(current)) return;
  const previous = localStorage.getItem(WEEKEND_WITCH_PREVIOUS_AVATAR_KEY);
  const eventAvatar = profileAvatarById(current);
  const candidates = BASE_PROFILE_AVATARS.filter((avatar) => avatar.group === eventAvatar?.group);
  const seed = `${weekendWitchId()}|${profileDeviceId()}|${loadPlayerName()}|${eventAvatar?.group || "male"}`;
  let hash = 0;
  [...seed].forEach((letter) => { hash = ((hash * 31) + letter.charCodeAt(0)) >>> 0; });
  const fallback = previous && !isWeekendEventAvatarId(previous) && profileAvatarById(previous)
    && isProfileAvatarUnlocked(profileAvatarById(previous))
    ? previous
    : (candidates[hash % candidates.length] || PROFILE_AVATARS[0]).id;
  localStorage.setItem(PROFILE_AVATAR_KEY, fallback);
  localStorage.removeItem(WEEKEND_WITCH_PREVIOUS_AVATAR_KEY);
  if (isWeekendEventAvatarId(localStorage.getItem(PROFILE_AVATAR_APPROVED_KEY))) {
    saveApprovedProfileAvatarId("");
  }
  saveWeekendWitchState({});
  // Osnovni avatar u Supabase-u nije menjan tokom vikenda, zato ga ovde ne prepisujemo.
}

function loadProfileAvatarId() {
  syncWeekendWitchAvatarState();
  const id = localStorage.getItem(PROFILE_AVATAR_KEY) || PROFILE_AVATARS[0].id;
  const avatar = profileAvatarById(id);
  return avatar && (isProfileAvatarUnlocked(avatar) || isProfileAvatarApproved(avatar.id) || (isWeekendWitchActive() && isWeekendEventAvatarId(avatar.id)))
    ? avatar.id
    : PROFILE_AVATARS[0].id;
}

function profileAvatarById(id) {
  const clean = String(id || "").trim();
  return PROFILE_AVATARS.find((avatar) => avatar.id === clean) || adminProfileAvatarFromCode(clean);
}

function profileAvatarByCode(code) {
  const clean = String(code || "").trim().toUpperCase();
  if (!clean) return null;
  return PROFILE_AVATARS.find((avatar) => (
    String(avatar.id || "").toUpperCase() === clean ||
    String(avatar.label || "").toUpperCase() === clean ||
    String(avatar.src || "").toUpperCase().endsWith(`/${clean}.PNG`)
  )) || adminProfileAvatarFromCode(clean);
}

function currentProfileAvatar() {
  return profileAvatarById(loadProfileAvatarId()) || PROFILE_AVATARS[0];
}

function normalizeProfileAvatarId(id) {
  const avatar = profileAvatarById(id);
  return avatar && (isProfileAvatarUnlocked(avatar) || isProfileAvatarApproved(avatar.id) || (isWeekendWitchActive() && isWeekendEventAvatarId(avatar.id)))
    ? avatar.id
    : PROFILE_AVATARS[0].id;
}

function playerAvatarCacheKey(name) {
  return normalizePlayerName(name).toLowerCase();
}

function weekendAvatarFromPlayerRow(row = {}) {
  const weekendAvatar = profileAvatarById(row.weekend_avatar_id);
  return isWeekendWitchActive() && row.weekend_avatar_weekend === weekendWitchId() && weekendAvatar
    ? weekendAvatar
    : profileAvatarById(row.avatar_id);
}

function cachePlayerAvatar(row = {}) {
  const key = playerAvatarCacheKey(row.nickname);
  const avatar = weekendAvatarFromPlayerRow(row);
  if (key && avatar) PLAYER_AVATAR_CACHE.set(key, avatar.id);
}

function applySupabaseProfileAvatar(row = {}, nickname = loadPlayerName()) {
  const avatar = profileAvatarById(row.avatar_id);
  const cleanName = normalizePlayerName(nickname || row.nickname || "");
  if (!avatar) return false;
  if (isWeekendEventAvatarId(avatar.id) && !isWeekendWitchActive()) return false;
  if (!isWeekendEventAvatarId(avatar.id)) saveApprovedProfileAvatarId(avatar.id);
  localStorage.setItem(PROFILE_AVATAR_KEY, normalizeProfileAvatarId(avatar.id));
  if (cleanName) PLAYER_AVATAR_CACHE.set(playerAvatarCacheKey(cleanName), avatar.id);
  // Kada Supabase vrati stalni avatar usred Witch Hunta, odmah ponovo prikaži
  // odgovarajućeg Lovca ili Vešticu i sačuvaj ga samo u vikend poljima.
  if (isWeekendWitchActive()) syncWeekendWitchAvatarState();
  updateStatusProfile();
  return true;
}

function cachedProfileAvatar(name = "") {
  const id = PLAYER_AVATAR_CACHE.get(playerAvatarCacheKey(name));
  return profileAvatarById(id);
}

function deterministicProfileAvatar(name = "") {
  const clean = normalizePlayerName(name) || "petko";
  let hash = 0;
  [...clean].forEach((letter) => {
    hash = ((hash << 5) - hash) + letter.charCodeAt(0);
    hash |= 0;
  });
  return BASE_PROFILE_AVATARS[Math.abs(hash) % BASE_PROFILE_AVATARS.length] || PROFILE_AVATARS[0];
}

function appendAvatarImage(target, avatar = {}, fallbackName = "") {
  const image = document.createElement("img");
  image.src = avatar.src;
  image.alt = avatar.label || "Аватар";
  image.loading = "lazy";
  image.addEventListener("error", () => {
    target.innerHTML = "";
    target.classList.remove("has-image");
    target.textContent = avatar.label || playerInitial(fallbackName || loadPlayerName());
  }, { once: true });
  target.append(image);
}

function renderAvatarForName(target, name = "", options = {}) {
  if (!target) return;
  let avatar = options.avatar || null;
  if (!avatar) {
    avatar = options.current || sameChallengeName(name, loadPlayerName())
      ? currentProfileAvatar()
      : cachedProfileAvatar(name) || deterministicProfileAvatar(name);
  }
  // Tokom Witch Hunta svaki profil u listama i rezultatima dobija sezonu:
  // muškarci su Lovci, a žene Veštice.
  if (isWeekendWitchActive()) avatar = challengeDisplayAvatar(avatar, name);
  target.innerHTML = "";
  target.classList.toggle("has-image", Boolean(avatar?.src));
  if (avatar?.src) {
    appendAvatarImage(target, avatar, name);
    return;
  }
  target.textContent = avatar?.label || playerInitial(name || loadPlayerName());
}

function renderAvatarText(target, fallbackName = "") {
  if (!target) return;
  const avatar = currentProfileAvatar();
  target.innerHTML = "";
  target.classList.toggle("has-image", Boolean(avatar?.src));
  if (avatar?.src) {
    appendAvatarImage(target, avatar, fallbackName);
    return;
  }
  target.textContent = avatar?.label || playerInitial(fallbackName || loadPlayerName());
}

function saveProfileAvatar(id) {
  const avatar = profileAvatarById(id);
  const weekendAvatar = avatar && isWeekendWitchActive() && isWeekendEventAvatarId(avatar.id);
  if (avatar && !isProfileAvatarUnlocked(avatar) && !isProfileAvatarApproved(avatar.id) && !weekendAvatar) {
    setProfileMessage(profileAvatarUnlockInfo(avatar)?.requirement || "Овај аватар је још закључан.");
    return;
  }
  const cleanId = normalizeProfileAvatarId(id);
  if (isWeekendEventAvatarId(cleanId) && isWeekendWitchActive()) {
    const current = localStorage.getItem(PROFILE_AVATAR_KEY) || PROFILE_AVATARS[0].id;
    if (!isWeekendEventAvatarId(current)) {
      localStorage.setItem(WEEKEND_WITCH_PREVIOUS_AVATAR_KEY, current);
    }
    saveWeekendWitchState({ selected: cleanId });
    const data = loadWeekendWitchChallengeBonus();
    if (data.weekend !== weekendWitchId() || !data.lastAwardAt) {
      saveWeekendWitchChallengeBonus(emptyWeekendWitchChallengeBonus());
    }
  }
  localStorage.setItem(PROFILE_AVATAR_KEY, cleanId);
  const cleanAvatar = profileAvatarById(cleanId);
  if (cleanAvatar && isProfileAvatarUnlocked(cleanAvatar)) saveApprovedProfileAvatarId("");
  const player = loadPlayerName();
  if (player) PLAYER_AVATAR_CACHE.set(playerAvatarCacheKey(player), cleanId);
  updateStatusProfile();
  renderProfileModal();
  ensurePlayerRowInSupabase()
    .then((ok) => {
      if (!ok) return syncProfileAvatarToSupabase(cleanId);
      return true;
    })
    .catch(() => syncProfileAvatarToSupabase(cleanId).catch(() => false));
}

async function syncProfileAvatarToSupabase(id = loadProfileAvatarId()) {
  if (!supabaseConfigured()) return false;
  const cleanId = normalizeProfileAvatarId(id);
  const name = normalizePlayerName(loadPlayerName() || "");
  const weekendAvatar = isWeekendWitchActive() && isWeekendEventAvatarId(cleanId);
  // Za vreme Witch Hunta stalni avatar je zaključan za upis.
  // Samo sezonski Lovac/Veštica sme da se šalje u weekend_avatar_id.
  if (isWeekendWitchActive() && !weekendAvatar) return true;
  const patch = weekendAvatar
    ? { weekend_avatar_id: cleanId, weekend_avatar_weekend: weekendWitchId() }
    : { avatar_id: cleanId };
  const jobs = [];
  if (profileDeviceId()) {
    jobs.push(patchSupabaseRows(`${playersTable()}?device_id=eq.${encodeURIComponent(profileDeviceId())}`, patch));
  }
  if (name) {
    jobs.push(patchSupabaseRows(`${playersTable()}?nickname=eq.${encodeURIComponent(name)}`, patch));
  }
  if (!jobs.length) return false;
  await Promise.allSettled(jobs);
  return true;
}

function playerAvatarRegistrationPayload(id = loadProfileAvatarId()) {
  const cleanId = normalizeProfileAvatarId(id);
  if (!isWeekendWitchActive() || !isWeekendEventAvatarId(cleanId)) {
    return { avatar_id: cleanId };
  }
  const previous = localStorage.getItem(WEEKEND_WITCH_PREVIOUS_AVATAR_KEY);
  const baseAvatar = previous && !isWeekendEventAvatarId(previous) && profileAvatarById(previous)
    ? previous
    : deterministicProfileAvatar(loadPlayerName()).id;
  return {
    // Osnovni avatar ostaje trajni avatar; sezonski se čuva odvojeno.
    avatar_id: baseAvatar,
    weekend_avatar_id: cleanId,
    weekend_avatar_weekend: weekendWitchId()
  };
}

function updateTopScoreProfile(totalScore) {
  if (annualTopScoreEl) {
    annualTopScoreEl.textContent = formatScore(totalScore ?? 0);
  }
  updateStatusProfile();
}

function updateStatusProfile() {
  if (!scoreCountEl || !statusProfileButton) return;
  const showProfile = gameType !== "competitive";
  scoreCountEl.classList.toggle("profile-mode", showProfile);
  if (scoreTotalLineEl) scoreTotalLineEl.hidden = showProfile;
  if (scoreDifferenceLineEl) scoreDifferenceLineEl.hidden = showProfile;
  statusProfileButton.hidden = !showProfile;
  if (!showProfile) return;
  const name = loadPlayerName() || "Играч";
  renderAvatarText(statusProfileAvatar, name);
  if (statusProfileName) statusProfileName.textContent = name;
  statusProfileButton.setAttribute("aria-label", `Профил играча ${name}`);
  statusProfileButton.title = "Профил играча";
}

function setProfileMessage(text = "") {
  if (profileMessage) profileMessage.textContent = text;
}

function setProfileEditMode(editing) {
  if (profileEditRow) profileEditRow.hidden = !editing;
  if (profileEditButton) profileEditButton.hidden = editing;
  if (profileNameInput && editing) {
    profileNameInput.value = loadPlayerName() || "";
    window.setTimeout(() => profileNameInput.focus(), 0);
  }
}

function setProfileLinkPanelOpen(open) {
  if (profileLinkCodePanel) profileLinkCodePanel.hidden = !open;
  if (profileLinkToggleButton) profileLinkToggleButton.setAttribute("aria-expanded", open ? "true" : "false");
}

function renderProfileAvatarGrid(group = "male") {
  if (!profileAvatarGrid) return;
  profileAvatarGrid.innerHTML = "";
  const stats = avatarAchievementStats || emptyAvatarAchievementStats();
  const witchPicker = isWeekendWitchActive() && !challengeAvatarIsMale(currentProfileAvatar());
  if (witchPicker) group = "female";
  if (profileAvatarUnlockNote) profileAvatarUnlockNote.textContent = witchPicker
    ? "Током Witch Hunta можеш изабрати једну од пет Вештица."
    : "Ваша достигнућа ће откључати нове аватаре.";
  profileAvatarTabs.forEach((tab) => tab.classList.toggle("active", tab.dataset.avatarTab === group));
  const visibleAvatars = witchPicker
    ? weekendWitchAvatars()
    : SELECTABLE_PROFILE_AVATARS.filter((avatar) => avatar.group === group);
  visibleAvatars.forEach((avatar) => {
    const locked = witchPicker ? false : !isProfileAvatarUnlocked(avatar, stats);
    const info = profileAvatarUnlockInfo(avatar);
    const seasonalLock = isWeekendEventAvatarId(avatar.id) && !isWeekendWitchActive();
    const button = document.createElement("button");
    button.type = "button";
    button.className = "profile-avatar-option";
    button.classList.toggle("active", avatar.id === loadProfileAvatarId());
    button.classList.toggle("locked", locked);
    button.title = locked ? (seasonalLock ? "Доступно само током Witch Hunta" : info?.requirement || "Закључано") : avatar.label;
    button.disabled = false;
    if (avatar.src) {
      const image = document.createElement("img");
      image.src = avatar.src;
      image.alt = avatar.label;
      image.loading = "lazy";
      image.addEventListener("error", () => {
        image.remove();
        button.append(document.createTextNode(avatar.label));
      }, { once: true });
      button.append(image);
    } else {
      button.textContent = avatar.label;
    }
    if (locked) {
      const lock = document.createElement("span");
      lock.className = "profile-avatar-lock";
      lock.textContent = "ЗАКЉ";
      button.append(lock);
    }
    button.addEventListener("click", () => {
      if (locked) {
        setProfileMessage(seasonalLock ? "Овај аватар је доступан само током Witch Hunta." : info?.requirement || "Овај аватар је још закључан.");
        return;
      }
      saveProfileAvatar(avatar.id);
      setProfileMessage("Аватар је промењен.");
    });
    profileAvatarGrid.append(button);
  });
}

function renderProfileModal() {
  const name = loadPlayerName() || "Играч";
  renderAvatarText(profileModalAvatar, name);
  if (profileModalName) profileModalName.textContent = name;
  if (profileNameInput) profileNameInput.value = name;
  if (profileLinkCode) profileLinkCode.textContent = profileConnectionCode();
  const activeGroup = profileAvatarTabs.find((tab) => tab.classList.contains("active"))?.dataset.avatarTab || "male";
  renderProfileAvatarGrid(activeGroup);
}

function openProfileModal() {
  if (!profileModal) return;
  renderProfileModal();
  refreshAvatarAchievements({ popup: true }).catch(() => {});
  setProfileEditMode(false);
  if (profileAvatarMenu) profileAvatarMenu.hidden = true;
  setProfileLinkPanelOpen(false);
  setProfileMessage("");
  profileModal.hidden = false;
}

function closeProfileModal() {
  if (profileModal) profileModal.hidden = true;
}

function showProfileHintOnce() {
  if (!statusProfileButton || localStorage.getItem(PROFILE_HINT_SEEN_KEY) === "1") return;
  localStorage.setItem(PROFILE_HINT_SEEN_KEY, "1");
  window.setTimeout(() => {
    if (gameType === "competitive" || statusProfileButton.hidden) return;
    statusProfileButton.classList.add("profile-hint");
    showPetkoMood("think", "Овде уреди профил: име и аватар.", 3000, { force: true, sideShift: -22 });
    window.setTimeout(() => statusProfileButton.classList.remove("profile-hint"), 3100);
  }, 900);
}

async function saveProfileNameChange() {
  const current = loadPlayerName() || "";
  const used = loadRenameCount();
  const next = normalizePlayerName(profileNameInput?.value || "");
  if (!next || sameChallengeName(next, current)) {
    if (current) await ensurePlayerRowInSupabase().catch(() => false);
    setProfileEditMode(false);
    renderProfileModal();
    return;
  }
  if (await playerNameTaken(next)) {
    if (await recoverExistingPlayerProfile(next)) return;
    setProfileMessage(`Надимак "${next}" већ постоји. Пробај други назив.`);
    return;
  }

  const previous = current;
  const firstRegistration = !previous;

  if (firstRegistration) {
    // Prvi unos imena mora da kreira red u players — inače se ne vidi u bazi dok ne odigra.
    const registered = await registerPlayerName(next).catch(() => null);
    if (registered === false) {
      setProfileMessage(`Надимак "${next}" већ постоји. Пробај други назив.`);
      return;
    }
    if (registered !== true) {
      setProfileMessage("Упис играча у базу није успео. Пробај поново.");
      return;
    }
    savePlayerName(next);
    updateChallengePlayerName();
    renderProfileModal();
    setProfileEditMode(false);
    setProfileMessage(`Профил је сачуван као ${next}.`);
    refreshWordEditorPermission().catch(() => false);
    refreshChallengePanel();
    refreshOnlineLeaderboard();
    return;
  }

  if (used >= 3) {
    setProfileMessage("Име можеш променити највише 3 пута.");
    return;
  }
  savePlayerName(next);
  saveRenameCount(used + 1);
  updateChallengePlayerName();
  await renamePlayerEverywhere(previous, next);
  await ensurePlayerRowInSupabase().catch(() => false);
  renderProfileModal();
  setProfileEditMode(false);
  setProfileMessage(`Име је промењено у ${next}.`);
  refreshWordEditorPermission().catch(() => false);
  if (gameType === "challenge") renderChallengePanel(`Име је промењено у ${next}.`);
  refreshChallengePanel();
  refreshOnlineLeaderboard();
}

async function patchSupabaseRows(path, body) {
  if (!supabaseConfigured()) return false;
  const response = await fetch(supabaseUrl(path), {
    method: "PATCH",
    headers: supabaseJsonHeaders({ Prefer: "return=minimal" }),
    body: JSON.stringify(body)
  });
  return response.ok;
}

async function callSupabaseRpc(functionName, body = {}) {
  if (!supabaseConfigured()) return false;
  const response = await fetch(supabaseUrl(`rpc/${functionName}`), {
    method: "POST",
    headers: supabaseJsonHeaders({ Prefer: "return=minimal" }),
    body: JSON.stringify(body)
  });
  return response.ok;
}

function renameInChallengeObject(item, oldName, newName) {
  if (!item || typeof item !== "object") return item;
  if (sameChallengeName(item.creator, oldName)) item.creator = newName;
  if (sameChallengeName(item.opponent, oldName)) item.opponent = newName;
  return item;
}

function renamePlayerLocally(oldName, newName) {
  const active = loadActiveChallenge();
  if (active) {
    saveActiveChallenge(renameInChallengeObject(active, oldName, newName));
  }
  const sent = loadSentChallengeRowsToday();
  if (sent.length) {
    localStorage.setItem(CHALLENGE_SENT_KEY, JSON.stringify({
      entries: sent.map((entry) => renameInChallengeObject(entry, oldName, newName))
    }));
  }
  const progressStore = loadChallengeProgressStore();
  Object.keys(progressStore).forEach((code) => {
    if (progressStore[code]?.active) {
      renameInChallengeObject(progressStore[code].active, oldName, newName);
    }
  });
  saveChallengeProgressStore(progressStore);
}

async function renamePlayerEverywhere(oldName, newName) {
  if (!oldName || sameChallengeName(oldName, newName)) return;
  renamePlayerLocally(oldName, newName);
  if (!supabaseConfigured()) return;
  const oldFilter = encodeURIComponent(oldName);
  await Promise.allSettled([
    patchSupabaseRows(`${playersTable()}?nickname=eq.${oldFilter}`, { nickname: newName }),
    patchSupabaseRows(`${playersTable()}?device_id=eq.${encodeURIComponent(deviceId())}`, { nickname: newName }),
    patchSupabaseRows(`${SUPABASE_CONFIG.table}?nickname=eq.${oldFilter}`, { nickname: newName }),
    patchSupabaseRows(`${normalStatsTable()}?nickname=eq.${oldFilter}`, { nickname: newName }),
    patchSupabaseRows(`${lectorStatsTable()}?nickname=eq.${oldFilter}`, { nickname: newName }),
    patchSupabaseRows(`${wordReportsTable()}?nickname=eq.${oldFilter}`, { nickname: newName }),
    patchSupabaseRows(`${challengeTable()}?creator=eq.${oldFilter}`, { creator: newName }),
    patchSupabaseRows(`${challengeTable()}?opponent=eq.${oldFilter}`, { opponent: newName }),
    callSupabaseRpc("rename_challenge_stats_player", { old_name: oldName, new_name: newName })
  ]);
}

async function editChallengePlayerName() {
  const current = loadPlayerName() || "";
  const used = loadRenameCount();
  if (used >= 3) {
    renderChallengePanel("Име можеш променити највише 3 пута.");
    return;
  }
  openProfileModal();
  setProfileEditMode(true);
  if (profileNameInput) profileNameInput.value = current;
}

async function fetchPlayerRows() {
  if (!supabaseConfigured()) return [];
  const query = [
    "select=nickname,created_at,last_seen,device_id,avatar_id,weekend_avatar_id,weekend_avatar_weekend,challenge_bonus",
    "order=nickname.asc",
    "limit=1000"
  ].join("&");
  const response = await fetch(supabaseUrl(`${playersTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return null;
  const rows = await response.json();
  if (!Array.isArray(rows)) return [];
  rows.forEach(cachePlayerAvatar);
  return rows;
}

async function ensurePlayerRowInSupabase() {
  if (!supabaseConfigured()) return false;
  const name = normalizePlayerName(loadPlayerName() || "");
  if (!name) return false;
  const registered = await registerPlayerName(name).catch(() => null);
  if (registered === true) return true;
  if (registered === false) {
    return patchSupabaseRows(`${playersTable()}?nickname=eq.${encodeURIComponent(name)}`, {
      device_id: deviceId(),
      last_seen: new Date().toISOString(),
      ...playerAvatarRegistrationPayload()
    });
  }
  return false;
}

async function touchPlayerLastSeen() {
  if (!supabaseConfigured() || !hasRegisteredPlayerProfile()) return false;
  return ensurePlayerRowInSupabase();
}

async function refreshChallengePlayerAvatars() {
  const rows = await fetchPlayerRows();
  if (Array.isArray(rows)) rows.forEach(cachePlayerAvatar);
  return rows;
}

async function registerPlayerName(name) {
  if (!supabaseConfigured()) return true;
  const clean = normalizePlayerName(name);
  const response = await fetch(supabaseUrl(playersTable()), {
    method: "POST",
    headers: supabaseJsonHeaders({ Prefer: "return=minimal" }),
    body: JSON.stringify({
      nickname: clean,
      device_id: deviceId(),
      last_seen: new Date().toISOString(),
      ...playerAvatarRegistrationPayload()
    })
  });
  if (response.ok) return true;
  if (response.status === 409) return false;
  return null;
}

async function syncCurrentPlayerDevice() {
  return ensurePlayerRowInSupabase();
}

async function playerNameTaken(name) {
  const clean = normalizePlayerName(name);
  const current = loadPlayerName();
  if (!supabaseConfigured() || sameChallengeName(clean, current)) return false;
  const playerRows = await fetchPlayerRows().catch(() => null);
  if (Array.isArray(playerRows)) {
    return playerRows.some((row) => sameChallengeName(row.nickname, clean));
  }
  const [normalRows, scoreRows, challengeRows] = await Promise.all([
    fetchNormalStatsRows().catch(() => []),
    fetchOnlineLeaderboard().catch(() => []),
    fetchChallengeHistory().catch(() => [])
  ]);
  return [
    ...(normalRows || []).map((row) => row.nickname),
    ...(scoreRows || []).map((row) => row.nickname),
    ...(challengeRows || []).flatMap((row) => [row.creator, row.opponent])
  ].some((value) => sameChallengeName(value, clean));
}

async function claimChallengePlayerName(name, invitedOpponent = "") {
  const clean = normalizePlayerName(name);
  const invited = cleanChallengeName(invitedOpponent);
  const acceptingDirectedInvite = invited && sameChallengeName(clean, invited);
  const previous = loadPlayerName();

  if (acceptingDirectedInvite) {
    if (previous && sameChallengeName(clean, previous)) {
      await syncCurrentPlayerDevice().catch(() => false);
      return previous;
    }
    const registered = await registerPlayerName(clean).catch(() => null);
    if (registered === true) return savePlayerName(clean);
    if (registered === false) {
      const encodedName = encodeURIComponent(clean);
      const patched = await patchSupabaseRows(`${playersTable()}?nickname=eq.${encodedName}`, {
        device_id: deviceId()
      });
      if (patched) return savePlayerName(clean);
    }
    if (playerNameInput) playerNameInput.value = previous;
    return "";
  }

  return savePlayerNameUnique(clean);
}

async function savePlayerNameUnique(value) {
  const clean = normalizePlayerName(value);
  const previous = loadPlayerName();
  if (previous && sameChallengeName(clean, previous)) {
    if (playerNameInput) playerNameInput.value = previous;
    await ensurePlayerRowInSupabase().catch(() => false);
    return previous;
  }
  if (await playerNameTaken(clean)) {
    if (playerNameInput) playerNameInput.value = previous;
    messageEl.textContent = `Надимак "${clean}" већ постоји. Изабери други.`;
    return "";
  }
  const registered = await registerPlayerName(clean).catch(() => null);
  if (registered === false) {
    if (playerNameInput) playerNameInput.value = previous;
    messageEl.textContent = `Надимак "${clean}" већ постоји. Изабери други.`;
    return "";
  }
  if (registered !== true) {
    if (playerNameInput) playerNameInput.value = previous;
    messageEl.textContent = "Упис играча у базу није успео. Пробај поново.";
    return "";
  }
  return savePlayerName(clean);
}

function ensurePlayerName() {
  const saved = loadPlayerName();
  if (saved) return saved;
  return savePlayerName("Играч");
}

function deviceId() {
  let id = localStorage.getItem(DEVICE_ID_KEY);
  if (id) return id;
  id = crypto.randomUUID ? crypto.randomUUID() : `d-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  localStorage.setItem(DEVICE_ID_KEY, id);
  return id;
}

function profileDeviceId() {
  return localStorage.getItem(PROFILE_DEVICE_ID_KEY) || deviceId();
}

function profileConnectionCode() {
  return `PK-${deviceId().toUpperCase()}`;
}

function parseProfileConnectionCode(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  return raw.replace(/^PK[-\s]*/i, "").trim().toLowerCase();
}

function dayNumber(dateText) {
  const date = new Date(`${dateText}T00:00:00`);
  return Math.floor(date.getTime() / 86400000);
}

function currentStreakFor(status) {
  if (status !== "finished") return 0;
  let streak = 1;
  let expected = dayNumber(todayId()) - 1;
  const previous = loadResults()
    .filter((result) => result.date !== todayId() && isFinalResult(result))
    .sort((a, b) => b.date.localeCompare(a.date));

  for (const result of previous) {
    const day = dayNumber(result.date);
    if (day !== expected) break;
    if (result.status !== "finished") break;
    streak += 1;
    expected -= 1;
  }

  return streak;
}

function todayResult() {
  return loadResults().find((result) => result.date === todayId() && isFinalResult(result));
}

function todayLock() {
  try {
    const lock = JSON.parse(localStorage.getItem(LOCK_STORAGE_KEY) || "null");
    if (lock && lock.date === todayId() && isFinalResult(lock)) return lock;
  } catch {}

  const existing = loadResults().find((result) => result.date === todayId() && isFinalResult(result));
  return existing || null;
}

function loadTodayLock() {
  return todayLock();
}

function saveTodayLock(patch) {
  const lock = {
    date: todayId(),
    ...patch,
    updatedAt: new Date().toISOString()
  };
  localStorage.setItem(LOCK_STORAGE_KEY, JSON.stringify(lock));
}

function clearCompetitiveProgress() {
  localStorage.removeItem(COMPETITIVE_PROGRESS_KEY);
  queueGameSessionClear("competitive");
}

function clearNormalProgress() {
  localStorage.removeItem(NORMAL_PROGRESS_KEY);
  queueGameSessionClear("normal");
}

function normalizeChallengeCode(value) {
  return String(value || "").trim().toUpperCase();
}

function loadChallengeProgressStore() {
  try {
    const data = JSON.parse(localStorage.getItem(CHALLENGE_PROGRESS_KEY) || "null");
    if (!data) return {};
    if (data.status === "in_progress" && data.active?.code) {
      return { [normalizeChallengeCode(data.active.code)]: data };
    }
    return data && typeof data === "object" ? data : {};
  } catch {}
  return {};
}

function saveChallengeProgressStore(store) {
  localStorage.setItem(CHALLENGE_PROGRESS_KEY, JSON.stringify(store || {}));
}

function clearChallengeProgress(code = activeChallenge?.code) {
  const cleanCode = normalizeChallengeCode(code);
  if (!cleanCode) {
    localStorage.removeItem(CHALLENGE_PROGRESS_KEY);
    return;
  }
  const store = loadChallengeProgressStore();
  delete store[cleanCode];
  saveChallengeProgressStore(store);
  queueGameSessionClear("challenge", cleanCode);
}

function loadCompetitiveProgress() {
  try {
    const progress = JSON.parse(localStorage.getItem(COMPETITIVE_PROGRESS_KEY) || "null");
    if (progress && progress.date === todayId() && progress.status === "in_progress") return progress;
  } catch {}
  return null;
}

function saveCompetitiveProgress() {
  if (gameType !== "competitive" || !competitiveRunActive) return;
  const progress = {
    date: todayId(),
    status: "in_progress",
    mode,
    done,
    competitiveLevelIndex,
    competitiveStarted,
    competitiveCompleted,
    score,
    lastLevelAward,
    targets,
    competitiveWordsPlayed,
    solvedAt,
    guesses,
    current,
    keyStates: [...keyStates.entries()],
    updatedAt: new Date().toISOString()
  };
  localStorage.setItem(COMPETITIVE_PROGRESS_KEY, JSON.stringify(progress));
  queueGameSessionUpsert("competitive", progress);
}

function loadNormalProgress() {
  try {
    const progress = JSON.parse(localStorage.getItem(NORMAL_PROGRESS_KEY) || "null");
    if (progress && progress.status === "in_progress") return progress;
  } catch {}
  return null;
}

function saveNormalProgress() {
  if (gameType !== "normal" || done) return;
  if (!normalStartedCounted && !current && !guesses.length) return;
  const progress = {
    status: "in_progress",
    mode,
    normalGameSeed,
    normalStartedCounted,
    targets,
    solvedAt,
    guesses,
    current,
    keyStates: [...keyStates.entries()],
    updatedAt: new Date().toISOString()
  };
  localStorage.setItem(NORMAL_PROGRESS_KEY, JSON.stringify(progress));
  queueGameSessionUpsert("normal", progress);
}

function loadChallengeProgress(code = activeChallenge?.code) {
  const cleanCode = normalizeChallengeCode(code);
  const store = loadChallengeProgressStore();
  const progress = cleanCode ? store[cleanCode] : Object.values(store).find((item) => item?.status === "in_progress" && item.active?.code);
  if (progress && progress.status === "in_progress" && progress.active?.code) return progress;
  return null;
}

function saveChallengeProgress() {
  if (gameType !== "challenge" || done || !activeChallenge?.code || targets.length !== CHALLENGE_WORDS) return;
  const progress = {
    status: "in_progress",
    active: activeChallenge,
    mode,
    score,
    targets,
    solvedAt,
    guesses,
    current,
    keyStates: [...keyStates.entries()],
    updatedAt: new Date().toISOString()
  };
  const store = loadChallengeProgressStore();
  store[normalizeChallengeCode(activeChallenge.code)] = progress;
  saveChallengeProgressStore(store);
  queueGameSessionUpsert("challenge", progress, activeChallenge.code);
}

function playerNicknameKey(name = loadPlayerName()) {
  return String(name || "").trim().toLowerCase();
}

function progressUpdatedAtMs(progress) {
  const value = Date.parse(progress?.updatedAt || "");
  return Number.isFinite(value) ? value : 0;
}

function preferNewerProgress(localProgress, remoteProgress) {
  if (!remoteProgress) return localProgress || null;
  if (!localProgress) return remoteProgress;
  return progressUpdatedAtMs(remoteProgress) >= progressUpdatedAtMs(localProgress)
    ? remoteProgress
    : localProgress;
}

function gameSessionKey(mode, challengeCode = "") {
  return `${mode}:${normalizeChallengeCode(challengeCode)}`;
}

function buildGameSessionRow(mode, progress, challengeCode = "") {
  if (!hasRegisteredPlayerProfile()) return null;
  const nickname = normalizePlayerName(loadPlayerName() || "");
  if (!nickname) return null;
  const cleanCode = mode === "challenge" ? normalizeChallengeCode(challengeCode || progress?.active?.code || "") : "";
  if (mode === "challenge" && !cleanCode) return null;
  return {
    nickname,
    nickname_key: playerNicknameKey(nickname),
    profile_device_id: profileDeviceId(),
    device_id: deviceId(),
    mode,
    challenge_code: cleanCode,
    day: progress?.date || (mode === "competitive" ? todayId() : null),
    status: progress?.status || "in_progress",
    payload: progress || {},
    updated_at: progress?.updatedAt || new Date().toISOString()
  };
}

async function upsertGameSessionRow(row) {
  if (!supabaseConfigured() || !row) return false;
  const response = await fetch(
    supabaseUrl(`${gameSessionsTable()}?on_conflict=nickname_key,mode,challenge_code`),
    {
      method: "POST",
      headers: supabaseJsonHeaders({
        Prefer: "resolution=merge-duplicates,return=minimal"
      }),
      body: JSON.stringify(row)
    }
  );
  return response.ok;
}

async function deleteGameSessionRow(mode, challengeCode = "") {
  if (!supabaseConfigured() || !hasRegisteredPlayerProfile()) return false;
  const nicknameKey = playerNicknameKey();
  if (!nicknameKey) return false;
  const cleanCode = mode === "challenge" ? normalizeChallengeCode(challengeCode) : "";
  const query = [
    `nickname_key=eq.${encodeURIComponent(nicknameKey)}`,
    `mode=eq.${encodeURIComponent(mode)}`,
    `challenge_code=eq.${encodeURIComponent(cleanCode)}`
  ].join("&");
  const response = await fetch(supabaseUrl(`${gameSessionsTable()}?${query}`), {
    method: "DELETE",
    headers: supabaseJsonHeaders({ Prefer: "return=minimal" })
  });
  return response.ok;
}

function queueGameSessionUpsert(mode, progress, challengeCode = "") {
  if (!supabaseConfigured() || !hasRegisteredPlayerProfile()) return;
  const key = gameSessionKey(mode, challengeCode);
  const existing = gameSessionSyncTimers.get(key);
  if (existing) clearTimeout(existing);
  const timer = setTimeout(() => {
    gameSessionSyncTimers.delete(key);
    const row = buildGameSessionRow(mode, progress, challengeCode);
    if (!row) return;
    upsertGameSessionRow(row).catch(() => {});
  }, GAME_SESSION_SYNC_DEBOUNCE_MS);
  gameSessionSyncTimers.set(key, timer);
}

function queueGameSessionClear(mode, challengeCode = "") {
  if (!supabaseConfigured() || !hasRegisteredPlayerProfile()) return;
  const key = gameSessionKey(mode, challengeCode);
  const existing = gameSessionSyncTimers.get(key);
  if (existing) clearTimeout(existing);
  gameSessionSyncTimers.delete(key);
  deleteGameSessionRow(mode, challengeCode).catch(() => {});
}

function flushGameSessionUpserts() {
  if (!supabaseConfigured() || !hasRegisteredPlayerProfile()) return;
  for (const [key, timer] of gameSessionSyncTimers.entries()) {
    clearTimeout(timer);
    gameSessionSyncTimers.delete(key);
  }
  const competitive = loadCompetitiveProgress();
  if (competitive) {
    const row = buildGameSessionRow("competitive", competitive);
    if (row) upsertGameSessionRow(row).catch(() => {});
  }
  const normal = loadNormalProgress();
  if (normal) {
    const row = buildGameSessionRow("normal", normal);
    if (row) upsertGameSessionRow(row).catch(() => {});
  }
  const store = loadChallengeProgressStore();
  Object.entries(store).forEach(([code, progress]) => {
    if (progress?.status !== "in_progress") return;
    const row = buildGameSessionRow("challenge", progress, code);
    if (row) upsertGameSessionRow(row).catch(() => {});
  });
}

async function fetchCloudGameSessions() {
  if (!supabaseConfigured() || !hasRegisteredPlayerProfile()) return [];
  const nicknameKey = playerNicknameKey();
  if (!nicknameKey) return [];
  const query = [
    "select=mode,challenge_code,day,status,payload,updated_at,nickname,profile_device_id,device_id",
    `nickname_key=eq.${encodeURIComponent(nicknameKey)}`,
    "status=eq.in_progress",
    "order=updated_at.desc"
  ].join("&");
  const response = await fetch(supabaseUrl(`${gameSessionsTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return [];
  const rows = await response.json();
  return Array.isArray(rows) ? rows : [];
}

function applyCloudGameSessionRow(row) {
  if (!row || row.status !== "in_progress" || !row.payload || typeof row.payload !== "object") return false;
  const payload = { ...row.payload };
  if (!payload.updatedAt && row.updated_at) payload.updatedAt = row.updated_at;
  if (row.mode === "competitive") {
    if (payload.date && payload.date !== todayId()) {
      queueGameSessionClear("competitive");
      return false;
    }
    const merged = preferNewerProgress(loadCompetitiveProgress(), payload);
    if (!merged || merged !== payload) return false;
    localStorage.setItem(COMPETITIVE_PROGRESS_KEY, JSON.stringify(merged));
    return true;
  }
  if (row.mode === "normal") {
    const merged = preferNewerProgress(loadNormalProgress(), payload);
    if (!merged || merged !== payload) return false;
    localStorage.setItem(NORMAL_PROGRESS_KEY, JSON.stringify(merged));
    return true;
  }
  if (row.mode === "challenge") {
    const code = normalizeChallengeCode(row.challenge_code || payload?.active?.code || "");
    if (!code) return false;
    const store = loadChallengeProgressStore();
    const merged = preferNewerProgress(store[code], payload);
    if (!merged || merged !== payload) return false;
    store[code] = merged;
    saveChallengeProgressStore(store);
    return true;
  }
  return false;
}

async function hydrateGameSessionsFromCloud({ force = false } = {}) {
  if (!supabaseConfigured() || !hasRegisteredPlayerProfile()) return false;
  if (gameSessionHydrateBusy) return false;
  if (!force && Date.now() - gameSessionLastHydratedAt < 2500) return false;
  gameSessionHydrateBusy = true;
  try {
    flushGameSessionUpserts();
    const rows = await fetchCloudGameSessions();
    let changed = false;
    rows.forEach((row) => {
      if (applyCloudGameSessionRow(row)) changed = true;
    });
    gameSessionLastHydratedAt = Date.now();
    return changed;
  } catch {
    return false;
  } finally {
    gameSessionHydrateBusy = false;
  }
}

function restoreCompetitiveProgress(progress) {
  gameType = "competitive";
  competitiveIntro = false;
  competitiveRunActive = true;
  done = Boolean(progress.done);
  mode = progress.mode || 1;
  competitiveLevelIndex = progress.competitiveLevelIndex || 0;
  competitiveStarted = progress.competitiveStarted || 1;
  competitiveCompleted = progress.competitiveCompleted || 0;
  if (done && competitiveCompleted > 0 && competitiveCompleted < COMPETITIVE_LEVELS.length) {
    competitiveLevelIndex = Math.min(competitiveLevelIndex, completedCompetitiveLevelIndex());
    mode = COMPETITIVE_LEVELS[competitiveLevelIndex];
  }
  score = progress.score || 0;
  targets = Array.isArray(progress.targets) ? progress.targets : [];
  competitiveWordsPlayed = Array.isArray(progress.competitiveWordsPlayed) ? progress.competitiveWordsPlayed : [];
  solvedAt = Array.isArray(progress.solvedAt) ? progress.solvedAt : Array(targets.length).fill(null);
  guesses = Array.isArray(progress.guesses) ? progress.guesses : [];
  current = progress.current || "";
  keyStates = new Map(Array.isArray(progress.keyStates) ? progress.keyStates : []);
  lastLevelAward = progress.lastLevelAward || null;
  bonusFlashRows = new Set();

  document.body.dataset.gameType = gameType;
  document.body.dataset.competitiveLocked = "false";
  document.body.dataset.competitiveIntro = "false";
  document.body.dataset.challengePlaying = "false";
  document.body.dataset.challengeFinished = "false";
  boardsEl.classList.remove("multi", "mega", "level-1", "level-2", "level-4", "level-8");
  boardsEl.classList.toggle("multi", mode > 1);
  boardsEl.classList.toggle("mega", mode === 8);
  boardsEl.classList.toggle("level-1", mode === 1);
  boardsEl.classList.toggle("level-2", mode === 2);
  boardsEl.classList.toggle("level-4", mode === 4);
  boardsEl.classList.toggle("level-8", mode === 8);
  typeButtons.forEach((button) => button.classList.toggle("active", button.dataset.type === gameType));
  updateModeButtons();
  updateCompetitiveNextButton();
  modeLabelEl.textContent = "";
  messageEl.textContent = done && !nextLevelButton.hidden
    ? levelAwardMessage()
    : "Настављено такмичење.";
  renderSolutionsPanel(false);
  render();
  saveCompetitiveProgress();
  renderListing();
  updateCompetitiveCountdown();
}

function restoreNormalProgress(progress) {
  gameType = "normal";
  competitiveIntro = false;
  competitiveRunActive = false;
  normalStartedCounted = Boolean(progress.normalStartedCounted);
  done = false;
  mode = 1;
  score = 0;
  normalGameSeed = progress.normalGameSeed || 0;
  targets = Array.isArray(progress.targets) && progress.targets.length ? progress.targets : chooseTargets(1);
  solvedAt = Array.isArray(progress.solvedAt) ? progress.solvedAt : Array(targets.length).fill(null);
  guesses = Array.isArray(progress.guesses) ? progress.guesses : [];
  current = progress.current || "";
  keyStates = new Map(Array.isArray(progress.keyStates) ? progress.keyStates : []);
  lastLevelAward = null;
  bonusFlashRows = new Set();

  document.body.dataset.gameType = gameType;
  document.body.dataset.competitiveLocked = "false";
  document.body.dataset.competitiveIntro = "false";
  document.body.dataset.challengePlaying = "false";
  document.body.dataset.challengeFinished = "false";
  boardsEl.classList.remove("multi", "mega", "level-1", "level-2", "level-4", "level-8");
  boardsEl.classList.add("level-1");
  typeButtons.forEach((button) => button.classList.toggle("active", button.dataset.type === gameType));
  updateModeButtons();
  nextLevelButton.hidden = true;
  modeLabelEl.textContent = "Обичан";
  messageEl.textContent = "";
  renderSolutionsPanel(false);
  render();
  renderListing();
  updateCompetitiveCountdown();
}

function restoreChallengeProgress(progress) {
  gameType = "challenge";
  competitiveIntro = false;
  competitiveRunActive = false;
  activeChallenge = progress.active || null;
  if (activeChallenge) saveActiveChallenge(activeChallenge);
  done = false;
  mode = CHALLENGE_WORDS;
  score = Number(progress.score) || 0;
  targets = Array.isArray(progress.targets) ? progress.targets : [];
  solvedAt = Array.isArray(progress.solvedAt) ? progress.solvedAt : Array(targets.length).fill(null);
  guesses = Array.isArray(progress.guesses) ? progress.guesses : [];
  current = progress.current || "";
  keyStates = new Map(Array.isArray(progress.keyStates) ? progress.keyStates : []);
  lastLevelAward = null;
  bonusFlashRows = new Set();

  document.body.dataset.gameType = gameType;
  document.body.dataset.competitiveLocked = "false";
  document.body.dataset.challengePlaying = "true";
  document.body.dataset.challengeFinished = "false";
  boardsEl.classList.remove("multi", "mega", "level-1", "level-2", "level-4", "level-8");
  boardsEl.classList.add("multi", "mega", "level-8");
  typeButtons.forEach((button) => button.classList.toggle("active", button.dataset.type === gameType));
  updateModeButtons();
  nextLevelButton.hidden = true;
  modeLabelEl.textContent = "Изазов";
  messageEl.textContent = `Настављаш изазов: ${activeChallenge?.creator || "Играч 1"} против ${activeChallenge?.opponent || "Играч 2"}.`;
  renderSolutionsPanel(false);
  renderChallengePanel();
  render();
}

function isFinalResult(result) {
  return result.status === "finished" || result.status === "failed";
}

function upsertTodayResult(patch) {
  const results = loadResults();
  const date = todayId();
  const existingIndex = results.findIndex((result) => result.date === date);
  const base = existingIndex === -1 ? { date } : results[existingIndex];
  const next = { ...base, ...patch, updatedAt: new Date().toISOString() };

  if (existingIndex === -1) {
    results.unshift(next);
  } else {
    results[existingIndex] = next;
  }

  saveResults(results);
  renderListing();
}

function chooseTargets(count) {
  return takeWordsFromDeck(count);
}

function showCompetitiveIntro() {
  const locked = todayLock();
  if (locked) {
    showLockedCompetitive(locked);
    return;
  }
  const progress = loadCompetitiveProgress();
  if (progress) {
    restoreCompetitiveProgress(progress);
    return;
  }

  gameType = "competitive";
  competitiveIntro = true;
  mode = 1;
  competitiveLevelIndex = 0;
  competitiveStarted = 0;
  competitiveCompleted = 0;
  score = 0;
  competitiveRunActive = false;
  lastLevelAward = null;
  bonusFlashRows = new Set();
  targets = [];
  solvedAt = [];
  guesses = [];
  current = "";
  done = true;
  keyStates = new Map();

  document.body.dataset.gameType = gameType;
  document.body.dataset.competitiveLocked = "false";
  document.body.dataset.competitiveIntro = "true";
  document.body.dataset.challengePlaying = "false";
  boardsEl.innerHTML = "";
  boardsEl.classList.remove("multi", "mega", "level-1", "level-2", "level-4", "level-8");
  renderSolutionsPanel(false);
  hideWordReveal();
  keyboardEl.innerHTML = "";
  typeButtons.forEach((button) => button.classList.toggle("active", button.dataset.type === gameType));
  updateModeButtons();
  modeLabelEl.textContent = "Такмичарски";
  messageEl.textContent = "Притисни старт да започнеш игру.";
  tryCountEl.textContent = "0";
  tryButton.textContent = "0/6";
  updateScoreDisplay();
  if (awardPopEl) awardPopEl.hidden = true;
  nextLevelButton.textContent = "Старт";
  nextLevelButton.hidden = false;
  renderListing();
  updateCompetitiveCountdown();
}

function startGame(nextType = gameType, requestedMode, options = {}) {
  updateFridayTheme();
  if (nextType === "hall") {
    showHallOfFame();
    return;
  }
  if (!hasRegisteredPlayerProfile()) {
    openProfileModal();
    setProfileEditMode(true);
    setProfileMessage("За почетак игре изабери надимак и аватар.");
    return;
  }
  if (nextType === "challenge") {
    showChallengeIntro();
    return;
  }
  gameType = nextType;
  competitiveIntro = false;
  document.body.dataset.competitiveLocked = "false";
  document.body.dataset.competitiveIntro = "false";
  document.body.dataset.challengePlaying = "false";
  document.body.dataset.challengeFinished = "false";
  if (gameType === "competitive") {
    if (options.resetLadder) {
      const locked = todayLock();
      if (locked) {
        showLockedCompetitive(locked);
        return;
      }
      clearCompetitiveProgress();
      competitiveLevelIndex = 0;
      competitiveStarted = 0;
      competitiveCompleted = 0;
      score = 0;
      competitiveRunActive = true;
      competitiveWordsPlayed = [];
      lastLevelAward = null;
      bonusFlashRows = new Set();
    }

    if (typeof requestedMode === "number") {
      const requestedIndex = COMPETITIVE_LEVELS.indexOf(requestedMode);
      if (requestedIndex !== -1 && requestedIndex <= competitiveCompleted) {
        competitiveLevelIndex = requestedIndex;
      }
    }

    mode = COMPETITIVE_LEVELS[competitiveLevelIndex];
    competitiveStarted += 1;
  } else {
    if (!options.nextNormal) {
      const normalProgress = loadNormalProgress();
      if (normalProgress) {
        restoreNormalProgress(normalProgress);
        return;
      }
    } else {
      clearNormalProgress();
    }
    mode = 1;
    score = 0;
    competitiveRunActive = false;
    normalStartedCounted = false;
    lastLevelAward = null;
    bonusFlashRows = new Set();
    if (options.nextNormal) {
      normalGameSeed += 1;
    }
  }

  targets = chooseTargets(mode);
  if (gameType === "competitive") {
    competitiveWordsPlayed[competitiveLevelIndex] = [...targets];
  }
  solvedAt = Array(targets.length).fill(null);
  guesses = [];
  current = "";
  done = false;
  keyStates = new Map();
  bonusFlashRows = new Set();
  renderSolutionsPanel(false);

  document.body.dataset.gameType = gameType;
  boardsEl.classList.remove("multi", "mega", "level-1", "level-2", "level-4", "level-8");
  boardsEl.classList.toggle("multi", mode > 1);
  boardsEl.classList.toggle("mega", mode === 8);
  boardsEl.classList.toggle("level-1", mode === 1);
  boardsEl.classList.toggle("level-2", gameType === "competitive" && mode === 2);
  boardsEl.classList.toggle("level-4", gameType === "competitive" && mode === 4);
  boardsEl.classList.toggle("level-8", gameType === "competitive" && mode === 8);
  typeButtons.forEach((button) => button.classList.toggle("active", button.dataset.type === gameType));
  modeButtons.forEach((button) => {
    const buttonMode = Number(button.dataset.mode);
    const levelIndex = COMPETITIVE_LEVELS.indexOf(buttonMode);
    button.classList.toggle("active", buttonMode === mode);
    const isLocked = gameType === "normal" ? buttonMode !== 1 : levelIndex > competitiveCompleted;
    button.classList.toggle("locked", isLocked);
    button.disabled = gameType === "competitive" || isLocked;
  });
  nextLevelButton.hidden = true;
  nextLevelButton.textContent = "Даље";
  if (awardPopEl) awardPopEl.hidden = true;

  modeLabelEl.textContent = gameType === "competitive"
    ? ""
    : isPetkoFriday()
      ? "Петак за Петка"
      : "Обичан";
  messageEl.textContent = gameType === "competitive"
    ? `${fridayLabel()}Ниво ${competitiveLevelIndex + 1}: ${mode} ${mode === 1 ? "реч" : "речи"}, све решено носи ${levelPoints()} поена. Бонус +${UNUSED_ATTEMPT_BONUS} ако остане покушаја. Неуспех носи ${COMPETITIVE_FAIL_PENALTY}.`
    : isPetkoFriday()
      ? "Петак за Петка: реши 5 обичних заредом за +5 на главни скор."
      : "";
  render();
  saveCompetitiveProgress();
  saveNormalProgress();
  renderListing();
  updateCompetitiveCountdown();
}

function render() {
  renderBoards();
  renderWordReveal();
  renderKeyboard();
  tryCountEl.textContent = String(guesses.length);
  tryButton.textContent = gameType === "competitive"
    ? `${guesses.length}/${maxAttempts()}`
    : `${guesses.length}/${maxAttempts()}`;
  updateScoreDisplay();
  renderNormalStats();
  updateCompetitiveCountdown();
  requestAnimationFrame(positionKeyboard);
}

function renderBoards() {
  boardsEl.innerHTML = "";
  const collapsibleGame = gameType === "competitive" || gameType === "challenge";
  const boardIndexes = targets
    .map((_, index) => index)
    .sort((a, b) => {
      const aSolved = collapsibleGame && solvedAt[a];
      const bSolved = collapsibleGame && solvedAt[b];
      return Number(Boolean(aSolved)) - Number(Boolean(bSolved)) || a - b;
    });
  const collapsedCount = boardIndexes.filter((index) =>
    collapsibleGame && solvedAt[index]
  ).length;
  const activeCount = targets.length - collapsedCount;
  const collapsedSide = !done && activeCount > 0 && activeCount % 2 === 1 && collapsedCount > 0;
  const collapsedStack = collapsedSide ? document.createElement("div") : null;
  boardsEl.classList.toggle("has-collapsed", collapsedCount > 0);
  boardsEl.classList.toggle("collapsed-odd", collapsedCount % 2 === 1);
  boardsEl.classList.toggle("collapsed-side", collapsedSide);
  boardsEl.classList.toggle("challenge-finished", gameType === "challenge" && done);
  boardsEl.classList.toggle("final-hidden", done && (gameType === "competitive" || gameType === "challenge"));
  if (collapsedStack) collapsedStack.className = "collapsed-stack";

  boardIndexes.forEach((boardIndex) => {
    const target = targets[boardIndex];
    const fragment = template.content.cloneNode(true);
    const card = fragment.querySelector(".board-card");
    const title = fragment.querySelector(".board-title");
    const grid = fragment.querySelector(".grid");
    const solvedTry = solvedAt[boardIndex];
    const collapseSolved = collapsibleGame && solvedTry;

    title.textContent = collapseSolved
      ? displayWord(target)
      : mode === 1
      ? ""
      : solvedTry
        ? `Реч ${boardIndex + 1} ОК`
        : `Реч ${boardIndex + 1}`;

    if (collapseSolved) {
      card.classList.add("solved", "collapsed");
      title.innerHTML = "";
      const word = document.createElement("div");
      word.className = "mini-word";
      [...displayWord(target)].forEach((letter) => {
        const tile = document.createElement("span");
        tile.className = "mini-word-tile";
        tile.textContent = letter;
        word.append(tile);
      });
      const info = document.createElement("button");
      info.className = "mini-word-info";
      info.type = "button";
      info.textContent = "?";
      info.setAttribute("aria-label", `Објашњење речи ${displayWord(target)}`);
      info.addEventListener("click", () => showExistingWordReview(target));
      title.append(word, info);
      (collapsedStack || boardsEl).append(fragment);
      return;
    }

    for (let rowIndex = 0; rowIndex < visibleRows(); rowIndex += 1) {
      const row = document.createElement("div");
      row.className = "row";
      if (bonusFlashRows.has(rowIndex)) row.classList.add("bonus-flash");
      const boardClosed = solvedTry && rowIndex >= solvedTry;
      const word = boardClosed ? "" : guesses[rowIndex] || (rowIndex === guesses.length && !done ? current : "");
      const states = boardClosed ? [] : guesses[rowIndex] ? scoreGuess(guesses[rowIndex], target) : [];

      for (let tileIndex = 0; tileIndex < WORD_LENGTH; tileIndex += 1) {
        const tile = document.createElement("div");
        tile.className = "tile";
        tile.textContent = word[tileIndex] ? word[tileIndex].toUpperCase() : "";
        if (word[tileIndex]) tile.classList.add("filled");
        if (states[tileIndex]) tile.classList.add(states[tileIndex]);
        row.append(tile);
      }
      grid.append(row);
    }

    if (solvedTry) card.classList.add("solved");
    boardsEl.append(fragment);
  });

  if (collapsedStack && collapsedStack.childElementCount) {
    boardsEl.append(collapsedStack);
  }
}

function renderSolutionsPanel(show) {
  if (!solutionsPanelEl) return;
  solutionsPanelEl.innerHTML = "";
  solutionsPanelEl.hidden = !show || !targets.length;
  if (solutionsPanelEl.hidden) return;

  targets.forEach((target, index) => {
    const chip = document.createElement("div");
    chip.className = `solution-chip ${solvedAt[index] ? "solved" : "unsolved"}`;
    const word = document.createElement("div");
    word.className = "mini-word";
    [...displayWord(target)].forEach((letter) => {
      const tile = document.createElement("span");
      tile.className = "mini-word-tile";
      tile.textContent = letter;
      word.append(tile);
    });
    const info = document.createElement("button");
    info.className = "mini-word-info";
    info.type = "button";
    info.textContent = "?";
    info.setAttribute("aria-label", `Објашњење речи ${displayWord(target)}`);
    info.addEventListener("click", () => showExistingWordReview(target));
    chip.append(word, info);
    solutionsPanelEl.append(chip);
  });
}

function closeWordModal() {
  exitWordModalEditMode();
  wordModalMeaningEditable = false;
  wordModalCurrentWord = "";
  setWordModalEditLink(false, false);
  if (wordModal) wordModal.hidden = true;
  if (wordModal) delete wordModal.dataset.variant;
  document.body.dataset.wordModalOpen = "false";
}

function setWordModalEditLink(visible, allowed) {
  if (!wordModalEditLink) return;
  wordModalEditLink.hidden = !visible;
  wordModalEditLink.classList.toggle("is-disabled", !allowed);
  wordModalEditLink.setAttribute("aria-disabled", allowed ? "false" : "true");
  wordModalEditLink.tabIndex = visible && allowed ? 0 : -1;
}

async function refreshWordEditorPermission() {
  wordEditorAllowed = false;
  if (!supabaseConfigured()) return false;
  const params = new URLSearchParams({
    p_nickname: normalizePlayerName(loadPlayerName() || ""),
    p_device_id: deviceId()
  });
  const response = await fetch(supabaseUrl(`rpc/player_can_edit_words?${params}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) {
    console.warn("Petko: word editor permission check failed.", response.status);
    return false;
  }
  const allowed = await response.json();
  wordEditorAllowed = Boolean(allowed);
  return wordEditorAllowed;
}

function wordModalCardEl() {
  return wordModal?.querySelector(".word-card") || null;
}

function enterWordModalEditMode(text = "") {
  const card = wordModalCardEl();
  if (!wordModalEdit || !wordModalEditMeaning || !wordModalEditGrammar || !card) return;
  const { meaning, grammar } = parseWordCardText(text);
  wordModalEditMeaning.value = meaning;
  wordModalEditGrammar.value = grammar;
  wordModalEdit.hidden = false;
  card.dataset.editMode = "true";
  window.setTimeout(() => wordModalEditMeaning.focus(), 0);
}

function exitWordModalEditMode() {
  const card = wordModalCardEl();
  if (wordModalEdit) wordModalEdit.hidden = true;
  if (wordModalEditMeaning) wordModalEditMeaning.value = "";
  if (wordModalEditGrammar) wordModalEditGrammar.value = "";
  if (card) delete card.dataset.editMode;
}

async function saveWordMeaningEdit(word, meaning, grammar) {
  const formatted = formatWordCardText(meaning, grammar);
  if (!formatted) return { ok: false, error: "missing_fields" };
  if (!supabaseConfigured() || !wordEditorAllowed) return { ok: false, error: "forbidden" };

  // RLS na words dozvoljava samo SELECT za anon — pravi put je RPC.
  const response = await fetch(supabaseUrl("rpc/update_word_meaning"), {
    method: "POST",
    headers: supabaseJsonHeaders(),
    body: JSON.stringify({
      p_word: word,
      p_meaning: formatted,
      p_nickname: normalizePlayerName(loadPlayerName() || ""),
      p_device_id: deviceId()
    })
  });
  if (!response.ok) return { ok: false, error: "request_failed" };
  const payload = await response.json().catch(() => ({}));
  if (!payload?.ok) return payload || { ok: false, error: "forbidden" };
  WORD_INFO[word] = formatted;
  BOOTSTRAP_WORD_INFO[word] = formatted;
  markWordVerified(word, true);
  return { ok: true, meaning: formatted };
}

async function handleWordModalEditSave() {
  const word = wordModalCurrentWord;
  if (!word || !wordEditorAllowed) return;
  const meaning = String(wordModalEditMeaning?.value || "").trim();
  const grammar = String(wordModalEditGrammar?.value || "").trim();
  if (!meaning) {
    messageEl.textContent = "Унеси значење пре чувања.";
    return;
  }
  if (wordModalEditSave) wordModalEditSave.textContent = "Чувам...";
  const result = await saveWordMeaningEdit(word, meaning, grammar);
  if (wordModalEditSave) wordModalEditSave.textContent = "Сачувај";
  if (!result.ok) {
    messageEl.textContent = result.error === "forbidden"
      ? "Немаш дозволу за уређивање значења."
      : "Чување није успело.";
    return;
  }
  exitWordModalEditMode();
  setWordModalBody(result.meaning || formatWordCardText(meaning, grammar));
  applyVerifiedWordReviewChrome(word);
  messageEl.textContent = "Значење је сачувано.";
}

function setWordModalButtons(buttons) {
  if (!wordModalActions) return;
  wordModalActions.innerHTML = "";
  buttons.forEach((item) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = item.tone;
    button.textContent = item.label;
    button.addEventListener("click", item.onClick);
    wordModalActions.append(button);
  });
}

function escapeWordCardHtml(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function parseWordCardText(text) {
  const raw = String(text || "").trim();
  if (!raw) return { meaning: "", grammar: "" };
  const labeled = raw.match(/^Значење:\s*([\s\S]*?)(?:\n\nГраматика:\s*([\s\S]*))?$/u);
  if (labeled) {
    return {
      meaning: labeled[1].trim(),
      grammar: String(labeled[2] || "").trim()
    };
  }
  return { meaning: raw, grammar: "" };
}

function formatWordCardText(meaning, grammar = "") {
  const cleanMeaning = String(meaning || "").trim();
  const cleanGrammar = String(grammar || "").trim();
  if (!cleanMeaning) return "";
  if (!cleanGrammar) return cleanMeaning;
  return `Значење: ${cleanMeaning}\n\nГраматика: ${cleanGrammar}`;
}

function renderWordCardHtml(text) {
  const { meaning, grammar } = parseWordCardText(text);
  const parts = [];
  if (meaning) {
    parts.push(
      `<p class="word-card-section"><span class="word-card-label">Значење:</span> ${escapeWordCardHtml(meaning)}</p>`
    );
  }
  if (grammar) {
    parts.push(
      `<p class="word-card-section"><span class="word-card-label">Граматика:</span> ${escapeWordCardHtml(grammar)}</p>`
    );
  }
  if (parts.length) return parts.join("");
  return `<p class="word-card-section">${escapeWordCardHtml(text)}</p>`;
}

function setWordModalBody(text) {
  if (!wordModalText) return;
  wordModalText.innerHTML = renderWordCardHtml(text);
}

function showWordModal({ title, word, text, reviewText = "", buttons, modalVariant = "", meaningEditable = false }) {
  if (!wordModal || !wordModalTitle || !wordModalWord || !wordModalText) return;
  exitWordModalEditMode();
  wordModalMeaningEditable = meaningEditable;
  wordModalCurrentWord = meaningEditable ? String(word || "") : "";
  if (modalVariant) wordModal.dataset.variant = modalVariant;
  else delete wordModal.dataset.variant;
  wordModalTitle.textContent = title;
  wordModalWord.textContent = displayWord(word);
  setWordModalVerifiedMark(meaningEditable ? word : "", { editable: meaningEditable });
  setWordModalBody(text);
  if (wordReviewText) {
    wordReviewText.textContent = reviewText;
    wordReviewText.hidden = !reviewText;
  }
  setWordModalButtons(buttons);
  setWordModalEditLink(meaningEditable && wordEditorAllowed, meaningEditable && wordEditorAllowed);
  wordModal.hidden = false;
  document.body.dataset.wordModalOpen = "true";
}

function wordMeaningText(word) {
  const meaning = embeddedWordMeaning(word);
  if (meaning) {
    WORD_INFO[word] = meaning;
    return meaning;
  }
  return "Значење ове речи још није уписано. Овде ће стајати кратко објашњење када га додамо у базу.";
}

function wordReviewCloseButtons() {
  return [
    {
      label: "У реду",
      tone: "success",
      onClick: () => closeWordModal()
    }
  ];
}

function wordReviewRemoveButtons(word) {
  return [
    {
      label: "Да",
      tone: "danger",
      onClick: () => {
        submitWordReport(word, "remove", "normal_answer").catch(() => {});
        closeWordModal();
        messageEl.textContent = "Пријава је послата.";
      }
    },
    {
      label: "Не",
      tone: "success",
      onClick: () => closeWordModal()
    }
  ];
}

function applyVerifiedWordReviewChrome(word) {
  if (wordReviewText) {
    wordReviewText.textContent = "";
    wordReviewText.hidden = true;
  }
  setWordModalButtons(wordReviewCloseButtons());
  setWordModalVerifiedMark(word, { editable: true });
  setWordModalEditLink(wordEditorAllowed, wordEditorAllowed);
}

function showExistingWordReview(word) {
  const fallbackText = wordMeaningText(word);
  const verified = isWordVerified(word);
  showWordModal({
    title: "Објашњење речи",
    word,
    text: fallbackText,
    meaningEditable: true,
    reviewText: verified
      ? ""
      : "Да ли је ова реч сувишна, непримерена или неисправна и треба да се уклони?",
    buttons: verified ? wordReviewCloseButtons() : wordReviewRemoveButtons(word)
  });
  refreshWordEditorPermission()
    .catch(() => false)
    .finally(() => {
      if (!wordModal || wordModal.hidden || wordModalCurrentWord !== word) return;
      setWordModalEditLink(wordEditorAllowed, wordEditorAllowed);
      setWordModalVerifiedMark(word, { editable: true });
    });

  fetchWordMeaning(word)
    .then((meaning) => {
      if (!wordModal || wordModal.hidden || wordModalWord.textContent !== displayWord(word)) return;
      if (meaning) setWordModalBody(meaning);
      if (isWordVerified(word)) applyVerifiedWordReviewChrome(word);
      else setWordModalVerifiedMark(word, { editable: true });
    })
    .catch(() => {});
}

function showMissingWordReview(word) {
  showWordModal({
    title: "Реч није у бази",
    word,
    text: "Ова реч не постоји у бази. Да ли мислите да треба да се нађе у бази речи?",
    buttons: [
      {
        label: "Да",
        tone: "success",
        onClick: () => {
          submitWordReport(word, "add", "missing_guess").catch(() => {});
          closeWordModal();
          messageEl.textContent = "Предлог је послат.";
        }
      },
      {
        label: "Не",
        tone: "danger",
        onClick: () => {
          closeWordModal();
          messageEl.textContent = "Настави.";
        }
      }
    ]
  });
}

function renderWordReveal() {
  if (!wordRevealEl || !wordRevealTextEl) return;
  const show = gameType === "normal" && done && targets.length === 1;
  wordRevealEl.hidden = !show;
  if (!show) {
    wordRevealTextEl.innerHTML = "";
    wordRevealEl.classList.remove("solved", "failed");
    return;
  }
  wordRevealEl.classList.toggle("solved", Boolean(solvedAt[0]));
  wordRevealEl.classList.toggle("failed", !solvedAt[0]);
  wordRevealTextEl.innerHTML = "";
  [...displayWord(targets[0])].forEach((letter) => {
    const tile = document.createElement("span");
    tile.className = "word-reveal-tile";
    tile.textContent = letter;
    wordRevealTextEl.append(tile);
  });
}

function hideWordReveal() {
  if (wordRevealEl) wordRevealEl.hidden = true;
  if (wordRevealTextEl) wordRevealTextEl.innerHTML = "";
}

function renderKeyboard() {
  keyboardEl.innerHTML = "";
  KEY_ROWS.forEach((letters) => {
    const row = document.createElement("div");
    row.className = "key-row";
    letters.forEach(([letter, label]) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "key";
      button.dataset.key = letter;
      button.textContent = label;
      if (letter === "enter" || letter === "back") button.classList.add("wide");
      if (keyStates.has(letter)) button.classList.add(keyStates.get(letter));
      button.addEventListener("click", () => pressKey(letter));
      row.append(button);
    });
    keyboardEl.append(row);
  });
}

function positionKeyboard() {
  keyboardEl.style.top = "";
  keyboardEl.style.bottom = "";
}

function pressKey(key) {
  if (done) return;
  if (key === "back") {
    current = current.slice(0, -1);
  } else if (key === "enter") {
    submitGuess();
  } else if (/^[абвгдђежзијклљмнњопрстћуфхцчџш]$/.test(key) && current.length < WORD_LENGTH) {
    current += key;
    markNormalStarted();
  }
  render();
  saveCompetitiveProgress();
  saveNormalProgress();
  saveChallengeProgress();
}

function submitGuess() {
  if (current.length !== WORD_LENGTH) {
    messageEl.textContent = "Треба тачно 5 слова.";
    playPetkoMoment("short", { force: true });
    return;
  }

  if (!isKnownWord(current)) {
    const missingWord = current;
    current = "";
    messageEl.textContent = "Нема те речи.";
    playPetkoMoment("unknown", { force: true });
    showMissingWordReview(missingWord);
    render();
    saveNormalProgress();
    return;
  }

  guesses.push(current);
  updateSolvedAndScore(current, guesses.length);
  updateKeyStates(current);
  current = "";
  saveCompetitiveProgress();
  saveNormalProgress();
  saveChallengeProgress();

  const solvedCount = solvedAt.filter(Boolean).length;
  const allSolved = solvedCount === targets.length;
  markQuietGuessForPetko();

  if (allSolved) {
    done = true;
    petkoMoodQuietGuesses = 0;
    if (gameType === "competitive") {
      competitiveCompleted = Math.max(competitiveCompleted, competitiveLevelIndex + 1);
      updateChallengeQuota();
      applyLevelAward();
      renderSolutionsPanel(true);
      const isFinalLevel = competitiveLevelIndex === COMPETITIVE_LEVELS.length - 1;
      updateCompetitiveNextButton();
      messageEl.textContent = isFinalLevel
        ? finalMessage("finished")
        : levelAwardMessage();
      saveCompetitiveProgress();
      if (isFinalLevel) {
        finishCompetitive("finished");
      }
      playPetkoMoment(isFinalLevel ? "tournamentWin" : "levelWin", { force: true });
      updateModeButtons();
    } else if (gameType === "challenge") {
      playPetkoMoment("challengeWin", { force: true });
      finishChallenge("finished");
    } else {
      bumpNormalFinished();
      const challengeText = recordNormalChallengeWin();
      const fridayText = recordFridayNormalWin();
      const normalWinText = [fridayText, challengeText].filter(Boolean).join(" ");
      messageEl.textContent = normalWinText || "Погођено!";
      playPetkoMoment(fridayText ? "fridayWin" : "normalWin", { text: normalWinText || "", force: true });
      clearNormalProgress();
      nextLevelButton.textContent = "Следећа";
      nextLevelButton.hidden = false;
      renderWordReveal();
    }
  } else if (guesses.length >= maxAttempts()) {
    done = true;
    petkoMoodQuietGuesses = 0;
    if (gameType === "competitive") {
      applyFailurePenalty();
      renderSolutionsPanel(true);
      messageEl.textContent = finalMessage("failed");
      playPetkoMoment("tournamentFail", { force: true });
      finishCompetitive("failed");
    } else if (gameType === "challenge") {
      playPetkoMoment("challengeFail", { force: true });
      finishChallenge("failed");
    } else {
      messageEl.textContent = `Реч је била: ${displayWords(targets)}`;
      playPetkoMoment("normalMiss", { force: true });
      resetFridayNormalStreak();
      resetNormalChallengeStreak();
      clearNormalProgress();
      nextLevelButton.textContent = "Следећа";
      nextLevelButton.hidden = false;
      renderWordReveal();
    }
  } else {
    messageEl.textContent = gameType === "competitive"
      ? `${solvedCount}/${mode} решено. Скор важи само за такмичарски.`
      : "Настави.";
    saveCompetitiveProgress();
    saveNormalProgress();
  }
}

function showLockedCompetitive(result) {
  clearCompetitiveProgress();
  gameType = "competitive";
  document.body.dataset.competitiveLocked = "true";
  competitiveCompleted = result.completed || 0;
  competitiveLevelIndex = Math.min(competitiveCompleted, COMPETITIVE_LEVELS.length - 1);
  mode = COMPETITIVE_LEVELS[competitiveLevelIndex];
  targets = [];
  solvedAt = [];
  guesses = [];
  current = "";
  done = true;
  score = result.score;
  competitiveStarted = result.started || 0;
  competitiveRunActive = false;
  keyStates = new Map();
  lastLevelAward = null;
  bonusFlashRows = new Set();

  document.body.dataset.gameType = gameType;
  document.body.dataset.competitiveIntro = "false";
  boardsEl.innerHTML = "";
  boardsEl.classList.remove("multi", "mega", "level-1", "level-2", "level-4", "level-8");
  keyboardEl.innerHTML = "";
  nextLevelButton.hidden = true;
  typeButtons.forEach((button) => button.classList.toggle("active", button.dataset.type === gameType));
  updateModeButtons();
  modeLabelEl.textContent = "Такмичарски закључан";
  messageEl.textContent = lockedMessage(result);
  tryCountEl.textContent = "0";
  tryButton.textContent = `0/${maxAttempts()}`;
  updateScoreDisplay(result);
  renderListing();
  updateCompetitiveCountdown();
}

function updateModeButtons() {
  modeButtons.forEach((button) => {
    const buttonMode = Number(button.dataset.mode);
    const levelIndex = COMPETITIVE_LEVELS.indexOf(buttonMode);
    const isLocked = gameType === "normal" ? buttonMode !== 1 : levelIndex > competitiveCompleted;
    button.classList.toggle("active", buttonMode === mode);
    button.classList.toggle("locked", isLocked);
    button.disabled = gameType === "competitive" || isLocked;
  });
}

function updateSolvedAndScore(guess, attempt) {
  targets.forEach((target, index) => {
    if (solvedAt[index] || guess !== target) return;
    solvedAt[index] = attempt;
  });
}

function unusedBonus() {
  return unusedAttempts() * UNUSED_ATTEMPT_BONUS;
}

function unusedAttempts() {
  return Math.max(0, maxAttempts() - guesses.length);
}

function applyLevelAward() {
  const base = levelPoints();
  const attemptsLeft = unusedAttempts();
  const bonus = unusedBonus();
  const total = base + bonus;
  const before = score;
  score += total;
  lastLevelAward = { base, bonus, attemptsLeft, total, before, after: score };
  bonusFlashRows = new Set();
  animateScoreAward(lastLevelAward);
}

function applyFailurePenalty() {
  score += COMPETITIVE_FAIL_PENALTY;
  updateScoreDisplay();
  showScoreBurst(String(COMPETITIVE_FAIL_PENALTY), "red");
}

function levelPoints() {
  return COMPETITIVE_LEVEL_POINTS[competitiveLevelIndex];
}

function maxAttempts() {
  if (gameType === "challenge") return CHALLENGE_ATTEMPTS;
  if (gameType !== "competitive") return MAX_ROWS;
  return COMPETITIVE_LEVEL_ATTEMPTS[competitiveLevelIndex] || MAX_ROWS;
}

function visibleRows() {
  if (gameType === "challenge") return CHALLENGE_ATTEMPTS;
  if (gameType === "competitive") return maxAttempts();
  return Math.max(MAX_ROWS, guesses.length + (done ? 0 : 1));
}

function currentFinalScore() {
  if (gameType !== "competitive") return score;
  return score / Math.max(1, competitiveStarted);
}

function scoreDifferenceValue(total = score, started = competitiveStarted) {
  return total - started;
}

function annualScoreSummary(currentPatch = null) {
  const year = currentYearId();
  const byDate = new Map();
  loadResults()
    .filter((result) => String(result.date || "").startsWith(year) && isFinalResult(result))
    .forEach((result) => byDate.set(result.date, result));

  if (currentPatch) {
    byDate.set(todayId(), { date: todayId(), ...currentPatch });
  } else if (gameType === "competitive" && competitiveRunActive) {
    byDate.set(todayId(), {
      score,
      started: competitiveStarted
    });
  }

  const rows = [...byDate.values()];
  const summary = rows.reduce(
    (summary, result) => {
      const total = Number(result.score) || 0;
      const started = Number(result.started) || 0;
      const daily = scoreDifferenceValue(total, started);
      summary.total += total;
      summary.started += started;
      summary.bestDaily = Math.max(summary.bestDaily, daily);
      return summary;
    },
    { total: 0, started: 0, bestDaily: 0 }
  );
  const friday = loadFridayBonus();
  let fridayBonus = fridayBonusTotal(friday);
  const todayBonusStored = Boolean(friday.competitive?.[todayId()]);
  if (isPetkoFriday() && !todayBonusStored) {
    if (currentPatch) {
      fridayBonus += Math.max(0, Number(currentPatch.score) || 0);
    } else if (gameType === "competitive" && competitiveRunActive) {
      fridayBonus += Math.max(0, score);
    }
  }
  summary.total += fridayBonus;
  return summary;
}

function updateScoreDisplay(result) {
  const summary = annualScoreSummary(result);
  updateTopScoreProfile(summary.total);
  if (scoreTotalLineEl && scoreDifferenceLineEl) {
    scoreTotalLineEl.textContent = `${formatScore(summary.started)}/${formatScore(summary.total)}`;
    scoreDifferenceLineEl.textContent = formatScore(summary.bestDaily);
    return;
  }
  if (scoreCountEl) scoreCountEl.textContent = formatScore(summary.bestDaily);
}

function formatScore(value) {
  if (!Number.isFinite(value)) return "0";
  return Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, "").replace(/\.$/, "");
}

function levelLabel(index) {
  return `${COMPETITIVE_LEVELS[index]}=${COMPETITIVE_LEVEL_POINTS[index]}`;
}

function levelAwardMessage() {
  if (!lastLevelAward) return `Ниво завршен. Скор ${formatScore(currentFinalScore())}. Можеш даље.`;
  const bonus = lastLevelAward.bonus ? ` + бонус ${lastLevelAward.bonus}` : "";
  return `Освојено ${lastLevelAward.base}${bonus} = +${lastLevelAward.total}. Збир ${formatScore(lastLevelAward.before)} → ${formatScore(lastLevelAward.after)}. Коначни скор ${formatScore(currentFinalScore())}.`;
}

function resultWords() {
  const words = competitiveWordsPlayed.flat();
  return words.length ? displayWords(words) : displayWords(targets);
}

function resultPayload(status) {
  const finalScore = currentFinalScore();
  const streak = currentStreakFor(status);
  return {
    status,
    date: todayId(),
    score,
    finalScore,
    started: competitiveStarted,
    completed: competitiveCompleted,
    level: competitiveLevelIndex + 1,
    words: resultWords(),
    points: `неуспех ${COMPETITIVE_FAIL_PENALTY}, ${COMPETITIVE_LEVELS.map((_, index) => levelLabel(index)).join(", ")}, бонус +${UNUSED_ATTEMPT_BONUS} за сваки неискоришћен покушај`,
    attempts: COMPETITIVE_LEVEL_ATTEMPTS[competitiveLevelIndex],
    wins: status === "finished" ? 1 : 0,
    streak
  };
}

function onlineScorePayload(result) {
  const total = Number(result.score) || 0;
  const started = Number(result.started) || 0;
  return {
    nickname: loadPlayerName() || "Играч",
    score: scoreDifferenceValue(total, started),
    attempts: started,
    wins: Number(result.wins) || 0,
    streak: Number(result.streak) || 0
  };
}

async function submitOnlineResult(result) {
  if (!supabaseConfigured() || !isFinalResult(result)) return false;
  const response = await fetch(supabaseUrl(SUPABASE_CONFIG.table), {
    method: "POST",
    headers: supabaseJsonHeaders({ Prefer: "return=minimal" }),
    body: JSON.stringify(onlineScorePayload(result))
  });
  if (!response.ok) throw new Error("Supabase submit failed");
  return true;
}

async function fetchOnlineLeaderboard() {
  if (!supabaseConfigured()) return null;
  const query = [
    `select=nickname,score,attempts,wins,streak,created_at`,
    `order=created_at.desc`,
    `limit=1000`
  ].join("&");
  const response = await fetch(supabaseUrl(`${SUPABASE_CONFIG.table}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) throw new Error("Supabase leaderboard failed");
  return response.json();
}

async function fetchNormalStatsRows() {
  if (!supabaseConfigured()) return [];
  const query = [
    "select=nickname,started,finished,updated_at",
    "order=updated_at.desc",
    "limit=1000"
  ].join("&");
  const response = await fetch(supabaseUrl(`${normalStatsTable()}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) return [];
  const rows = await response.json();
  return Array.isArray(rows) ? rows : [];
}

async function fetchOnlinePlayerStats(nickname) {
  if (!supabaseConfigured() || !nickname) return null;
  const query = [
    `select=nickname,score,attempts,wins,streak,created_at`,
    `nickname=eq.${encodeURIComponent(nickname)}`,
    `order=created_at.desc`,
    `limit=1000`
  ].join("&");
  const response = await fetch(supabaseUrl(`${SUPABASE_CONFIG.table}?${query}`), {
    headers: supabaseHeaders()
  });
  if (!response.ok) throw new Error("Supabase stats failed");
  return response.json();
}

function scoreDate(row) {
  return String(row.created_at || "").slice(0, 10) || todayId();
}

function formatHallDate(value) {
  const raw = String(value || "").slice(0, 10);
  if (!raw) return "датум није уписан";
  const [year, month, day] = raw.split("-");
  if (!year || !month || !day) return raw;
  return `${day}.${month}.${year}.`;
}

function aggregatePlayerRows(rows) {
  const days = new Map();
  rows.forEach((row) => {
    const date = scoreDate(row);
    const scoreValue = Number(row.score) || 0;
    const old = days.get(date);
    if (!old || scoreValue > old.score) {
      days.set(date, {
        date,
        createdAt: row.created_at || date,
        score: scoreValue,
        attempts: Number(row.attempts) || 0,
        wins: Number(row.wins) || 0,
        streak: Number(row.streak) || 0
      });
    }
  });

  const dayRows = [...days.values()];
  const playedDays = dayRows.length;
  const totalScore = dayRows.reduce((sum, row) => sum + row.score, 0);
  const average = playedDays ? totalScore / playedDays : 0;
  const activityBonus = Math.min(playedDays, 20) * 0.5;
  const streak = Math.max(0, ...dayRows.map((row) => row.streak || 0));
  const streakBonus = Math.min(streak, 10);
  const finalScore = average + activityBonus + streakBonus;
  const bestDay = dayRows.reduce((best, row) => (!best || row.score > best.score ? row : best), null);
  const lastDay = dayRows.reduce((last, row) => (!last || row.date > last.date ? row : last), null);
  const wonGames = dayRows.reduce((sum, row) => sum + row.wins, 0);

  return {
    attempts: playedDays,
    attemptsAt: lastDay?.createdAt || "",
    best: playedDays ? Math.max(...dayRows.map((row) => row.score)) : 0,
    bestAt: bestDay?.createdAt || "",
    finalScore,
    finalScoreAt: lastDay?.createdAt || "",
    playedDays,
    playedDaysAt: lastDay?.createdAt || "",
    streak,
    streakAt: lastDay?.createdAt || "",
    totalScore,
    wins: wonGames,
    winsAt: lastDay?.createdAt || ""
  };
}

function normalSuccessRows(rows) {
  const byName = new Map();
  rows.forEach((row) => {
    const nickname = (row.nickname || "Играч").trim() || "Играч";
    const key = nickname.toLocaleLowerCase("sr");
    const started = Number(row.started) || 0;
    const finished = Number(row.finished) || 0;
    const updatedAt = row.updated_at || "";
    const current = byName.get(key) || {
      nickname,
      started: 0,
      finished: 0,
      successRate: 0,
      successRateAt: ""
    };
    current.started += started;
    current.finished += finished;
    if (!current.successRateAt || updatedAt > current.successRateAt) {
      current.nickname = nickname;
      current.successRateAt = updatedAt;
    }
    byName.set(key, current);
  });

  return [...byName.values()]
    .map((row) => ({
      ...row,
      successRate: row.started ? (row.finished / row.started) * 100 : 0
    }))
    .filter((row) => row.started >= 10);
}

function aggregateLeaderboard(rows) {
  const byName = new Map();
  rows.forEach((row) => {
    const nickname = (row.nickname || "Играч").trim() || "Играч";
    if (!byName.has(nickname)) byName.set(nickname, []);
    byName.get(nickname).push(row);
  });

  return [...byName.entries()]
    .map(([nickname, playerRows]) => ({ nickname, ...aggregatePlayerRows(playerRows) }))
    .sort((a, b) =>
      b.finalScore - a.finalScore ||
      b.best - a.best ||
      b.playedDays - a.playedDays ||
      a.nickname.localeCompare(b.nickname)
    )
    .slice(0, 100);
}

function bestDailyScoreRows(rows) {
  const byName = new Map();
  rows.forEach((row) => {
    const nickname = (row.nickname || "Играч").trim() || "Играч";
    const key = nickname.toLocaleLowerCase("sr");
    const scoreValue = Number(row.score) || 0;
    const createdAt = row.created_at || "";
    const current = byName.get(key);
    if (!current || scoreValue > current.score || (scoreValue === current.score && createdAt > current.created_at)) {
      byName.set(key, {
        nickname,
        score: scoreValue,
        attempts: Number(row.attempts) || 0,
        wins: Number(row.wins) || 0,
        streak: Number(row.streak) || 0,
        created_at: createdAt
      });
    }
  });
  return [...byName.values()];
}

function bestBy(items, valueFn) {
  let best = null;
  let bestValue = -Infinity;
  items.forEach((item) => {
    const value = Number(valueFn(item)) || 0;
    if (value > bestValue) {
      best = item;
      bestValue = value;
    }
  });
  return best && bestValue > 0 ? { item: best, value: bestValue } : null;
}

function challengeResultCountsForMedal(row) {
  const winner = challengeWinner(row);
  if (winner !== "creator" && winner !== "opponent") return null;
  const loser = winner === "creator" ? "opponent" : "creator";
  const loserSolved = Number(row[`${loser}_solved`]) || 0;
  const loserAttempts = Number(row[`${loser}_attempts`]) || 0;
  const loserFinished = loserSolved >= CHALLENGE_WORDS || loserAttempts >= CHALLENGE_ATTEMPTS;
  if (!loserFinished) return null;
  return {
    winnerName: winner === "creator" ? row.creator : row.opponent,
    diff: challengeDifference(row),
    playedAt: row[`${winner}_played_at`] || row.created_at || ""
  };
}

function challengeStrongScoreRows(rows) {
  const byName = new Map();
  rows.filter(playedChallenge).forEach((row) => {
    const result = challengeResultCountsForMedal(row);
    if (!result || !result.diff) return;
    const nickname = (result.winnerName || "Играч").trim() || "Играч";
    const key = nickname.toLocaleLowerCase("sr");
    const current = byName.get(key) || {
      nickname,
      best: 0,
      bestCount: 0,
      bestAt: ""
    };
    if (result.diff > current.best) {
      current.best = result.diff;
      current.bestCount = 1;
      current.bestAt = result.playedAt;
    } else if (result.diff === current.best) {
      current.bestCount += 1;
      if (!current.bestAt || result.playedAt > current.bestAt) current.bestAt = result.playedAt;
    }
    byName.set(key, current);
  });
  return [...byName.values()];
}

function normalizeChallengeScoreStatsRows(rows = []) {
  const byName = new Map();
  rows.forEach((row) => {
    const nickname = (row.nickname || "Играч").trim() || "Играч";
    const key = nickname.toLocaleLowerCase("sr");
    const best = Number(row.best_score) || 0;
    const bestCount = Math.max(1, Number(row.best_score_count) || 1);
    const bestAt = row.last_at || "";
    const current = byName.get(key);
    if (!current) {
      byName.set(key, { nickname, best, bestCount, bestAt });
      return;
    }
    if (best > current.best) {
      current.nickname = nickname;
      current.best = best;
      current.bestCount = bestCount;
      current.bestAt = bestAt;
    } else if (best === current.best) {
      current.bestCount += bestCount;
      if (bestAt && (!current.bestAt || bestAt > current.bestAt)) current.bestAt = bestAt;
      if (nickname.length > current.nickname.length) current.nickname = nickname;
    }
  });
  return [...byName.values()];
}

function normalizeChallengeWinStatsRows(rows = []) {
  const byName = new Map();
  const ensure = (name) => {
    const key = (name || "Играч").trim() || "Играч";
    if (!byName.has(key)) {
      byName.set(key, { nickname: key, wins: 0, winsAt: "", played: 0, best: 0, bestAt: "" });
    }
    return byName.get(key);
  };

  rows.forEach((row) => {
    const playerA = ensure(row.player_a);
    const playerB = ensure(row.player_b);
    const aWins = Number(row.player_a_wins) || 0;
    const bWins = Number(row.player_b_wins) || 0;
    const totalGames = Number(row.total_games) || 0;
    const lastAt = row.last_played_at || "";

    playerA.wins += aWins;
    playerB.wins += bWins;
    playerA.played += totalGames;
    playerB.played += totalGames;
    if (aWins > 0 && (!playerA.winsAt || lastAt > playerA.winsAt)) playerA.winsAt = lastAt;
    if (bWins > 0 && (!playerB.winsAt || lastAt > playerB.winsAt)) playerB.winsAt = lastAt;
  });

  return [...byName.values()];
}

function mergeChallengeWinLeaderRows(...groups) {
  const byName = new Map();
  groups.flat().filter(Boolean).forEach((row) => {
    const nickname = (row.nickname || "Играч").trim() || "Играч";
    const key = nickname.toLocaleLowerCase("sr");
    const current = byName.get(key) || {
      nickname,
      wins: 0,
      winsAt: "",
      played: 0,
      best: 0,
      bestAt: ""
    };
    current.nickname = current.nickname || nickname;
    current.wins = Math.max(current.wins, Number(row.wins) || 0);
    current.played = Math.max(current.played, Number(row.played) || 0);
    current.best = Math.max(current.best, Number(row.best) || 0);
    const winsAt = row.winsAt || "";
    const bestAt = row.bestAt || "";
    if (winsAt && (!current.winsAt || winsAt > current.winsAt)) current.winsAt = winsAt;
    if (bestAt && (!current.bestAt || bestAt > current.bestAt)) current.bestAt = bestAt;
    byName.set(key, current);
  });
  return [...byName.values()];
}

function challengeStats(rows) {
  const byName = new Map();
  rows.filter(playedChallenge).forEach((row) => {
    const creator = (row.creator || "Играч").trim() || "Играч";
    const opponent = (row.opponent || "Играч").trim() || "Играч";
    const creatorScore = Number(row.creator_score) || 0;
    const opponentScore = Number(row.opponent_score) || 0;
    [creator, opponent].forEach((name) => {
      if (!byName.has(name)) byName.set(name, { nickname: name, wins: 0, winsAt: "", played: 0, best: 0, bestAt: "" });
    });
    const creatorRow = byName.get(creator);
    const opponentRow = byName.get(opponent);
    creatorRow.played += 1;
    opponentRow.played += 1;
    const diff = Math.abs(creatorScore - opponentScore);
    if (creatorScore > opponentScore) {
      creatorRow.wins += 1;
      if (!creatorRow.winsAt) creatorRow.winsAt = row.created_at || "";
      if (diff > creatorRow.best) {
        creatorRow.best = diff;
        creatorRow.bestAt = row.created_at || "";
      }
    }
    if (opponentScore > creatorScore) {
      opponentRow.wins += 1;
      if (!opponentRow.winsAt) opponentRow.winsAt = row.created_at || "";
      if (diff > opponentRow.best) {
        opponentRow.best = diff;
        opponentRow.bestAt = row.created_at || "";
      }
    }
  });
  return [...byName.values()];
}

function medalCard(title, winner, value, suffix = "", image = "", onOpen = null) {
  const card = document.createElement("article");
  card.className = "medal-card";
  if (onOpen) {
    card.tabIndex = 0;
    card.setAttribute("role", "button");
    card.addEventListener("click", onOpen);
    card.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        onOpen();
      }
    });
  }
  const holder = winner || "Још нема";
  const shownValue = value ? `${typeof value === "string" ? value : formatScore(value)}${suffix}` : "-";
  const icon = document.createElement("div");
  icon.className = "medal-icon";
  if (image) {
    const img = document.createElement("img");
    img.src = image;
    img.alt = "";
    icon.append(img);
  } else {
    icon.textContent = "★";
  }
  const copy = document.createElement("div");
  const titleEl = document.createElement("div");
  titleEl.className = "medal-title";
  titleEl.textContent = title;
  const holderEl = document.createElement("div");
  holderEl.className = "medal-holder";
  holderEl.textContent = holder;
  const valueEl = document.createElement("div");
  valueEl.className = "medal-value";
  valueEl.textContent = shownValue;
  copy.append(titleEl, holderEl);
  card.append(icon, copy, valueEl);
  return card;
}

function topMedalRows(items, valueFn, options = {}) {
  return [...items]
    .map((item) => {
      const value = Number(valueFn(item)) || 0;
      return {
        item,
        value,
        sortValue: Number(options.sortFn?.(item, value)) || value,
        displayValue: options.displayFn?.(item, value) || ""
      };
    })
    .filter((row) => row.value > 0)
    .sort((a, b) => {
      if (b.sortValue !== a.sortValue) return b.sortValue - a.sortValue;
      if (b.value !== a.value) return b.value - a.value;
      return String(a.item.nickname || "").localeCompare(String(b.item.nickname || ""), "sr");
    })
    .slice(0, 10);
}

function medalEntry(title, items, valueFn, suffix = "", image = "", dateKey = "", formula = "", options = {}) {
  const top = topMedalRows(items, valueFn, options);
  const firstValue = top[0]?.value || 0;
  const firstSortValue = top[0]?.sortValue || firstValue;
  const firstNames = top
    .filter((row) => row.value === firstValue && row.sortValue === firstSortValue)
    .map((row) => row.item.nickname || "Играч");
  return {
    title,
    result: top[0] || null,
    holder: firstNames.length > 1 ? firstNames.join("/") : firstNames[0],
    suffix,
    image,
    dateKey,
    formula,
    top
  };
}

function medalDisplayValue(entry, suffix = "") {
  if (!entry) return "-";
  return `${entry.displayValue || formatScore(entry.value)}${suffix}`;
}

function renderHallLoading(text = "Учитавање дворане славних...") {
  if (!hallGridEl) return;
  if (hallCarouselEl) hallCarouselEl.innerHTML = "";
  hallGridEl.innerHTML = "";
  hallGridEl.append(medalCard(text, "", 0));
}

function hallMedalDate(result, dateKey) {
  if (!result?.item) return "датум није уписан";
  return formatHallDate(result.item[dateKey] || result.item.created_at || result.item.createdAt);
}

function openHallModal(medalData) {
  if (!hallModal || !hallTopList || !medalData) return;
  const { title, top = [], suffix = "", image = "", formula = "" } = medalData;
  if (hallModalTitle) hallModalTitle.textContent = title;
  if (hallModalHolder) {
    hallModalHolder.textContent = top.length ? `TOP 10 · ${top.length} учесника` : "Још нема резултата";
  }
  if (hallModalImage) {
    hallModalImage.src = image || "";
    hallModalImage.hidden = !image;
  }
  hallTopList.innerHTML = "";
  if (!top.length) {
    const empty = document.createElement("li");
    empty.className = "hall-top-empty";
    empty.textContent = "Још нема учесника за ову медаљу.";
    hallTopList.append(empty);
  } else {
    top.forEach((entry, index) => {
      const row = document.createElement("li");
      const rank = document.createElement("span");
      rank.className = "hall-rank";
      rank.textContent = String(index + 1);
      const name = document.createElement("span");
      name.className = "hall-name";
      name.textContent = entry.item.nickname || "Играч";
      const score = document.createElement("span");
      score.className = "hall-score";
      score.textContent = medalDisplayValue(entry, suffix);
      row.append(rank, name, score);
      hallTopList.append(row);
    });
  }
  if (hallFormula) {
    hallFormula.innerHTML = formula ? `<strong>Начин рачунања</strong>${formula}` : "";
    hallFormula.hidden = !formula;
  }
  hallModal.hidden = false;
}

function closeHallModal() {
  if (hallModal) hallModal.hidden = true;
}

function renderHallCarousel(direction = 0) {
  if (!hallCarouselEl) return;
  hallCarouselEl.innerHTML = "";
  if (!hallMedals.length) return;
  const medalData = hallMedals[hallMedalIndex];
  const { title, result, image, dateKey } = medalData;
  const holder = medalData.holder || result?.item?.nickname || "Још нема";
  const achievedAt = result?.value ? hallMedalDate(result, dateKey) : "датум није уписан";
  const prevButton = document.createElement("button");
  prevButton.className = "hall-arrow prev";
  prevButton.type = "button";
  prevButton.textContent = "‹";
  prevButton.addEventListener("click", () => moveHallMedal(-1));
  const nextButton = document.createElement("button");
  nextButton.className = "hall-arrow next";
  nextButton.type = "button";
  nextButton.textContent = "›";
  nextButton.addEventListener("click", () => moveHallMedal(1));
  const slide = document.createElement("article");
  slide.className = `hall-slide ${direction < 0 ? "from-left" : direction > 0 ? "from-right" : ""}`;
  slide.tabIndex = 0;
  slide.setAttribute("role", "button");
  slide.addEventListener("click", () => openHallModal(medalData));
  slide.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      openHallModal(medalData);
    }
  });
  const medal = document.createElement("div");
  medal.className = "hall-medal-large";
  if (image) {
    const img = document.createElement("img");
    img.src = image;
    img.alt = "";
    medal.append(img);
  } else {
    medal.textContent = String(hallMedalIndex + 1);
  }
  const titleEl = document.createElement("div");
  titleEl.className = "hall-slide-title";
  titleEl.textContent = title;
  const holderEl = document.createElement("div");
  holderEl.className = "hall-slide-holder";
  holderEl.textContent = holder;
  const dateEl = document.createElement("div");
  dateEl.className = "hall-slide-date";
  dateEl.textContent = achievedAt;
  slide.append(medal, titleEl, holderEl, dateEl);
  hallCarouselEl.append(prevButton, slide, nextButton);
}

function moveHallMedal(direction) {
  if (!hallMedals.length) return;
  hallMedalIndex = (hallMedalIndex + direction + hallMedals.length) % hallMedals.length;
  renderHallCarousel(direction);
}

async function renderHallOfFame() {
  if (!hallPanelEl || !hallGridEl) return;
  hallPanelEl.hidden = gameType !== "hall";
  renderHallLoading();
  try {
    const [scoreRows, challengeRows, normalRows, lectorRows, challengeScoreRows, challengeStatsRows] = await Promise.all([
      fetchOnlineLeaderboard(),
      fetchChallengeHistory(),
      fetchNormalStatsRows(),
      fetchLectorStatsRows(),
      fetchChallengeScoreStatsRows().catch(() => []),
      fetchChallengeStatsRows().catch(() => [])
    ]);
    const rows = Array.isArray(scoreRows) ? scoreRows : [];
    const leaderboard = aggregateLeaderboard(rows);
    const challengeRowsSafe = Array.isArray(challengeRows) ? challengeRows : [];
    const onlineChallengeWinRows = normalizeChallengeWinStatsRows(Array.isArray(challengeStatsRows) ? challengeStatsRows : []);
    const challengeLeaders = onlineChallengeWinRows.length
      ? onlineChallengeWinRows
      : challengeStats(challengeRowsSafe);
    const onlineChallengeScoreRows = normalizeChallengeScoreStatsRows(Array.isArray(challengeScoreRows) ? challengeScoreRows : []);
    const challengeStrongLeaders = onlineChallengeScoreRows.length
      ? onlineChallengeScoreRows
      : challengeStrongScoreRows(challengeRowsSafe);
    const normalLeaders = normalSuccessRows(Array.isArray(normalRows) ? normalRows : []);
    const localLector = loadLectorStats();
    const onlineLectorRows = Array.isArray(lectorRows) ? lectorRows : [];
    const localLectorName = loadPlayerName() || "Играч";
    const hasOnlineLector = onlineLectorRows.some((row) => String(row.nickname || "").trim() === localLectorName);
    const localLectorRows = localLector.total && !hasOnlineLector ? [{
      nickname: localLectorName,
      total: localLector.total,
      add_count: localLector.add,
      remove_count: localLector.remove,
      updated_at: localLector.updated_at
    }] : [];
    const lectorLeaders = lectorStatsPersistent([
      ...onlineLectorRows,
      ...localLectorRows
    ]);
    const playerRows = leaderboard.map((row) => row);
    const totalScoreLeaders = playerRows.filter((row) => Number(row.attempts) >= 5);
    const rawScores = bestDailyScoreRows(rows.map((row) => ({
      nickname: (row.nickname || "Играч").trim() || "Играч",
      score: Number(row.score) || 0,
      attempts: Number(row.attempts) || 0,
      wins: Number(row.wins) || 0,
      streak: Number(row.streak) || 0,
      created_at: row.created_at || ""
    })));

    const medals = [
      medalEntry("Највише решених дневних партија", normalLeaders, (row) => row.finished, " партија", "medal-daily-wins.png", "successRateAt", "Сабира се укупан број завршених обичних партија. У листу улазе играчи са најмање 10 започетих обичних партија."),
      medalEntry("Највише добијених изазова", challengeLeaders, (row) => row.wins, " победа", "medal-challenge-wins.png", "winsAt", "Броји се свака победа у одиграном изазову. Нерешени изазови не улазе као победа."),
      medalEntry("Највећи дневни скор", rawScores, (row) => row.score, " поена", "medal-best-daily.png", "created_at", "Гледа се највећи појединачни дневни такмичарски скор који је играч остварио једног дана. Ако исти играч има више уписа, рачуна се само његов најбољи дневни скор."),
      medalEntry("Највећи укупан резултат", totalScoreLeaders, (row) => row.finalScore, " финал", "medal-total-score.png", "finalScoreAt", "Улазе само играчи са најмање 5 одиграних турнира. Рачуна се просек дневних скорова, уз бонус за активне дане и бонус за низ."),
      medalEntry("Највише започетих турнира", playerRows, (row) => row.attempts, " турнир", "medal-started.png", "attemptsAt", "Броји се колико је дневних такмичарских турнира играч започео."),
      medalEntry("Најбоља успешност обичне игре", normalLeaders, (row) => row.successRate, "%", "medal-success-rate.png", "successRateAt", "Рачуна се проценат: завршене обичне партије / започете обичне партије × 100. Улазе играчи са најмање 10 започетих партија."),
      medalEntry("Најдужи низ", playerRows, (row) => row.streak, " дана", "medal-streak.png", "streakAt", "Гледа се најдужи уписани низ дана у којима је играч успешно играо такмичарски део."),
      medalEntry("Највише активних дана", playerRows, (row) => row.playedDays, " дана", "medal-active-days.png", "playedDaysAt", "Броји се број различитих дана у којима је играч имао такмичарски резултат."),
      medalEntry("Најјачи изазов скор", challengeStrongLeaders, (row) => row.best, "", "medal-challenge-score.png", "bestAt", "Гледа се највећа разлика у поенима којом је играч победио у валидном изазову. Ако противник преда, не одигра до краја или има мање од 10 одиграних изазова, тај резултат не улази. Када играч више пута оствари исти најбољи скор, приказује се као 30/2, 30/3 и има предност над једним истим скором.", {
        sortFn: (row) => (Number(row.best) || 0) * 1000 + (Number(row.bestCount) || 0),
        displayFn: (row) => `${formatScore(row.best)}/${formatScore(row.bestCount || 1)}`
      }),
      medalEntry("Лектор", lectorLeaders, (row) => row.total, " пријава", "medal-lector.png", "lastAt", "Сабирају се прихваћене пријаве речи за додавање и за избацивање из базе.")
    ];

    hallGridEl.innerHTML = "";
    hallMedals = medals;
    hallMedalIndex = 0;
    renderHallCarousel();
    medals.forEach((medal) => {
      hallGridEl.append(medalCard(
        medal.title,
        medal.holder || medal.result?.item?.nickname,
        medal.result?.displayValue || medal.result?.value,
        medal.suffix,
        medal.image,
        () => openHallModal(medal)
      ));
    });
  } catch {
    if (hallCarouselEl) hallCarouselEl.innerHTML = "";
    renderHallLoading("Дворана славних тренутно није доступна.");
  }
}

